// KeyBinder is the conventional registry key a main binds the [Binder] under
// (and handlers retrieve it by). The binder is opt-in like every service —
// the generated main binds it only when the spec declares non-argv channels.
const KeyBinder = "binder"

// Binder is the default multi-source input binder: it fills a command's typed
// inputs from argv (flags + positional arguments, via the embedded [Parser]) and
// from the non-argv channels — environment variables and configuration files —
// reconciled and decoded by recon. It is a service, bound like the parser:
//
//	// main.go
//	rth.Program.
//	    Bind(rotini.KeyBinder, rotini.NewBinder(rtg.BindMeta)).
//	    Execute()
//
//	// a handler
//	binder := rotini.MustGet[*rotini.Binder](rtx, rotini.KeyBinder)
//	var in rtg.WidgetCreateInputs
//	if err := binder.Bind(rtx, &in); err != nil { /* handler owns it */ }
//
// Env values fill the generated <Prefix>Env struct (recon's env source maps a
// field's recon key to its SNAKE_UPPER form); config-file values fill <Prefix>Config
// from the document's configuration_files (carried in [BindMeta]). The two
// channels use independent registries, so an env var never leaks into a config field
// or vice versa. Flags may also fall back to env/config, and a leaf command may decode
// a typed stdin payload.
type Binder struct {
	parser       *Parser
	configFiles  []ConfigFile
	stdinSchemas map[string]string // "<Prefix>Stdin" type name → JSON Schema for payload validation
	envPrefix    string            // BindMeta.EnvPrefix: scopes derived env-var names
	sources      []recon.Source    // BindMeta.Sources: custom sources, after the declared files
}

// KeyBindMeta is the registry key the generated NewProgram binds the CLI's
// [BindMeta] descriptor under, so the per-channel functions ([ParseEnv],
// [ParseFiles], [ParseStdin], …) can derive their configuration from the
// [Context] alone. A standalone Context (tests, [NewContextFor]) opts in the
// same way: rtx.Bind(rotini.KeyBindMeta, meta).
const KeyBindMeta = "bindmeta"

// binderFor builds a Binder from the Context's bound BindMeta — the zero meta
// when none is bound, so a CLI with no config files/stdin schemas/env prefix
// needs no ceremony at all.
func binderFor(rtx *Context) *Binder {
	if rtx == nil {
		return NewBinder(BindMeta{}) // the channel layer reports the nil context as a ParseError
	}
	meta, _ := Get[BindMeta](rtx, KeyBindMeta)
	return NewBinder(meta)
}

// NewBinder returns the default binder, configured from the generated descriptor
// (the rtg package's BindMeta var) — its configuration_files sources and per-command
// stdin payload schemas.
func NewBinder(meta BindMeta) *Binder {
	return &Binder{parser: NewParser(), configFiles: meta.ConfigFiles, stdinSchemas: meta.StdinSchemas, envPrefix: meta.EnvPrefix, sources: meta.Sources}
}

// Bind fills out — a non-nil pointer to the typed inputs struct rtg emits — from
// every wired channel: argv flags + positional arguments (via the parser), env- and
// config-file fallbacks for flags that declare them, the pure Env/Config channels,
// and a leaf command's typed stdin payload. Required/enum/constraint validation of
// the argv channel runs once over the fully-reconciled values — so a required flag is
// satisfiable from env or config, not only from argv, and an env/config-supplied value
// is enum-checked. It returns the first error: a [*ParseError] from the argv channel
// (parsing/validation), or a [*BindError] from the env/config/stdin channels — both
// categorized ([CategoryOf]) and non-leaky, with the underlying recon cause reachable
// via errors.As.
func (b *Binder) Bind(rtx *Context, out any) error {
	if b == nil {
		return &ParseError{Kind: ParseKindInternal, Msg: "rotini: nil binder"}
	}
	rv := reflect.ValueOf(out)
	if rv.Kind() != reflect.Pointer || rv.IsNil() {
		return &ParseError{Kind: ParseKindInternal, Msg: "rotini: Bind out argument must be a non-nil pointer to an inputs struct"}
	}

	// 1. argv → Flags + Arguments, WITHOUT validation: required/enum (and, later,
	//    declared constraints) are checked once in step 3, over the fully-reconciled
	//    store, so a required flag can be satisfied by env/config — not only by argv.
	store, chain, err := b.parser.parseBind(rtx, out)
	if err != nil {
		return err
	}
	v := rv.Elem()

	// 1b. two-phase bootstrap: a config_source flag/env names the config file
	//     the file channel then reads (the path is data the argv+env phase owns).
	overrides := b.pathOverrides(chain, store)

	// 2. flag fallback: for flags that declare a recon key, reconcile
	//    argv-set > env (SNAKE_UPPER of the key) > config; otherwise keep the
	//    Parser's value (an explicit argv value or the flag's default). Each
	//    reconciled value is recorded back into the store so step 3 validates it too.
	if err := b.reconcileFlags(v, chain, rtx.Args, store, overrides); err != nil {
		return err
	}

	// 3. validate the reconciled flags + arguments (required + enum) — the single
	//    validation locus for the argv channel, run after fallback so it sees every
	//    source. Argv errors surface before any channel error.
	if err := validate(chain, store); err != nil {
		return err
	}
	if err := validateFlagGroups(chain, store); err != nil {
		return err
	}
	if err := validateFlagDependencies(chain, store); err != nil {
		return err
	}

	// 4. env + config → the Env/Config sub-structs, from independent registries
	//    (so an env var never leaks into a config field, or vice versa); recon
	//    enforces each channel's own required/validator. The env source honors an
	//    input's explicit `variable` (else recon's SNAKE_UPPER).
	envReg, err := recon.New(recon.WithSources(envSources(v, b.envPrefix)...))
	if err != nil {
		return internalBind(channelEnv, "", "could not build the environment registry", err)
	}
	defer envReg.Close()

	cfgRegs, err := b.configRegs(chain, overrides)
	if err != nil {
		return err
	}
	defer cfgRegs.Close()

	if err := fillChannels(v, envReg, cfgRegs); err != nil {
		return err
	}

	// 4b. validate the env/config channel values against their declared constraints
	//     (the same checks A1 applies to argv), over the values actually provided.
	if err := validateChannels(v, envReg, cfgRegs); err != nil {
		return err
	}

	// 5. stdin → the leaf command's typed payload (decoded by its declared format).
	return b.fillStdin(rtx, v)
}

// fillStdin decodes piped stdin into the leaf command's Stdin payload field, when it
// declares one, using its `stdin:"<format>[,required]"` tag. Stdin is a single
// stream, so only the leaf (the running command) consumes it; when nothing is piped
// the Stdin field is left nil — unless the spec marked the payload required, in
// which case an empty stdin is an error. The bytes are read from os.Stdin — see
// readStdin. The decoded payload is validated against the command's stdin JSON
// Schema (from BindMeta) before binding, so a malformed document is rejected with
// a clear error.
func (b *Binder) fillStdin(rtx *Context, v reflect.Value) error {
	if v.Kind() != reflect.Struct || v.NumField() == 0 {
		return nil
	}
	leaf := v.Field(v.NumField() - 1) // the running command's inputs
	if leaf.Kind() != reflect.Struct {
		return nil
	}
	sf := leaf.FieldByName("Stdin")
	field, ok := leaf.Type().FieldByName("Stdin")
	if !sf.IsValid() || sf.Kind() != reflect.Pointer || !ok {
		return nil
	}
	format := field.Tag.Get("stdin")
	if format == "" {
		return nil
	}
	format, required := parseStdinTag(format)

	data, err := readStdin(rtx.Stdin)
	if err != nil {
		return internalBind(channelStdin, "", "could not read stdin", err)
	}
	if len(data) == 0 {
		if required {
			return usageBind(channelStdin, "", fmt.Sprintf("required stdin payload is empty — pipe a %s document", format), nil)
		}
		return nil // nothing piped → leave Stdin nil
	}
	codec, ok := recon.DefaultCodecs().ByName(format)
	if !ok {
		return internalBind(channelStdin, "", fmt.Sprintf("unsupported stdin format %q", format), nil)
	}
	m, err := codec.Decode(data)
	if err != nil {
		return usageBind(channelStdin, "", fmt.Sprintf("could not decode stdin as %s", format), err)
	}

	// Validate the decoded payload against the command's stdin schema (when one was
	// generated for this <Prefix>Stdin type), before binding.
	if js := b.stdinSchemas[sf.Type().Elem().Name()]; js != "" {
		validator, err := recon.NewJSONSchemaValidator([]byte(js))
		if err != nil {
			return internalBind(channelStdin, "", "invalid stdin schema", err)
		}
		if err := validator.Validate(m); err != nil {
			return reconBind(channelStdin, err)
		}
	}

	reg, err := recon.New(recon.WithSource(recon.NewMapSource("stdin", m)))
	if err != nil {
		return internalBind(channelStdin, "", "could not build the stdin registry", err)
	}
	defer reg.Close()

	ptr := reflect.New(sf.Type().Elem()) // *<Prefix>Stdin
	if err := reg.Bind(ptr.Interface()); err != nil {
		return reconBind(channelStdin, err)
	}
	sf.Set(ptr)
	return nil
}

// parseStdinTag splits a generated `stdin:"<format>[,required]"` tag value into
// the decode format and the required marker (the spec's stdin schema declared
// required: true — an empty stdin is then an error rather than a nil payload).
func parseStdinTag(tag string) (format string, required bool) {
	format, opt, _ := strings.Cut(tag, ",")
	return format, opt == "required"
}

// readStdin returns the bytes available on r — the run's stdin ([Context.Stdin], which
// the Program sets from [Program.WithStdin], default os.Stdin). When r is the real
// os.Stdin attached to an interactive terminal it returns nil rather than blocking — a
// stdin channel is for piped/redirected input, not interactive typing. Any other reader
// (e.g. a test's strings.Reader) is read to EOF. A nil reader yields no data.
func readStdin(r io.Reader) ([]byte, error) {
	if r == nil {
		return nil, nil
	}
	if f, ok := r.(*os.File); ok {
		info, err := f.Stat()
		if err != nil {
			return nil, err
		}
		if info.Mode()&os.ModeCharDevice != 0 {
			return nil, nil // an interactive terminal, not a pipe/redirect
		}
	}
	return io.ReadAll(r)
}

// reconcileFlags overrides each fallback flag (a Flags field carrying a recon tag)
// with its reconciled value: argv-set flags (highest) > env (SNAKE_UPPER of the recon
// key) > config files. A flag not present in any source keeps the value the Parser
// already bound (its explicit argv value or declared default). Argv-only flags (no
// recon tag) are untouched. Each reconciled value is also written back into store, so
// the deferred [validate] pass sees an env/config-supplied flag as present (satisfying
// a required check) and range-checks it against any enum.
func (b *Binder) reconcileFlags(v reflect.Value, chain []ResolvedCommand, argv []string, store *parsedInputs, overrides map[string]string) error {
	if v.Kind() != reflect.Struct || !hasReconFlags(v) {
		return nil // no fallback flags → nothing to reconcile (env included)
	}
	offset := len(chain) - v.NumField()
	srcs := []recon.Source{recon.NewMapSource("flags", flagOverrides(v, chain, argv)), flagEnvSource(b.envPrefix)}
	files, err := b.fileSources(b.chainConfigFiles(chain), overrides)
	if err != nil {
		return err
	}
	srcs = append(srcs, files...)
	reg, err := recon.New(recon.WithSources(srcs...))
	if err != nil {
		return internalBind(channelFlag, "", "could not build the flag-fallback registry", err)
	}
	defer reg.Close()

	for i := range v.NumField() {
		flags := commandFlags(v.Field(i))
		if !flags.IsValid() {
			continue
		}
		ft := flags.Type()
		for j := range flags.NumField() {
			key := reconKey(ft.Field(j).Tag.Get("recon"))
			if key == "" {
				continue
			}
			val, found, err := reg.Get(key)
			if err != nil {
				return reconBind(channelFlag, err)
			}
			if !found {
				continue
			}
			// Value.String stringifies any kind (int/float/bool config values too) —
			// the strict AsString returns "" for non-strings, silently dropping a
			// numeric/bool flag's env/config fallback.
			s := val.String()
			coerce(flags.Field(j), []string{s})
			if name := ft.Field(j).Tag.Get("rotini"); name != "" && offset >= 0 {
				recordFlag(store, offset+i, name, s)
			}
		}
	}
	return nil
}

// recordFlag writes a reconciled flag value into the parsed store at its chain frame,
// so deferred validation treats it as present (for required) and enum-checks it.
func recordFlag(store *parsedInputs, idx int, name, value string) {
	if store == nil || idx < 0 || idx >= len(store.scopes) {
		return
	}
	if store.scopes[idx].flags == nil {
		store.scopes[idx].flags = map[string][]string{}
	}
	store.scopes[idx].flags[name] = []string{value}
}

// hasReconFlags reports whether any command's Flags sub-struct declares a recon key
// (i.e. there is at least one env/config fallback flag to reconcile). When false, the
// binder skips building a registry entirely.
func hasReconFlags(v reflect.Value) bool {
	for _, field := range v.Fields() {
		flags := commandFlags(field)
		if !flags.IsValid() {
			continue
		}
		ft := flags.Type()
		for j := range flags.NumField() {
			if reconKey(ft.Field(j).Tag.Get("recon")) != "" {
				return true
			}
		}
	}
	return false
}

// flagOverrides maps the canonical key of every fallback flag explicitly set on
// argv to its (Parser-bound) value — the highest-precedence layer for reconciliation.
func flagOverrides(v reflect.Value, chain []ResolvedCommand, argv []string) map[string]any {
	m := map[string]any{}
	offset := len(chain) - v.NumField()
	if offset < 0 {
		return m
	}
	for i := range v.NumField() {
		flags := commandFlags(v.Field(i))
		if !flags.IsValid() {
			continue
		}
		ft := flags.Type()
		for j := range flags.NumField() {
			key := reconKey(ft.Field(j).Tag.Get("recon"))
			if key == "" {
				continue
			}
			fd, ok := findFlagDef(chain[offset+i].Flags, ft.Field(j).Tag.Get("rotini"))
			if ok && flagWasSet(argv, fd.Identifiers) {
				setNested(m, key, flags.Field(j).Interface())
			}
		}
	}
	return m
}

// setNested stores val at a dotted key path in m, creating nested maps as needed —
// recon resolves a "create.color" path by walking nested maps, so the flag source
// must be nested too (not a flat "create.color" key).
func setNested(m map[string]any, key string, val any) {
	segs := strings.Split(key, ".")
	for _, seg := range segs[:len(segs)-1] {
		next, ok := m[seg].(map[string]any)
		if !ok {
			next = map[string]any{}
			m[seg] = next
		}
		m = next
	}
	m[segs[len(segs)-1]] = val
}

// commandFlags returns the Flags sub-struct of a <Prefix>CommandInputs value, or an
// invalid Value when there is none.
func commandFlags(ci reflect.Value) reflect.Value {
	if ci.Kind() != reflect.Struct {
		return reflect.Value{}
	}
	f := ci.FieldByName("Flags")
	if f.IsValid() && f.Kind() == reflect.Struct {
		return f
	}
	return reflect.Value{}
}

// reconKey extracts the canonical key (the part before the first comma) from a
// recon struct-tag body.
func reconKey(tag string) string {
	if tag == "" {
		return ""
	}
	if before, _, ok := strings.Cut(tag, ","); ok {
		return before
	}
	return tag
}

// reconHasSecret reports whether a recon struct-tag body carries the `secret` option,
// so the channel's value is redacted in constraint-violation errors (recon itself
// redacts it in the errors it raises).
func reconHasSecret(tag string) bool {
	for _, opt := range strings.Split(tag, ",")[1:] {
		if strings.TrimSpace(opt) == "secret" {
			return true
		}
	}
	return false
}

// findFlagDef finds a flag definition by its logical name.
func findFlagDef(defs []FlagDef, name string) (FlagDef, bool) {
	for _, d := range defs {
		if d.Name == name {
			return d, true
		}
	}
	return FlagDef{}, false
}

// flagWasSet reports whether any of a flag's identifiers appears as a flag token in
// argv (exact match; clustered short flags are not detected — a documented edge).
func flagWasSet(argv, identifiers []string) bool {
	for _, tok := range argv {
		if tok == "--" {
			break
		}
		if len(tok) < 2 || tok[0] != '-' {
			continue
		}
		name := tok
		if before, _, ok := strings.Cut(tok, "="); ok {
			name = before
		}
		if slices.Contains(identifiers, name) {
			return true
		}
	}
	return false
}

// configRegistry builds a recon registry over the configuration_files (for the
// pure Config channel), first (highest precedence) to last as declared.
// overrides carries any config_source-supplied paths (see pathOverrides).
func (b *Binder) configRegistry(files []ConfigFile, overrides map[string]string) (*recon.Registry, error) {
	srcs, err := b.fileSources(files, overrides)
	if err != nil {
		return nil, err
	}
	reg, err := recon.New(recon.WithSources(srcs...))
	if err != nil {
		return nil, internalBind(channelConfig, "", "could not build the configuration registry", err)
	}
	return reg, nil
}

// cfgRegs is the config channel's registries for one bind: the merged
// precedence chain, plus lazily-built single-file registries for inputs the
// spec pins to one file (`file:` → the generated cfgfile tag).
type cfgRegs struct {
	binder    *Binder
	files     []ConfigFile // sources in scope for the invoked chain, nearest-wins order
	overrides map[string]string
	merged    *recon.Registry
	perFile   map[string]*recon.Registry
}

// configRegs builds the merged config registry and the lazy per-file cache over
// the sources in scope for chain — the cascade (see [Binder.chainConfigFiles]).
func (b *Binder) configRegs(chain []ResolvedCommand, overrides map[string]string) (*cfgRegs, error) {
	files := b.chainConfigFiles(chain)
	merged, err := b.configRegistry(files, overrides)
	if err != nil {
		return nil, err
	}
	return &cfgRegs{binder: b, files: files, overrides: overrides, merged: merged, perFile: map[string]*recon.Registry{}}, nil
}

// chainConfigFiles returns the config_files in scope for the resolved chain — the
// union along it (D-W3.1) — ordered NEAREST-WINS: the invoked (deepest) command's
// sources first (highest precedence in the merged registry), then each ancestor up
// to the root, preserving each command's own declared order. A source is in scope
// when its Scope is one of the chain's command paths; off-branch sources are
// excluded. An UNSCOPED source (Scope=="" — a manual/legacy global) is always in
// scope, appended last (lowest precedence).
func (b *Binder) chainConfigFiles(chain []ResolvedCommand) []ConfigFile {
	paths := make([]string, len(chain))
	for i := range chain {
		if i == 0 {
			paths[i] = chain[i].Name
		} else {
			paths[i] = paths[i-1] + "/" + chain[i].Name
		}
	}
	var out []ConfigFile
	for _, p := range slices.Backward(paths) { // leaf → root
		for _, f := range b.configFiles {
			if f.Scope == p {
				out = append(out, f)
			}
		}
	}
	for _, f := range b.configFiles {
		if f.Scope == "" {
			out = append(out, f)
		}
	}
	return out
}

// For returns the registry over ONLY the named configuration_files entry —
// what a pinned input's value (and its required) is judged against.
func (c *cfgRegs) For(name string) (*recon.Registry, error) {
	if reg, ok := c.perFile[name]; ok {
		return reg, nil
	}
	for _, f := range c.files {
		if f.Name != name {
			continue
		}
		src, err := c.binder.fileSource(f, c.overrides)
		if err != nil {
			return nil, err
		}
		reg, err := recon.New(recon.WithSource(src))
		if err != nil {
			return nil, internalBind(channelConfig, name, fmt.Sprintf("could not build the registry for configuration file %q", name), err)
		}
		c.perFile[name] = reg
		return reg, nil
	}
	return nil, internalBind(channelConfig, name, fmt.Sprintf("input pinned to unknown configuration file %q", name), nil)
}

// Close closes the merged registry and every per-file registry built so far.
func (c *cfgRegs) Close() {
	c.merged.Close()
	for _, r := range c.perFile {
		r.Close()
	}
}

// bindPinnedConfig re-binds each cfgfile-pinned field of one Config struct
// against ONLY its pinned file's registry — including its recon required,
// which must be judged against that file, not the merged chain. A pinned key
// absent from its file zeroes the field, even when another file holds the key.
func bindPinnedConfig(cs reflect.Value, regs *cfgRegs) error {
	st := cs.Type()
	byFile := map[string][]int{}
	for j := range st.NumField() {
		if name := st.Field(j).Tag.Get("cfgfile"); name != "" {
			byFile[name] = append(byFile[name], j)
		}
	}
	for file, idxs := range byFile {
		reg, err := regs.For(file)
		if err != nil {
			return err
		}
		fields := make([]reflect.StructField, 0, len(idxs))
		for _, j := range idxs {
			f := st.Field(j)
			fields = append(fields, reflect.StructField{Name: f.Name, Type: f.Type, Tag: f.Tag})
		}
		tmp := reflect.New(reflect.StructOf(fields))
		if err := reg.Bind(tmp.Interface()); err != nil {
			return reconBind(channelConfig, err)
		}
		for i, j := range idxs {
			cs.Field(j).Set(tmp.Elem().Field(i))
		}
	}
	return nil
}

// fileSources builds one recon file source per configuration_files entry, in
// declared (precedence) order. Missing files are tolerated; ~ is expanded. An
// entry with a Discover strategy resolves its search directories now (at parse
// time) — the first directory containing the file wins. An entry whose path
// was supplied through config_source (overrides) reads that exact file and is
// NOT optional: the user explicitly asked for it, so a missing file errors.
// Custom BindMeta.Sources follow the declared files — explicit files beat
// ambient services (decided at ergonomics E1/E3-S4).
func (b *Binder) fileSources(files []ConfigFile, overrides map[string]string) ([]recon.Source, error) {
	srcs := make([]recon.Source, 0, len(files)+len(b.sources))
	for _, f := range files {
		src, err := b.fileSource(f, overrides)
		if err != nil {
			return nil, err
		}
		srcs = append(srcs, src)
	}
	return append(srcs, b.sources...), nil
}

// namedSource renames a recon source to its configuration_files logical name.
// FileSource names itself after the file's basename, and registry source names
// must be unique — but two declared entries may legitimately share a basename
// (a walk-up project file and a home file both called ".app.yaml"). The binder
// reads once at parse time, so the wrapper's loss of optional capabilities
// (live watch) costs nothing here.
type namedSource struct {
	recon.Source

	name string
}

func (s namedSource) Name() string { return s.name }

// fileSource builds the recon source for one configuration_files entry, named
// by the entry's logical name.
func (b *Binder) fileSource(f ConfigFile, overrides map[string]string) (recon.Source, error) {
	opts := []recon.FileOption{recon.WithPathExpansion(true)}
	if f.Format != "" {
		opts = append(opts, recon.WithFileFormat(f.Format))
	}
	path, overridden := overrides[f.Name]
	switch {
	case overridden:
		opts = append(opts, recon.WithOptional(false))
	case f.Discover != nil:
		dirs, err := discoverDirs(f.Discover)
		if err != nil {
			return nil, internalBind(channelConfig, f.Name, fmt.Sprintf("could not resolve the search path for configuration file %q", f.Name), err)
		}
		path = f.Discover.File
		opts = append(opts, recon.WithOptional(true), recon.WithSearchPaths(dirs...))
	default:
		path = f.Path
		opts = append(opts, recon.WithOptional(true))
	}
	src, err := recon.NewFileSource(path, opts...)
	if err != nil {
		// The file's content or path is the user's to fix (a config_source
		// override that points at a malformed/unreadable file surfaces here).
		return nil, usageBind(channelConfig, f.Name, fmt.Sprintf("could not open configuration file %q (%s)", f.Name, path), err)
	}
	if err := validateConfigFile(f, src); err != nil {
		return nil, err
	}
	return namedSource{Source: src, name: f.Name}, nil
}

// validateConfigFile checks the loaded document of one configuration_files
// entry against its declared schema (the spec entry's `schema:`) — the same
// load-time gate the stdin channel applies to its payload. The file recon
// actually resolved (after ~ expansion, discovery, or a config_source
// override) is the file validated. An absent optional file passes vacuously:
// document-shape validation gates what IS loaded; absence is the per-input
// `required`'s concern. The extra read happens once per source construction
// and only for entries that declare a schema.
func validateConfigFile(f ConfigFile, src recon.Source) error {
	if f.Schema == "" {
		return nil
	}
	fs, ok := src.(*recon.FileSource)
	if !ok {
		return nil
	}
	path := fs.Path()
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // absent: vacuous
		}
		// A present-but-unreadable file the user controls (permissions, etc.).
		return usageBind(channelConfig, f.Name, fmt.Sprintf("could not read configuration file %q (%s)", f.Name, path), err)
	}
	codec, ok := recon.DefaultCodecs().ByName(fs.Format())
	if !ok {
		return internalBind(channelConfig, f.Name, fmt.Sprintf("unsupported format %q for configuration file %q", fs.Format(), f.Name), nil)
	}
	m, err := codec.Decode(data)
	if err != nil {
		return usageBind(channelConfig, f.Name, fmt.Sprintf("configuration file %q (%s) is not valid %s", f.Name, path, fs.Format()), err)
	}
	validator, err := recon.NewJSONSchemaValidator([]byte(f.Schema))
	if err != nil {
		return internalBind(channelConfig, f.Name, fmt.Sprintf("invalid schema for configuration file %q", f.Name), err)
	}
	if err := validator.Validate(m); err != nil {
		return usageBind(channelConfig, f.Name,
			fmt.Sprintf("configuration file %q (%s) is invalid: %s", f.Name, path, schemaDetail(err)), err)
	}
	return nil
}

// pathOverrides resolves each ConfigFile's config_source inputs (PathFrom) to
// the path they supply, by the documented precedence: the flag explicitly set
// on argv, then the env variable, then the flag's declared default. An entry
// none of them supplies keeps its own path/discover (no map entry).
func (b *Binder) pathOverrides(chain []ResolvedCommand, store *parsedInputs) map[string]string {
	out := map[string]string{}
	for _, f := range b.chainConfigFiles(chain) {
		pf := f.PathFrom
		if pf == nil {
			continue
		}
		explicit, defaulted := storeFlagValue(chain, store, pf.Flag)
		switch {
		case explicit != "":
			out[f.Name] = explicit
		case pf.Env != "" && os.Getenv(pf.Env) != "":
			out[f.Name] = os.Getenv(pf.Env)
		case defaulted != "":
			out[f.Name] = defaulted
		}
	}
	return out
}

// storeFlagValue finds a flag's parsed value by logical name across the chain,
// split by how it got there: explicitly set on argv vs. filled by its default.
// The last value wins for a repeated flag.
func storeFlagValue(chain []ResolvedCommand, store *parsedInputs, name string) (explicit, defaulted string) {
	if name == "" || store == nil {
		return "", ""
	}
	for i := range store.scopes {
		vals := store.scopes[i].flags[name]
		if len(vals) == 0 {
			continue
		}
		if store.setOnArgv(i, name) {
			explicit = vals[len(vals)-1]
		} else {
			defaulted = vals[len(vals)-1]
		}
	}
	return explicit, defaulted
}

// discoverDirs resolves a Discover strategy to the ordered directory list its
// file is searched in. "walk-up" is the working directory up to the filesystem
// root (project-local config, git-style); "xdg" is $XDG_CONFIG_HOME/<app>,
// defaulting to ~/.config/<app>.
func discoverDirs(d *DiscoverDef) ([]string, error) {
	switch d.Strategy {
	case "walk-up":
		dir, err := os.Getwd()
		if err != nil {
			return nil, fmt.Errorf("walk-up discovery: %w", err)
		}
		var dirs []string
		for {
			dirs = append(dirs, dir)
			parent := filepath.Dir(dir)
			if parent == dir {
				return dirs, nil
			}
			dir = parent
		}
	case "xdg":
		// fs.XDGConfigDir is XDG-literal on every platform ($XDG_CONFIG_HOME
		// else ~/.config/<app>) — matching this branch's prior behavior.
		dir, err := fs.XDGConfigDir(d.App)
		if err != nil {
			return nil, fmt.Errorf("xdg discovery: %w", err)
		}
		return []string{dir}, nil
	default:
		return nil, fmt.Errorf("unknown discover strategy %q", d.Strategy)
	}
}

// envSources builds the env channel's recon sources for one inputs value: the
// process environment, with per-input explicit `variable:` names pinned in BOTH
// directions via recon.WithEnvVars (the forward key→variable projection and the
// inverse variable→key parser its enumeration needs), and the optional env
// prefix scoping the convention-named rest. (Nested env families — envnest —
// are not registry data: recon resolves leaf keys only, so fillEnvNested sets
// those fields directly.)
func envSources(v reflect.Value, envPrefix string) []recon.Source {
	opts := []recon.EnvOption{recon.WithEnvVars(envExplicit(v))}
	if envPrefix != "" {
		opts = append(opts, recon.WithEnvPrefix(envPrefix+"_"))
	}
	return []recon.Source{recon.NewOSEnvSource(opts...)}
}

// flagEnvSource is the env source flags' fallbacks read: the plain SNAKE_UPPER
// projection of each recon key, scoped under env_prefix when one is declared
// (recon strips the prefix before parsing and prepends it when projecting).
func flagEnvSource(envPrefix string) recon.Source {
	if envPrefix == "" {
		return recon.NewOSEnvSource()
	}
	return recon.NewOSEnvSource(recon.WithEnvPrefix(envPrefix + "_"))
}

// fillEnvNested fills each nested env input of one Env struct (the generated
// `envnest:"<BASE>,<sep>[,required]"` tag — spec nesting:) directly from its
// variable family: with BASE=ACME_HTTP and sep=__, ACME_HTTP__RETRY__MAX=9
// binds {retry: {max: "9"}}. Segments are lowercased; values stay strings. It
// returns the recon keys it filled (the channel parsers record presence from
// it) and errors on a required family with no variables.
func fillEnvNested(env reflect.Value) (map[string]bool, error) {
	filled := map[string]bool{}
	if env.Kind() != reflect.Struct {
		return filled, nil
	}
	et := env.Type()
	for j := range env.NumField() {
		base, rest, ok := strings.Cut(et.Field(j).Tag.Get("envnest"), ",")
		if !ok || base == "" {
			continue
		}
		sep, opt, _ := strings.Cut(rest, ",")
		fam := envFamily(base, sep)
		if len(fam) == 0 {
			if opt == "required" {
				name := et.Field(j).Tag.Get("rotini")
				return filled, usageBind(channelEnv, name,
					fmt.Sprintf("environment input %q is required — set %s%s* variables", name, base, sep), nil)
			}
			continue
		}
		f := env.Field(j)
		if f.CanSet() && reflect.TypeFor[map[string]any]().AssignableTo(f.Type()) {
			f.Set(reflect.ValueOf(fam))
			filled[reconKey(et.Field(j).Tag.Get("recon"))] = true
		}
	}
	return filled, nil
}

// envFamily collects the BASE<sep>… environment variables into a nested map.
func envFamily(base, sep string) map[string]any {
	out := map[string]any{}
	if sep == "" {
		return out
	}
	prefix := base + sep
	for _, kv := range os.Environ() {
		name, val, ok := strings.Cut(kv, "=")
		if !ok || !strings.HasPrefix(name, prefix) || len(name) == len(prefix) {
			continue
		}
		segs := strings.Split(strings.ToLower(name[len(prefix):]), strings.ToLower(sep))
		setNested(out, strings.Join(segs, "."), val)
	}
	return out
}

// envExplicit collects the recon-key → explicit-env-var mapping from every Env
// field carrying an `env:"<VAR>"` tag (the spec's per-input `variable`), so the env
// source reads that exact variable instead of the SNAKE_UPPER default.
func envExplicit(v reflect.Value) map[string]string {
	m := map[string]string{}
	if v.Kind() != reflect.Struct {
		return m
	}
	for _, ci := range v.Fields() {
		if ci.Kind() != reflect.Struct {
			continue
		}
		env := ci.FieldByName("Env")
		if !env.IsValid() || env.Kind() != reflect.Struct {
			continue
		}
		et := env.Type()
		for j := range env.NumField() {
			vr := et.Field(j).Tag.Get("env")
			if key := reconKey(et.Field(j).Tag.Get("recon")); vr != "" && key != "" {
				m[key] = vr
			}
		}
	}
	return m
}

// fillChannels walks a <Cmd>Inputs struct (one field per command on the resolved
// path) and, for each command's <Prefix>CommandInputs, recon-binds its Env struct
// from envReg and its Config struct from cfgReg via their recon tags.
func fillChannels(v reflect.Value, envReg *recon.Registry, cfg *cfgRegs) error {
	if v.Kind() != reflect.Struct {
		return nil
	}
	for _, ci := range v.Fields() {
		if ci.Kind() != reflect.Struct {
			continue
		}
		t := ci.Type()
		for j := range ci.NumField() {
			switch t.Field(j).Name {
			case "Env":
				if err := envReg.Bind(ci.Field(j).Addr().Interface()); err != nil {
					return reconBind(channelEnv, err)
				}
				if _, err := fillEnvNested(ci.Field(j)); err != nil {
					return err
				}
			case "Config":
				if err := cfg.merged.Bind(ci.Field(j).Addr().Interface()); err != nil {
					return reconBind(channelConfig, err)
				}
				if err := bindPinnedConfig(ci.Field(j), cfg); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// validateChannels enforces the declared numeric/string/array constraints on each
// command's Env and Config fields, reusing the same [checkConstraints] A1 applies to
// argv. It is presence-aware: a field is checked only when its source actually provided
// a value (reg.Get found), so absence is governed by `required` (recon), not by these.
func validateChannels(v reflect.Value, envReg *recon.Registry, cfg *cfgRegs) error {
	if v.Kind() != reflect.Struct {
		return nil
	}
	for _, ci := range v.Fields() {
		if ci.Kind() != reflect.Struct {
			continue
		}
		t := ci.Type()
		for j := range ci.NumField() {
			switch t.Field(j).Name {
			case "Env":
				if err := validateChannelStruct(ci.Field(j), envReg, nil); err != nil {
					return err
				}
			case "Config":
				if err := validateChannelStruct(ci.Field(j), cfg.merged, cfg); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// validateChannelStruct checks every constrained field of an Env/Config sub-struct
// against the value its registry resolved (when present). A cfgfile-pinned
// field is judged against its own file's registry (cfg non-nil for the config
// channel).
func validateChannelStruct(s reflect.Value, reg *recon.Registry, cfg *cfgRegs) error {
	if s.Kind() != reflect.Struct {
		return nil
	}
	st := s.Type()
	for j := range s.NumField() {
		f := st.Field(j)
		c, has := channelConstraints(f.Tag)
		if !has {
			continue
		}
		key := reconKey(f.Tag.Get("recon"))
		if key == "" {
			continue
		}
		fieldReg := reg
		if pin := f.Tag.Get("cfgfile"); pin != "" && cfg != nil {
			var err error
			if fieldReg, err = cfg.For(pin); err != nil {
				return err
			}
		}
		val, found, err := fieldReg.Get(key)
		if err != nil {
			channel := channelEnv
			if cfg != nil {
				channel = channelConfig
			}
			return reconBind(channel, err)
		}
		if !found {
			continue // only provided values are constraint-checked
		}
		typ := channelGoType(s.Field(j).Type())
		label := f.Tag.Get("rotini")
		if label == "" {
			label = key
		}
		if err := checkConstraints(label, typ, c, channelValues(val, typ), reconHasSecret(f.Tag.Get("recon"))); err != nil {
			return err
		}
	}
	return nil
}

// channelConstraints reads the validation struct-tags codegen emits on a channel field
// (min/max/xmin/xmax/multipleof/minlen/maxlen/minitems/maxitems/pattern) into a
// [Constraints]. Tag PRESENCE is what carries a numeric bound's declaredness —
// min:"0" is a real, enforced >= 0.
func channelConstraints(tag reflect.StructTag) (Constraints, bool) {
	var c Constraints
	has := false
	if v := tag.Get("min"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			c.Minimum, has = new(f), true
		}
	}
	if v := tag.Get("max"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			c.Maximum, has = new(f), true
		}
	}
	if v := tag.Get("xmin"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			c.ExclusiveMinimum, has = new(f), true
		}
	}
	if v := tag.Get("xmax"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			c.ExclusiveMaximum, has = new(f), true
		}
	}
	if v := tag.Get("multipleof"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			c.MultipleOf, has = new(f), true
		}
	}
	if v := tag.Get("minlen"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			c.MinLength, has = n, true
		}
	}
	if v := tag.Get("maxlen"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			c.MaxLength, has = n, true
		}
	}
	if v := tag.Get("minitems"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			c.MinItems, has = n, true
		}
	}
	if v := tag.Get("maxitems"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			c.MaxItems, has = n, true
		}
	}
	if v := tag.Get("pattern"); v != "" {
		c.Pattern, has = v, true
	}
	return c, has
}

// channelGoType maps a channel field's Go type to the type string checkConstraints
// expects (numeric bounds apply to int/float, length/pattern to strings, item counts
// to slices).
func channelGoType(t reflect.Type) string {
	switch t.Kind() {
	case reflect.Pointer:
		return channelGoType(t.Elem())
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return "int"
	case reflect.Float32, reflect.Float64:
		return "float64"
	case reflect.Slice:
		return "[]string"
	default:
		return "string"
	}
}

// channelValues renders a reconciled value as the string(s) checkConstraints consumes:
// the elements for an array type, else the single canonical string.
func channelValues(val recon.Value, typ string) []string {
	if isArrayType(typ) {
		if items, err := val.AsSlice(); err == nil {
			out := make([]string, len(items))
			for i, it := range items {
				out[i] = it.String()
			}
			return out
		}
	}
	return []string{val.String()}
}

// The non-argv input channels a [BindError] can report on. They name the
// surface an end-user (or author) reasons about, not recon's internals.
const (
	channelEnv    = "env"
	channelConfig = "config"
	channelStdin  = "stdin"
	channelFlag   = "flag"
)

// BindError reports a failure acquiring or decoding one of a command's non-argv
// input channels — environment variables, configuration files, a typed stdin
// payload, or a flag's env/config fallback. It is the bind channels' answer to
// the argv channel's [*ParseError]: a typed, categorized, NON-LEAKY error a
// funnel can branch on.
//
// Error renders a clean, rotini-owned message (Channel + Input + what went
// wrong); the underlying recon/decode/OS Cause stays reachable via errors.As /
// [errors.Unwrap] but is deliberately kept OUT of the message, so raw recon
// text ("recon: coerce no_styles: string → bool") never reaches a terminal.
// Values are never echoed — a secret can't leak through a BindError's message.
//
// It is categorized through the reused [ErrUsage] / [ErrInternal] sentinels (no
// finer sentinels — the type itself is the structured handle): a bad value, a
// missing-required input, or a malformed document the user supplied is
// [CategoryUsage]; a registry build, a schema compile, an IO read, or a
// codegen/spec mismatch is [CategoryInternal]. Recover the structure with
// errors.As, classify with [CategoryOf] (or errors.Is against the sentinels):
//
//	var be *rotini.BindError
//	if errors.As(err, &be) {
//	    fmt.Fprintf(os.Stderr, "bad %s input %q: %s\n", be.Channel, be.Input, be.Error())
//	}
type BindError struct {
	Channel string // one of "env", "config", "stdin", "flag"
	Input   string // the offending input key/path, when a single one is known (else "")
	Msg     string // a clean, non-leaky, rotini-owned message
	Cause   error  // the underlying recon/decode/OS error, reachable via errors.As (may be nil)

	usage bool // true → CategoryUsage (ErrUsage); false → CategoryInternal
}

func (e *BindError) Error() string { return e.Msg }

// Unwrap exposes the [Cause] (when present) and the category sentinel via
// multi-unwrap, so errors.Is/As reach both the original recon error and
// [ErrUsage]/[ErrInternal] — while [Error] stays the clean message, adding no
// recon text.
func (e *BindError) Unwrap() []error {
	sentinel := ErrInternal
	if e.usage {
		sentinel = ErrUsage
	}
	if e.Cause == nil {
		return []error{sentinel}
	}
	return []error{e.Cause, sentinel}
}

// usageBind builds a [CategoryUsage] *BindError — bad input the end-user can fix.
func usageBind(channel, input, msg string, cause error) *BindError {
	return &BindError{Channel: channel, Input: input, Msg: msg, Cause: cause, usage: true}
}

// internalBind builds a [CategoryInternal] *BindError — a registry/IO/schema/
// codegen failure the program author must fix.
func internalBind(channel, input, msg string, cause error) *BindError {
	return &BindError{Channel: channel, Input: input, Msg: msg, Cause: cause}
}

// reconBind converts a recon Bind/Get/Validate error for one channel into a
// clean, categorized [*BindError]. It inspects recon's typed errors to name the
// offending input and phrase a non-leaky message, keeping the whole error as
// the Cause so errors.As still reaches every recon field. Recognized failures
// (coercion, missing-required, validation, empty) are usage-class; an
// unrecognized recon error becomes a generic usage-class channel failure (a
// channel value the user supplied could not be used) — its detail stays
// reachable via the Cause.
func reconBind(channel string, err error) error {
	if err == nil {
		return nil
	}
	noun := channelNoun(channel)
	var ce *recon.CoercionError
	var mre *recon.MissingRequiredError
	var ve *recon.ValidationError
	var eve *recon.EmptyValueError
	switch {
	case errors.As(err, &ce):
		return usageBind(channel, ce.Path.String(),
			fmt.Sprintf("%s %q: expected %s", noun, ce.Path.String(), cleanType(ce.Target)), err)
	case errors.As(err, &mre):
		return usageBind(channel, mre.Path.String(),
			fmt.Sprintf("%s %q is required", noun, mre.Path.String()), err)
	case errors.As(err, &ve):
		return usageBind(channel, ve.Path.String(),
			fmt.Sprintf("%s %q: %s", noun, ve.Path.String(), ve.Msg), err)
	case errors.As(err, &eve):
		return usageBind(channel, eve.Path.String(),
			fmt.Sprintf("%s %q must not be empty", noun, eve.Path.String()), err)
	default:
		return usageBind(channel, "", fmt.Sprintf("could not read %s input", channelDesc(channel)), err)
	}
}

// channelNoun names a single input on a channel, for per-input messages.
func channelNoun(channel string) string {
	switch channel {
	case channelEnv:
		return "environment variable"
	case channelConfig:
		return "config key"
	case channelStdin:
		return "stdin field"
	default:
		return "flag"
	}
}

// channelDesc names the channel as a whole, for generic messages.
func channelDesc(channel string) string {
	switch channel {
	case channelEnv:
		return "environment"
	case channelConfig:
		return "configuration"
	case channelStdin:
		return "stdin"
	default:
		return "flag"
	}
}

// schemaDetail extracts a clean, non-leaky detail from a recon schema
// [recon.ValidationError] — the property/rule it names, redacted by recon when
// secret — falling back to a generic phrase when the cause is some other error,
// so the document-shape message never echoes raw recon text.
func schemaDetail(err error) string {
	if ve, ok := errors.AsType[*recon.ValidationError](err); ok {
		if ve.Path.String() != "" {
			return fmt.Sprintf("%s: %s", ve.Path.String(), ve.Msg)
		}
		return ve.Msg
	}
	return "does not match its schema"
}

// channelForStruct maps a generated channel sub-struct name ("Env"/"Config"/
// "Stdin") to its [BindError] channel label.
func channelForStruct(structName string) string {
	switch structName {
	case "Config":
		return channelConfig
	case "Stdin":
		return channelStdin
	default:
		return channelEnv
	}
}

// cleanType renders a recon target Go type for an end-user message: a nullable
// scalar's pointer star is noise here (the user supplies a value, not a
// pointer), so it is trimmed.
func cleanType(t string) string { return strings.TrimPrefix(t, "*") }

// Category classifies an error by whose fault it is, so the funnel can decide the
// exit code and message style from a single call to [CategoryOf] — rather than every CLI
// re-deriving the taxonomy. rotini tags its
// OWN errors (a missing service is [CategoryInternal]; a parse/bind failure is
// [CategoryUsage]); user code tags its domain errors with [UsageError] / [InternalError].
//
// rotini labels; a funnel decides what to do with the label. rotini holds no
// named exit-code constants and forces no category→code mapping (Pillar 1): its
// DEFAULT funnel exits 1 for any recorded error or fault (a recorded run never
// exits 0). A program that wants to map categories to distinct codes does so in
// its own [Program.WithFunnel] via rtx.Exit.
type Category int

const (
	// CategoryNone is an unclassified error — a plain error rotini cannot attribute.
	CategoryNone Category = iota
	// CategoryUsage is bad input from the end-user: an unknown flag, a missing required
	// argument, a value that fails validation. The user can fix it by changing the command.
	CategoryUsage
	// CategoryInternal is a bug or misconfiguration in the program: a missing bound
	// service, a wiring mistake. The end-user cannot fix it; the author must.
	CategoryInternal
)

// String renders the category as a short, stable label.
func (c Category) String() string {
	switch c {
	case CategoryUsage:
		return "usage"
	case CategoryInternal:
		return "internal"
	default:
		return "none"
	}
}

// ErrUsage and ErrInternal are the sentinels the categories match on. rotini's own
// errors wrap the appropriate one, and [CategoryOf] resolves a category by testing an
// error against them with errors.Is — so a funnel may match either way:
//
//	if errors.Is(err, rotini.ErrUsage) { /* usage */ }
//	switch rotini.CategoryOf(err) { case rotini.CategoryUsage: /* usage */ }
//
// Prefer the [UsageError] / [InternalError] constructors over wrapping these with
// fmt.Errorf("%w", …) directly: the constructors tag the category WITHOUT prepending the
// sentinel's text to your message.
var (
	ErrUsage    = errors.New("rotini: usage error")
	ErrInternal = errors.New("rotini: internal error")
)

// CategoryOf returns the [Category] an error carries — [CategoryUsage] or
// [CategoryInternal] when it (or anything it wraps) matches [ErrUsage] / [ErrInternal],
// else [CategoryNone] (including for a nil error). It is the single classification call a
// funnel makes:
//
//	func onError(ctx context.Context, rtx *rotini.Context, err error) {
//	    switch rotini.CategoryOf(err) {
//	    case rotini.CategoryUsage:    fmt.Fprintln(rtx.Stderr, err); rtx.SignalExit(1)
//	    case rotini.CategoryInternal: report(err); rtx.SignalExit(70)
//	    default:                      fmt.Fprintln(rtx.Stderr, err); rtx.SignalExit(1)
//	    }
//	}
func CategoryOf(err error) Category {
	switch {
	case err == nil:
		return CategoryNone
	case errors.Is(err, ErrUsage):
		return CategoryUsage
	case errors.Is(err, ErrInternal):
		return CategoryInternal
	default:
		return CategoryNone
	}
}

// UsageError tags err as a [CategoryUsage] error — bad input the end-user can correct —
// without altering its message: the returned error reads exactly like err but matches
// [ErrUsage] (and so [CategoryOf] reports [CategoryUsage]). errors.Is/As still see through
// to err. It returns nil when err is nil.
//
//	if id == "" {
//	    return rotini.UsageError(fmt.Errorf("a widget id is required"))
//	}
func UsageError(err error) error { return categorize(err, ErrUsage) }

// InternalError tags err as a [CategoryInternal] error — a bug or misconfiguration —
// without altering its message. It returns nil when err is nil.
func InternalError(err error) error { return categorize(err, ErrInternal) }

func categorize(err, sentinel error) error {
	if err == nil {
		return nil
	}
	return &categorized{err: err, sentinel: sentinel}
}

// categorized tags an error with a category sentinel via multi-unwrap, so errors.Is finds
// both the original error and the sentinel — while Error() delegates to the original, so
// the category adds no text to the message.
type categorized struct {
	err      error
	sentinel error
}

func (c *categorized) Error() string   { return c.err.Error() }
func (c *categorized) Unwrap() []error { return []error{c.err, c.sentinel} }

type ANSIColor int

const (
	ANSIColorBlack ANSIColor = iota
	ANSIColorRed
	ANSIColorGreen
	ANSIColorYellow
	ANSIColorBlue
	ANSIColorMagenta
	ANSIColorCyan
	ANSIColorWhite
	ANSIColorBrightBlack
	ANSIColorBrightRed
	ANSIColorBrightGreen
	ANSIColorBrightYellow
	ANSIColorBrightBlue
	ANSIColorBrightMagenta
	ANSIColorBrightCyan
	ANSIColorBrightWhite
)

type Profile int

const (
	ProfileNoColor Profile = iota
	ProfileANSI16
	ProfileANSI256
	ProfileTrueColor
)

type color interface {
	sgr(profile Profile, background bool) string
}

type colorANSI ANSIColor

func (c colorANSI) sgr(profile Profile, background bool) string {
	if profile == ProfileNoColor {
		return ""
	}
	base := 30
	if background {
		base = 40
	}
	return strconv.Itoa(colorSGR(ANSIColor(c), base))
}

type color256 uint8

func (c color256) sgr(profile Profile, background bool) string {
	switch profile {
	case ProfileNoColor:
		return ""
	case ProfileANSI16:
		return colorANSI(code256To16(uint8(c))).sgr(profile, background)
	default:
		prefix := "38;5;"
		if background {
			prefix = "48;5;"
		}
		return prefix + strconv.Itoa(int(c))
	}
}

type colorRGB struct {
	r, g, b uint8
}

func (c colorRGB) sgr(profile Profile, background bool) string {
	switch profile {
	case ProfileNoColor:
		return ""
	case ProfileANSI16:
		return colorANSI(rgbTo16(c.r, c.g, c.b)).sgr(profile, background)
	case ProfileANSI256:
		return color256(rgbTo256(c.r, c.g, c.b)).sgr(profile, background)
	default:
		prefix := "38;2;"
		if background {
			prefix = "48;2;"
		}
		return prefix + strconv.Itoa(int(c.r)) + ";" + strconv.Itoa(int(c.g)) + ";" + strconv.Itoa(int(c.b))
	}
}

func colorSGR(color ANSIColor, base int) int {
	if color >= ANSIColorBrightBlack {
		return base + 60 + int(color) - int(ANSIColorBrightBlack)
	}
	return base + int(color)
}

// palette16 holds the conventional xterm RGB values for the sixteen ANSI colors,
// used to pick the nearest palette entry when downsampling to ProfileANSI16.
var palette16 = [16][3]uint8{
	{0, 0, 0}, {205, 0, 0}, {0, 205, 0}, {205, 205, 0},
	{0, 0, 238}, {205, 0, 205}, {0, 205, 205}, {229, 229, 229},
	{127, 127, 127}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0},
	{92, 92, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
}

var cubeLevels = [6]uint8{0, 95, 135, 175, 215, 255}

func code256ToRGB(code uint8) (red, green, blue uint8) {
	switch {
	case code < 16:
		p := palette16[code]
		return p[0], p[1], p[2]
	case code < 232:
		c := code - 16
		return cubeLevels[c/36], cubeLevels[(c%36)/6], cubeLevels[c%6]
	default:
		v := uint8(8 + (int(code)-232)*10)
		return v, v, v
	}
}

func colorDistance(r1, g1, b1, r2, g2, b2 uint8) int {
	dr, dg, db := int(r1)-int(r2), int(g1)-int(g2), int(b1)-int(b2)
	return dr*dr + dg*dg + db*db
}

func rgbTo256(red, green, blue uint8) uint8 {
	best, bestDistance := uint8(16), math.MaxInt
	for code := 16; code <= 255; code++ {
		cr, cg, cb := code256ToRGB(uint8(code))
		if d := colorDistance(red, green, blue, cr, cg, cb); d < bestDistance {
			best, bestDistance = uint8(code), d
		}
	}
	return best
}

func rgbTo16(red, green, blue uint8) ANSIColor {
	best, bestDistance := 0, math.MaxInt
	for code, p := range palette16 {
		if d := colorDistance(red, green, blue, p[0], p[1], p[2]); d < bestDistance {
			best, bestDistance = code, d
		}
	}
	return ANSIColor(best)
}

func code256To16(code uint8) ANSIColor {
	return rgbTo16(code256ToRGB(code))
}

func parseHex(hex string) (red, green, blue uint8, ok bool) {
	hex = strings.TrimPrefix(hex, "#")
	if len(hex) == 3 {
		hex = string([]byte{hex[0], hex[0], hex[1], hex[1], hex[2], hex[2]})
	}
	if len(hex) != 6 {
		return 0, 0, 0, false
	}
	value, err := strconv.ParseUint(hex, 16, 32)
	if err != nil {
		return 0, 0, 0, false
	}
	return uint8(value >> 16), uint8(value >> 8), uint8(value), true
}

// completeCommand is the hidden sub-command the generated shell scripts call to
// ask the binary for completion candidates.
const completeCommand = "__complete"

// FlagValueCompleter is an optional interface a command's handler may implement to
// supply dynamic completion candidates for one of its flags' values. When the hidden
// __complete entry is completing a flag value, it resolves the handler of the command
// that *declares* that flag (the same handler reflection dispatch uses) and, if it
// implements this interface, calls CompleteFlagValue with the flag's logical Name and
// the word being typed. A nil return falls back to the flag's static enum; a non-nil
// (possibly empty) return is authoritative. rtx carries the resolved chain
// (rtx.Chain()), the completion words (rtx.Args), and every service bound on the
// Program, so a completer can reach a bound API client, the filesystem, etc.
//
// It is entirely opt-in — rotini generates no stub for it and adds nothing if it is
// absent — and, like any user callback, a panic in it is the caller's
// bug, not recovered. It may be called on every keystroke, so it must be read-only and
// fast.
//
// A returned candidate MAY carry a one-line description after a tab —
// "value\tdescription", the same wire shape command and flag candidates use:
// zsh/fish/powershell render it beside the value, bash strips it. Bare values
// stay bare; nothing breaks when descriptions are absent.
type FlagValueCompleter interface {
	CompleteFlagValue(rtx *Context, flag, partial string) []string
}

// ArgValueCompleter is the positional-argument counterpart of
// [FlagValueCompleter]: a command's handler may implement it to supply dynamic
// completion candidates for one of its arguments' values. When the hidden
// __complete entry is completing a positional, it resolves the handler of the
// command being invoked and, if it implements this interface, calls
// CompleteArgValue with the argument's logical Name and the word being typed. A
// nil return falls back to the argument's static enum; a non-nil (possibly
// empty) return is authoritative. The same opt-in, read-only, called-on-every-
// keystroke contract as FlagValueCompleter applies — including the optional
// "value\tdescription" candidate shape.
type ArgValueCompleter interface {
	CompleteArgValue(rtx *Context, arg, partial string) []string
}

// completionContext is the dispatch-faithful reading of the words preceding the
// one being completed: the resolved command chain, how many positional
// arguments the leaf has already consumed, and whether a "--" terminator has
// ended flag handling. It mirrors resolveChain (value-aware flag skipping,
// descent stops at the first positional) so completion predicts exactly what
// dispatch would do with the same words.
type completionContext struct {
	chain           []ResolvedCommand
	positionals     int
	afterTerminator bool
	remote          bool // a remote/plugin token was hit: the rest belongs to the dispatched binary
}

// complete returns the completion candidates for the word currently being typed
// (the last element of words; the rest are the preceding context). It completes
// flag values (dynamic completer, else enum), flag names (when the word starts
// with "-", including the inline "--flag=val" form), sub-command and
// remote-command names, and positional-argument values (dynamic completer, else
// enum) — all filtered by the typed prefix and excluding hidden inputs. An
// empty result lets the shell apply its own default (typically file names).
func complete(def Definition, words []string, handlers any, rtx *Context) []string {
	if len(words) == 0 {
		words = []string{""}
	}
	partial := words[len(words)-1]
	context := words[:len(words)-1]

	cc := walkContext(def, context)
	if cc.remote {
		return nil // the remote binary owns its own argument surface
	}
	cur := cc.chain[len(cc.chain)-1]
	if cur.Passthrough {
		return nil // raw tokens past the boundary: let the shell fall back to files
	}

	// Completing the value of the preceding flag (the separate-word form,
	// including bash's "--flag = val" word splitting). The handler of the command
	// that declares the flag may supply dynamic candidates (FlagValueCompleter);
	// a nil return (or no completer) falls back to the flag's static enum, and an
	// empty result lets the shell fall back to file completion — never to
	// sub-command names, which dispatch would treat as this flag's value.
	if !cc.afterTerminator {
		if name, ok := pendingValueFlag(context); ok {
			if fd, owner, found := findFlag(cc.chain, name); found && takesValue(fd) {
				return filterPrefix(flagValueCandidates(handlers, rtx, cc.chain, words, owner, fd, partial), partial)
			}
		}
	}

	// Completing a flag name — or, with an inline "=", a flag's value. Only
	// declared, non-hidden flags are offered — rotini auto-adds no flags, so
	// `-h`/`--help` appear here exactly when the CLI declares them, not by
	// framework injection. The whole chain contributes: ancestor flags resolve on
	// descendants at runtime.
	if !cc.afterTerminator && strings.HasPrefix(partial, "-") {
		if name, val, hasInline := splitFlag(partial); hasInline {
			if fd, owner, found := findFlag(cc.chain, name); found && takesValue(fd) {
				cands := flagValueCandidates(handlers, rtx, cc.chain, words, owner, fd, val)
				out := make([]string, 0, len(cands))
				for _, c := range cands {
					out = append(out, name+"="+c)
				}
				return filterPrefix(out, partial)
			}
			return nil
		}
		var ids []string
		for _, v := range slices.Backward(cc.chain) {
			for _, f := range v.Flags {
				if !f.Hidden {
					for _, id := range f.Identifiers {
						ids = append(ids, withDescription(id, f.Summary))
					}
				}
			}
		}
		return filterPrefix(ids, partial)
	}

	// Completing a positional word. Until the first positional is consumed it may
	// also be a sub-command / remote-command / discovered plugin; afterwards
	// dispatch no longer descends, so only argument values remain.
	var names []string
	if !cc.afterTerminator && cc.positionals == 0 {
		for _, c := range cur.Commands {
			if c.Hidden {
				continue
			}
			names = append(names, withDescription(c.Name, c.Summary))
			for _, a := range c.Aliases {
				names = append(names, withDescription(a, c.Summary))
			}
		}
		for _, r := range cur.Remotes {
			names = append(names, withDescription(r.Name, r.Summary))
			for _, a := range r.Aliases {
				names = append(names, withDescription(a, r.Summary))
			}
		}
		names = append(names, DiscoveredPlugins(cur)...)
	}
	names = append(names, argValueCandidates(handlers, rtx, cc, words, partial)...)
	return filterPrefix(names, partial)
}

// walkContext resolves the words preceding the completed one with dispatch's
// semantics (see resolveChain), leniently: unknown tokens are positionals, not
// errors. bash splits "--flag=value" on "=" into three words; the literal "="
// token glues such a value back onto its flag.
func walkContext(def Definition, context []string) completionContext {
	cc := completionContext{chain: []ResolvedCommand{rootFrame(def)}}
	for i := 0; i < len(context); i++ {
		tok := context[i]
		if cc.afterTerminator {
			cc.positionals++
			continue
		}
		if tok == "--" {
			cc.afterTerminator = true
			continue
		}
		if tok == "=" {
			if i > 0 && isFlag(context[i-1]) {
				i++ // the glued value (when present) belongs to the preceding flag
			}
			continue
		}
		if isFlag(tok) {
			name, _, hasInline := splitFlag(tok)
			// Skip a separate value token so it is not mistaken for a command —
			// unless it is the "=" glue, which the next iteration handles.
			if fd, _, ok := findFlag(cc.chain, name); ok && takesValue(fd) && !hasInline {
				if i+1 < len(context) && context[i+1] != "=" {
					i++
				}
			}
			continue
		}
		cur := cc.chain[len(cc.chain)-1]
		if cc.positionals == 0 {
			if child, ok := findChild(cur, tok); ok {
				cc.chain = append(cc.chain, cmdFrame(child))
				continue
			}
			if _, ok := findRemote(cur, tok); ok || cur.Discovery != nil {
				cc.remote = true
				return cc
			}
		}
		cc.positionals++
	}
	return cc
}

// pendingValueFlag reports the flag whose value the next word supplies, when
// the context ends with a flag awaiting one: a bare flag token, or a flag
// followed by bash's "=" split token.
func pendingValueFlag(context []string) (string, bool) {
	if len(context) == 0 {
		return "", false
	}
	last := context[len(context)-1]
	if last == "=" && len(context) >= 2 && isFlag(context[len(context)-2]) {
		name, _, _ := splitFlag(context[len(context)-2])
		return name, true
	}
	if isFlag(last) {
		if name, _, hasInline := splitFlag(last); !hasInline {
			return name, true
		}
	}
	return "", false
}

// flagValueCandidates returns the candidates for one flag's value: the owning
// handler's dynamic completer when it answers, else a map flag's declared key
// vocabulary (completed up to the '='), else the flag's static enum, else
// nothing (so the shell falls back to its default completion).
func flagValueCandidates(handlers any, rtx *Context, chain []ResolvedCommand, words []string, owner string, fd FlagDef, partial string) []string {
	// An '@' on a from:file flag is a path in progress — offer nothing, so the
	// shell falls back to its own file completion.
	if strings.HasPrefix(partial, "@") && slices.Contains(fd.From, "file") {
		return nil
	}
	if cands, dyn := dynamicFlagValues(handlers, rtx, chain, words, owner, fd.Name, partial); dyn {
		return cands
	}
	if len(fd.KeyPaths) > 0 && isMapType(fd.Type) && !strings.Contains(partial, "=") {
		keys := make([]string, len(fd.KeyPaths))
		for i, k := range fd.KeyPaths {
			keys[i] = k + "=" // the value past the '=' is the user's to write
		}
		return keys
	}
	return fd.Enum
}

// argValueCandidates returns the candidates for the positional argument the
// completed word would bind to — the argument at the leaf's next positional
// index (the trailing variadic argument absorbs everything past the end). The
// leaf handler's dynamic completer (ArgValueCompleter) wins when it answers,
// else the argument's static enum; hidden arguments offer nothing.
func argValueCandidates(handlers any, rtx *Context, cc completionContext, words []string, partial string) []string {
	cur := cc.chain[len(cc.chain)-1]
	args := cur.Arguments
	idx := cc.positionals
	if idx >= len(args) {
		if len(args) == 0 || !args[len(args)-1].Variadic {
			return nil
		}
		idx = len(args) - 1
	}
	ad := args[idx]
	if ad.Hidden {
		return nil
	}
	if cands, dyn := dynamicArgValues(handlers, rtx, cc.chain, words, ad.Name, partial); dyn {
		return cands
	}
	return ad.Enum
}

// DiscoveredPlugins returns the names of the plugins discovered for cmd's
// remote-discovery config — the token each plugin is invoked by (e.g. "foo" for an
// executable "<prefix>foo" found next to the binary, in the discovery path, or on
// PATH) — with any name that collides with a declared sub-command, remote command, or
// alias removed (the declared one wins, exactly as dispatch resolves it). It returns
// nil when cmd has no discovery or discovery is hidden. Results are deduped and sorted.
//
// This is the data feed for surfacing runtime plugins in help. A program's help is
// generated at codegen time and cannot know which plugins exist at runtime, so a help
// handler that wants to list them reads the relevant command's discovery from
// [Context.Chain] and calls this, then formats the result however it likes — rotini
// renders nothing itself (Pillar 1). For example, in a `--help` handler:
//
//	chain := rtx.Chain()
//	for _, name := range rotini.DiscoveredPlugins(chain[len(chain)-1]) {
//		fmt.Fprintf(out, "  %s\n", name)
//	}
//
// It touches the filesystem (reading the candidate directories) on every call and is
// best-effort: an unreadable directory contributes nothing rather than erroring. To learn
// whether the author-configured discovery path itself failed, call [DiscoveryDiagnostics].
func DiscoveredPlugins(cmd ResolvedCommand) []string {
	plugins, _ := discoveredFor(cmd)
	return plugins
}

// DiscoveryDiagnostics returns the problems encountered while scanning cmd's
// author-configured discovery path (remote_discovery.path) for plugins — typically the
// path is missing or unreadable. It returns nil when cmd has no discovery, discovery is
// hidden, none is configured, or the configured path scanned cleanly. Incidental
// locations — next to the binary and the entries of $PATH — are deliberately NOT reported:
// a missing $PATH entry is normal, not a misconfiguration.
//
// It is the data feed for a health/`doctor` or completion handler that wants to tell the
// author their discovery path is wrong. rotini surfaces the problem as data and prints no
// warning itself — auto-printing here would both corrupt completion output and impose
// behavior (Pillar 1). The handler decides whether and how to report it. Each error
// carries the offending path and cause, so a caller can classify with
// errors.Is(err, fs.ErrNotExist). Like [DiscoveredPlugins] it touches the filesystem on
// each call.
func DiscoveryDiagnostics(cmd ResolvedCommand) []error {
	_, problems := discoveredFor(cmd)
	return problems
}

// discoveredFor returns cmd's discovered plugin tokens (collision-filtered against its
// declared sub-commands and remotes) plus any problems scanning the author-configured
// discovery path. It is the shared core of [DiscoveredPlugins] and [DiscoveryDiagnostics].
func discoveredFor(cmd ResolvedCommand) ([]string, []error) {
	d := cmd.Discovery
	if d == nil || d.Hidden {
		return nil, nil
	}
	declared := map[string]bool{}
	for _, c := range cmd.Commands {
		declared[c.Name] = true
		for _, a := range c.Aliases {
			declared[a] = true
		}
	}
	for _, r := range cmd.Remotes {
		declared[r.Name] = true
		for _, a := range r.Aliases {
			declared[a] = true
		}
	}
	all, problems := discoverPlugins(d)
	var out []string
	for _, plugin := range all {
		if !declared[plugin] {
			out = append(out, plugin)
		}
	}
	return out, problems
}

// dynamicFlagValues asks the handler of the command that declares the flag (owner) for
// completion candidates, when it implements FlagValueCompleter. It returns (candidates,
// true) only when a completer ran and returned a non-nil slice — the authoritative
// result; otherwise (nil, false), so the caller falls back to the static enum. handlers
// is the aggregate handler set (nil in pure-structural callers/tests); the owner's
// handler is resolved by the same reflection dispatch uses. rtx is seeded with the
// resolved chain and completion words so the completer can inspect them and reach bound
// services.
func dynamicFlagValues(handlers any, rtx *Context, chain []ResolvedCommand, words []string, owner, flag, partial string) ([]string, bool) {
	var handlerName string
	for _, fr := range chain {
		if fr.Name == owner {
			handlerName = fr.Handler
			break
		}
	}
	completer, ok := resolveHandler[FlagValueCompleter](handlers, handlerName)
	if !ok {
		return nil, false
	}
	seedCompletionContext(rtx, chain, words)
	cands := completer.CompleteFlagValue(rtx, flag, partial)
	if cands == nil {
		return nil, false
	}
	return cands, true
}

// dynamicArgValues is dynamicFlagValues' positional counterpart: it asks the
// handler of the command being invoked (the chain leaf — positionals always
// bind to the leaf) for candidates, when it implements ArgValueCompleter.
func dynamicArgValues(handlers any, rtx *Context, chain []ResolvedCommand, words []string, arg, partial string) ([]string, bool) {
	completer, ok := resolveHandler[ArgValueCompleter](handlers, chain[len(chain)-1].Handler)
	if !ok {
		return nil, false
	}
	seedCompletionContext(rtx, chain, words)
	cands := completer.CompleteArgValue(rtx, arg, partial)
	if cands == nil {
		return nil, false
	}
	return cands, true
}

// resolveHandler resolves handlerName on the aggregate handler set — the same
// reflection dispatch uses — and reports whether the handler implements T.
func resolveHandler[T any](handlers any, handlerName string) (T, bool) {
	var zero T
	if handlers == nil || handlerName == "" {
		return zero, false
	}
	m := reflect.ValueOf(handlers).MethodByName(handlerName)
	if !m.IsValid() || m.Type().NumIn() != 0 || m.Type().NumOut() != 1 {
		return zero, false
	}
	completer, ok := m.Call(nil)[0].Interface().(T)
	return completer, ok
}

// seedCompletionContext hands the resolved chain and completion words to the
// context a dynamic completer receives, so it can inspect them and reach bound
// services.
func seedCompletionContext(rtx *Context, chain []ResolvedCommand, words []string) {
	if rtx != nil {
		rtx.chain = chain
		rtx.Args = words
	}
}

// discoverPlugins lists the names (the part after the prefix) of `<prefix>*`
// executables found next to the host binary, in d.Path, and on PATH — the candidates
// plugin discovery exposes — deduped and sorted. It also returns any errors scanning the
// author-configured d.Path (a missing or unreadable path); failures scanning the
// incidental locations (the binary's own dir, $PATH entries) are ignored as normal.
func discoverPlugins(d *RemoteDiscoveryDef) ([]string, []error) {
	if d.Prefix == "" {
		return nil, nil
	}
	seen := map[string]bool{}
	var out []string
	var problems []error
	scan := func(dir string, report bool) {
		entries, err := os.ReadDir(dir)
		if err != nil {
			if report {
				problems = append(problems, err)
			}
			return
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			name := e.Name()
			if name == d.Prefix || !strings.HasPrefix(name, d.Prefix) {
				continue
			}
			plugin := strings.TrimPrefix(name, d.Prefix)
			if seen[plugin] {
				continue
			}
			seen[plugin] = true
			out = append(out, plugin)
		}
	}
	if exe, err := os.Executable(); err == nil {
		scan(filepath.Dir(exe), false)
	}
	if d.Path != "" {
		scan(d.Path, true) // the author-configured path: a scan failure is a real diagnostic
	}
	for _, dir := range filepath.SplitList(os.Getenv("PATH")) {
		if dir != "" {
			scan(dir, false)
		}
	}
	sort.Strings(out)
	return out, problems
}

func filterPrefix(candidates []string, prefix string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(candidates))
	for _, c := range candidates {
		// A candidate may carry a "\t<description>" suffix (see withDescription);
		// the prefix matches — and duplicates collapse — on the NAME part only.
		name := c
		if before, _, ok := strings.Cut(c, "\t"); ok {
			name = before
		}
		if name != "" && strings.HasPrefix(name, prefix) && !seen[name] {
			seen[name] = true
			out = append(out, c)
		}
	}
	sort.Strings(out)
	return out
}

// withDescription suffixes a completion candidate with its one-line description
// as "name\tdescription" — the wire protocol descriptions ride on. zsh/fish/
// powershell render the description beside the name; the bash script strips it.
// An empty summary leaves the candidate bare, and only the summary's first line
// rides (the protocol is line-based). Dynamic completers (FlagValueCompleter /
// ArgValueCompleter) may return the same shape; bare values stay bare. Any ANSI
// styling in the summary is stripped (E6-S2): a styled summary is legitimate on
// the help-list surface, but escape sequences would corrupt the shell's
// completion rendering — the wire is the honest plain-text projection.
func withDescription(name, summary string) string {
	if summary == "" {
		return name
	}
	if i := strings.IndexByte(summary, '\n'); i >= 0 {
		summary = summary[:i]
	}
	summary = Strip(summary)
	if summary = strings.TrimSpace(summary); summary == "" {
		return name
	}
	return name + "\t" + summary
}

// ErrServiceNotFound is the sentinel reported when a registry key is unbound — the
// [MustGet] panics a [*ServiceError] wrapping it, which the runtime
// recovers and routes to the funnel (a missing service is rotini's
// "should never happen", not the end-user's error). A funnel classifies it with errors.Is:
//
//	case errors.Is(err, rotini.ErrServiceNotFound):
var ErrServiceNotFound = errors.New("rotini: service not found")

// ServiceError reports a registry key that was requested but unbound (or bound to
// the wrong type) — the [MustGet] panics it. It unwraps to
// [ErrServiceNotFound]; recover the key with errors.As.
type ServiceError struct {
	Key string // the registry key that was requested
}

func (e *ServiceError) Error() string {
	return fmt.Sprintf("rotini: no service bound under key %q", e.Key)
}

// Unwrap exposes both the [ErrServiceNotFound] sentinel and [ErrInternal], so a missing
// service matches errors.Is for either — and [CategoryOf] classifies it as
// [CategoryInternal] (a wiring bug, not the end-user's fault).
func (e *ServiceError) Unwrap() []error { return []error{ErrServiceNotFound, ErrInternal} }

// Context is rotini's per-invocation context: the service registry plus the bits
// the runtime resolves before dispatch — the raw argument vector (read via
// [Context.Args]) and the resolved command chain (read via [Context.Chain]). One
// is built per invocation and passed (as *Context) into every handler hook, so all
// hooks share the same bindings and exit state.
//
// The registry is the dependency-injection seam: bind any service with
// [Context.Bind] (a real implementation in production, a double in tests) and
// retrieve it with [Context.Value] (or the typed [Get]/[MustGet]).
// Bindings persist for the lifetime of the Context. Opt-in input parsing (the
// [Parser]) reads [Context.Args]/[Context.Chain]; the runtime itself never
// parses flags.
//
// A Context is safe for concurrent registry access; reads and writes are guarded
// by an internal sync.RWMutex. Always pass it as a pointer — it must not be copied.
type Context struct {
	mu sync.RWMutex

	// Stdin, Stdout, and Stderr are the program's streams, mirroring those set via
	// [Program.WithStdin] / [Program.WithStdout] / [Program.WithStderr] (default os.Stdin /
	// os.Stdout / os.Stderr). A handler reads input and writes its output/diagnostics
	// through these rather than os.Std* directly, so the same handler code is exercised in
	// a test by configuring the Program's streams (the Binder reads its stdin channel from
	// [Context.Stdin] too). They are set before dispatch and not mutated thereafter; never
	// nil (a standalone [NewContextFor] defaults them to os.Std*).
	Stdin  io.Reader
	Stdout io.Writer
	Stderr io.Writer

	// Args is the raw argument vector for this invocation — os.Args[1:], or the
	// override from [Program.WithArgs] — with everything after the resolved
	// command path still present, so a handler can run its own parser instead of
	// [Parser.Parse]. It is the live slice, not a copy: set before dispatch and
	// not mutated by the runtime thereafter; a handler that mutates it changes
	// what every later read (including the opt-in Parser/Binder) sees, and owns
	// the consequences.
	Args []string

	services    map[string]any
	chain       []ResolvedCommand // resolved command path, root → leaf
	exitCode    int               // process exit code requested via [Context.SignalExit]/[Context.Exit] (first non-zero wins; the funnel overrides)
	stopped     bool              // an exit was requested; forward progress (setup/PreRun/Run) halts
	exitNow     bool              // [Context.Exit] (hard) was called: skip remaining teardown too
	funnelStage bool              // the run has settled and the funnel is executing: [Context.Exit] now OVERRIDES the exit code (the funnel is the final authority); [Context.SignalExit] is a no-op
	infos       []string          // informational messages recorded this run via [Context.RecordInfo]; handed to the funnel
	recorded    []error           // errors recorded this run via [Context.RecordError]; handed to the funnel
	warnings    []error           // warnings recorded this run via [Context.RecordWarning]; handed to the funnel
	successes   []string          // successes recorded this run via [Context.RecordSuccess]; handed to the funnel
	faults      []*PanicError     // recovered panics + rotini-detected faults; set by the lifecycle (NOT publicly recordable); handed to the funnel
}

// newContext returns an empty [Context] with an initialized registry and no
// resolved command. The runtime builds one per invocation and fills in the
// resolved chain before dispatch; [NewContextFor] is the public entry for
// tests and standalone tooling (pass an empty Definition for a bare registry).
func newContext() *Context {
	return &Context{
		services: make(map[string]any),
		Stdin:    os.Stdin,
		Stdout:   os.Stdout,
		Stderr:   os.Stderr,
	}
}

// NewContextFor builds a [Context] with argv resolved against an explicit def — the
// same context the runtime hands a handler at dispatch (raw [Context.Args] + the
// resolved [Context.Chain]). It is for exercising the [Parser]/[Usage] helpers, or a
// single hook, against a Definition you construct:
//
//	def := rotini.Definition{Name: "app", Handler: "App", Commands: []rotini.CommandDef{ … }}
//	rtx := rotini.NewContextFor(def, []string{"build", "x.yaml"}).Bind(rotini.KeyParser, rotini.NewParser())
//	var in appInputs
//	err := rotini.MustGet[*rotini.Parser](rtx, rotini.KeyParser).Parse(rtx, &in)
//
// To drive a whole *generated* program end-to-end (the usual handler test), construct it
// with the generated NewProgram and run it under a recording exit + capture streams —
// see [Program.WithExit]/[Program.WithStdout]/[Program.WithStderr] — rather than building
// a context by hand; the generated command tree is unexported.
//
// A remote/co-located token resolves to as much of the chain as precedes it; the
// runtime would exec the sibling binary, which NewContextFor does not.
func NewContextFor(def Definition, argv []string) *Context {
	rtx := newContext()
	chain, _ := resolveChain(def, argv)
	rtx.Args = argv
	rtx.chain = chain
	return rtx
}

// Bind associates value with key, overwriting any prior binding. It returns the
// receiver so calls can be chained:
//
//	cmd.Program.Bind(rotini.KeyParser, customParser).Bind(rotini.KeyBinder, customBinder).Execute()
//
// Bind is safe for concurrent use.
func (rtx *Context) Bind(key string, value any) *Context {
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	if rtx.services == nil {
		rtx.services = make(map[string]any)
	}
	rtx.services[key] = value
	return rtx
}

// BindIfAbsent binds value under key only if key is not already bound, and returns the
// receiver to chain. It is the registered-default form of [Bind]: a handler binds its work
// dependency's real implementation with BindIfAbsent so production materializes the real one
// in the registry, while a caller (e.g. a test) that bound a double under the same key
// earlier keeps it — and either way the dependency is resolvable from the registry (with the
// standard [MustGet]), not a value hidden inline. The check-and-set is atomic. Use [Bind] to
// overwrite unconditionally.
//
//	rtx.BindIfAbsent("generate", internal.Generate)
//	gen := rotini.MustGet[internal.GenerateFn](rtx, "generate")
func (rtx *Context) BindIfAbsent(key string, value any) *Context {
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	if rtx.services == nil {
		rtx.services = make(map[string]any)
	}
	if _, ok := rtx.services[key]; !ok {
		rtx.services[key] = value
	}
	return rtx
}

// Chain returns the resolved command path for this invocation, root → leaf — the
// command tree the runtime descended to choose this handler. Opt-in tooling (the
// [Parser] and [Usage]) reads it to bind inputs and render help against
// the exact command whose handler ran. The slice is the runtime's; treat it as
// read-only.
func (rtx *Context) Chain() []ResolvedCommand {
	if rtx == nil {
		return nil
	}
	return rtx.chain
}

// Value returns the service bound under key, or nil if none is bound — the raw
// accessor, mirroring [context.Context.Value]. Callers type-assert to the expected
// type, using the comma-ok form to handle an unbound (or wrong-type) service:
//
//	parser, ok := rtx.Value(rotini.KeyParser).(*rotini.Parser)
//	if !ok {
//		// not bound — fail the command, or fall back
//	}
//
// Value reports a miss as nil and never panics; prefer the typed [Get] (comma-ok)
// or [MustGet] (panics → the funnel) for type-safe retrieval.
func (rtx *Context) Value(key string) any {
	if rtx == nil {
		return nil
	}
	rtx.mu.RLock()
	defer rtx.mu.RUnlock()
	return rtx.services[key]
}

// SignalExit records the program's exit code and stops the lifecycle's forward
// progress — no further setup hook (CascadingPreRun), PreRun, or Run runs.
// Teardown is unaffected: every PostRun/CascadingPostRun whose paired setup hook
// began still runs, in reverse, so cleanup is never skipped. The first non-zero
// code wins, so a later SignalExit (e.g. from a teardown hook) cannot change the
// verdict. SignalExit records no error — it is a clean, deliberate stop,
// not an error. The process exits with the recorded code once the lifecycle,
// teardown included, completes. For an abort that skips pending teardown, use
// [Context.Exit].
//
// SignalExit is a NO-OP inside the funnel ([Program.WithFunnel]): the lifecycle and
// its teardown have already run, so there is no forward progress to stop. To set the
// exit code from the funnel, use [Context.Exit] (which the funnel is allowed to use to
// override any code the lifecycle set).
func (rtx *Context) SignalExit(code int) {
	if rtx == nil || rtx.funnelStage {
		return
	}
	rtx.stopped = true
	if rtx.exitCode == 0 {
		rtx.exitCode = code
	}
}

// Exit records the program's exit code and stops the lifecycle immediately — no
// further hook runs, teardown included: any PostRun/CascadingPostRun still
// pending is skipped. Use it for an abort-now path where remaining cleanup must
// not run; prefer [Context.SignalExit] for an orderly stop that still unwinds
// every begun teardown hook. The first non-zero code wins, and Exit does not
// itself trigger the panic funnel — it is a deliberate stop, not an error.
//
// Exit skips teardown, not fault reporting: a panic already recovered before Exit
// is still captured and handed to the funnel ([Program.WithFunnel]), so a handler's
// Exit cannot silently swallow an in-flight panic — though the FUNNEL itself, as the
// final authority, may.
//
// Inside the funnel, Exit is the way to set the final exit code and OVERRIDES any code
// the lifecycle set (the funnel is the last word — first-non-zero-wins no longer
// applies). During the lifecycle it keeps first-non-zero-wins.
func (rtx *Context) Exit(code int) {
	if rtx == nil {
		return
	}
	rtx.stopped = true
	rtx.exitNow = true
	if rtx.funnelStage {
		rtx.exitCode = code // the funnel is the final authority — override any prior code
		return
	}
	if rtx.exitCode == 0 {
		rtx.exitCode = code
	}
}

// RecordInfo records msg as an informational message of this run — neutral
// output the end-user wants surfaced (progress, context, a note), distinct from a
// success message only by intent. Like the other record calls it neither prints
// nor stops the lifecycle: it appends, and the program's funnel
// ([Program.WithFunnel]) receives the recorded infos as a slice once the run
// settles. Recording an info never sets the exit code. An empty msg is ignored.
func (rtx *Context) RecordInfo(msg string) {
	if rtx == nil || msg == "" {
		return
	}
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	rtx.infos = append(rtx.infos, msg)
}

// copyInfos snapshots the informational messages recorded this run (via
// [Context.RecordInfo]), in recording order, as a copy. Unexported: infos are
// PRIVATE and surface only as the slice handed to the funnel.
func (rtx *Context) copyInfos() []string {
	if rtx == nil {
		return nil
	}
	rtx.mu.RLock()
	defer rtx.mu.RUnlock()
	if len(rtx.infos) == 0 {
		return nil
	}
	out := make([]string, len(rtx.infos))
	copy(out, rtx.infos)
	return out
}

// RecordError records err as one of THIS run's errors — the end-user's own
// failures, to be reported once the lifecycle settles. It does NOT print and
// does NOT stop the lifecycle — a handler accumulates one or more errors with
// RecordError (it may call it any number of times, across any hook), then
// chooses HOW to stop independently: [Context.SignalExit] for a graceful stop
// that still unwinds teardown, or [Context.Exit] to skip teardown. Either way —
// and even if neither is called — the program's funnel ([Program.WithFunnel])
// receives the recorded errors as a slice once the run settles. A nil err is
// ignored.
//
// This is the error channel of five outcome channels handed to the one funnel.
// Recovered panics and rotini-detected faults (a wiring mismatch, a resolver
// fault, a [MustGet] on a missing service) are NOT recorded here — the lifecycle
// captures them as the funnel's panics slice; infos/successes/warnings have their
// own channels ([Context.RecordInfo] / [Context.RecordSuccess] /
// [Context.RecordWarning]).
//
//	inputs, err := rotini.Collect[cmdgen.MycliInputs](rtx)
//	if err != nil {
//	    rtx.RecordError(err)
//	    rtx.SignalExit(1) // graceful; or rtx.Exit(…) to skip teardown
//	    return
//	}
func (rtx *Context) RecordError(err error) {
	if rtx == nil || err == nil {
		return
	}
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	rtx.recorded = append(rtx.recorded, err)
}

// copyErrors snapshots the errors recorded this run (via [Context.RecordError]),
// in recording order, as a copy. It is unexported: the recorded errors are
// PRIVATE — they surface only as the slice the runtime hands to the funnel
// ([Program.WithFunnel]), never through a drainable accessor.
func (rtx *Context) copyErrors() []error {
	if rtx == nil {
		return nil
	}
	rtx.mu.RLock()
	defer rtx.mu.RUnlock()
	if len(rtx.recorded) == 0 {
		return nil
	}
	out := make([]error, len(rtx.recorded))
	copy(out, rtx.recorded)
	return out
}

// RecordWarning records warn as a non-fatal warning of this run — something the
// end-user should know about that did NOT fail the command (a deprecation, a
// fallback, a skipped item). Like [Context.RecordError] it neither prints nor
// stops the lifecycle: it appends, and the program's funnel ([Program.WithFunnel])
// receives the recorded warnings as a slice once the run settles. A warning is an
// error value (so it can be typed and branched with errors.As, and secrets stay
// redacted), but it never raises the exit code. A nil warn is ignored.
func (rtx *Context) RecordWarning(warn error) {
	if rtx == nil || warn == nil {
		return
	}
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	rtx.warnings = append(rtx.warnings, warn)
}

// RecordSuccess records msg as a success message of this run — what went right,
// for the program's funnel ([Program.WithFunnel]) to present. Like the other
// record calls it neither prints nor stops the lifecycle: it appends, and the
// funnel receives the recorded messages as a slice once the run settles.
// Recording a success does not by itself set the exit code (a clean run is
// already 0). An empty msg is ignored.
func (rtx *Context) RecordSuccess(msg string) {
	if rtx == nil || msg == "" {
		return
	}
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	rtx.successes = append(rtx.successes, msg)
}

// copyWarnings snapshots the warnings recorded this run (via
// [Context.RecordWarning]), in recording order, as a copy. Unexported: warnings
// are PRIVATE and surface only as the slice handed to the funnel.
func (rtx *Context) copyWarnings() []error {
	if rtx == nil {
		return nil
	}
	rtx.mu.RLock()
	defer rtx.mu.RUnlock()
	if len(rtx.warnings) == 0 {
		return nil
	}
	out := make([]error, len(rtx.warnings))
	copy(out, rtx.warnings)
	return out
}

// copySuccesses snapshots the success messages recorded this run (via
// [Context.RecordSuccess]), in recording order, as a copy. Unexported:
// successes are PRIVATE and surface only as the slice handed to the funnel.
func (rtx *Context) copySuccesses() []string {
	if rtx == nil {
		return nil
	}
	rtx.mu.RLock()
	defer rtx.mu.RUnlock()
	if len(rtx.successes) == 0 {
		return nil
	}
	out := make([]string, len(rtx.successes))
	copy(out, rtx.successes)
	return out
}

// copyFaults snapshots the recovered panics + rotini-detected faults captured
// this run, in capture order, as a copy. Unexported: faults are PRIVATE (there
// is no public record call either — the lifecycle captures them) and surface
// only as the panics slice handed to the funnel ([Program.WithFunnel]).
func (rtx *Context) copyFaults() []*PanicError {
	if rtx == nil {
		return nil
	}
	rtx.mu.RLock()
	defer rtx.mu.RUnlock()
	if len(rtx.faults) == 0 {
		return nil
	}
	out := make([]*PanicError, len(rtx.faults))
	copy(out, rtx.faults)
	return out
}

// recordFault appends a recovered panic / rotini-detected fault to the private
// fault channel (handed to the funnel as its panics slice). It is unexported on
// purpose: faults are the lifecycle's to capture, never the handler's to record.
func (rtx *Context) recordFault(pe *PanicError) {
	if rtx == nil || pe == nil {
		return
	}
	rtx.mu.Lock()
	defer rtx.mu.Unlock()
	rtx.faults = append(rtx.faults, pe)
}

// Get returns the service bound under key as T — the typed, comma-ok form of the
// raw [Context.Value] (which returns any). ok is false when no service is bound
// under key or the bound value is not a T:
//
//	parser, ok := rotini.Get[*rotini.Parser](rtx, rotini.KeyParser)
//	if !ok {
//		// not bound — fail the command, or fall back
//	}
//
// It never panics; use [MustGet] to route a missing/wrong-type service through the
// funnel (as a fault) instead of handling it inline.
func Get[T any](rtx *Context, key string) (T, bool) {
	v, ok := rtx.Value(key).(T)
	return v, ok
}

// MustGet returns the service bound under key as T, or panics with a
// [*ServiceError] (unwrapping to [ErrServiceNotFound]) when it is absent or not a
// T. The panic is intentional and recoverable: the runtime recovers it inside
// dispatch and routes it through the program's funnel — so a handler that
// cannot run without a service reaches for MustGet instead of handling a miss
// inline:
//
//	parser := rotini.MustGet[*rotini.Parser](rtx, rotini.KeyParser)
//	var in rtg.MycliInputs
//	err := parser.Parse(rtx, &in)
func MustGet[T any](rtx *Context, key string) T {
	v, ok := Get[T](rtx, key)
	if !ok {
		panic(&ServiceError{Key: key})
	}
	return v
}

func EnvNoColor() bool {
	if force := os.Getenv("CLICOLOR_FORCE"); force != "" && force != "0" {
		return false
	}
	return os.Getenv("NO_COLOR") != ""
}

func DetectProfile() Profile {
	if EnvNoColor() {
		return ProfileNoColor
	}
	switch colorterm := os.Getenv("COLORTERM"); colorterm {
	case "truecolor", "24bit":
		return ProfileTrueColor
	}
	term := os.Getenv("TERM")
	switch {
	case strings.Contains(term, "truecolor"):
		return ProfileTrueColor
	case strings.Contains(term, "256color"):
		return ProfileANSI256
	case term == "" || term == "dumb":
		return ProfileNoColor
	default:
		return ProfileANSI16
	}
}

func IsTerminal(file *os.File) bool {
	if file == nil {
		return false
	}
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

// DefaultCascadingPreRun is an embeddable no-op [Handlers.CascadingPreRun].
type DefaultCascadingPreRun struct{}

// CascadingPreRun does nothing.
func (DefaultCascadingPreRun) CascadingPreRun(ctx context.Context, rtx *Context) {}

// DefaultPreRun is an embeddable no-op [Handlers.PreRun].
type DefaultPreRun struct{}

// PreRun does nothing.
func (DefaultPreRun) PreRun(ctx context.Context, rtx *Context) {}

// DefaultPostRun is an embeddable no-op [Handlers.PostRun].
type DefaultPostRun struct{}

// PostRun does nothing.
func (DefaultPostRun) PostRun(ctx context.Context, rtx *Context) {}

// DefaultCascadingPostRun is an embeddable no-op [Handlers.CascadingPostRun].
type DefaultCascadingPostRun struct{}

// CascadingPostRun does nothing.
func (DefaultCascadingPostRun) CascadingPostRun(ctx context.Context, rtx *Context) {}

// This file is the lifecycle seam: the two phases of Execute — *resolve*
// (argv → invocation target) and *run* (target → ordered hook invocations) —
// each with an exported default a program may wrap or replace
// ([Program.WithResolver], [Program.WithLifecycle]).
//
// The run contract, pinned (this table IS the product; the engine below
// enforces it for every plan, default or custom):
//
//	Phase     Order                    Hook                Halts forward on        Runs during unwind when
//	─────     ─────                    ────                ────────────────        ───────────────────────
//	setup     root → leaf              CascadingPreRun     SignalExit/Exit,        —
//	setup     leaf                     PreRun              a panic, or a           —
//	work      leaf                     Run                 trapped signal          —
//	teardown  leaf                     PostRun             —                       its PreRun began
//	teardown  leaf → root              CascadingPostRun    —                       its CascadingPreRun began
//
// Teardown unwinds in reverse for exactly the steps whose forward hook BEGAN,
// and runs to completion — a panic or SignalExit inside teardown neither
// aborts the rest nor displaces the first failure/exit code; only a hard
// [Context.Exit] skips what remains. A panic anywhere is recovered and routed
// once, after all teardown, to the funnel (exit floored
// to 1). A custom lifecycle changes only the *plan* — which hooks, in what
// pairing and order; the halting, balanced-unwind, panic-funnel, and
// exit-code semantics above are rotini's and not overridable.

// Resolution is the outcome of the resolve phase: the invoked command path
// (root → leaf), or a remote dispatch that replaces local execution.
type Resolution struct {
	// Chain is the resolved command path the run phase dispatches (when
	// Remote is nil). It must be non-empty — the root frame is always there.
	Chain []ResolvedCommand
	// Remote, when non-nil, short-circuits local dispatch: the runtime execs
	// this remote/plugin binary instead (stdio passed through, context
	// honored), exactly as for declared remote_commands.
	Remote *RemoteDispatch
	// Args is the argument vector the run phase exposes as [Context.Args] —
	// what the opt-in Parser/Binder later read. A resolver that rewrites
	// tokens (say, an alias) returns the rewritten vector here so parsing
	// agrees with its routing; nil keeps the original argv.
	Args []string
}

// Resolver is the resolve phase: argv against the Definition, deciding what
// this invocation targets. An error is routed through the funnel
// (as an error) and fails the run (exit floored to 1). See [DefaultResolver].
type Resolver func(def Definition, argv []string) (Resolution, error)

// DefaultResolver is rotini's resolve phase, exported so a custom [Resolver]
// can wrap it rather than re-derive it: descend sub-commands by name/alias,
// skip flags and their values, stop at the first positional (or "--", or a
// dash-prefixed value), and divert to a remote dispatch for declared
// remote_commands / discovered plugins. It is intentionally lenient — unknown
// flags and bad input are the opt-in Parser's concern, not routing's — and it
// never errors.
func DefaultResolver(def Definition, argv []string) (Resolution, error) {
	chain, remote := resolveChain(def, argv)
	return Resolution{Chain: chain, Remote: remote, Args: argv}, nil
}

// LifecycleStep pairs one forward hook with its teardown — the unit of the run
// phase's execution plan. The engine runs Do hooks forward, halting per the
// contract above, then runs the Undo of every step whose Do began, in reverse.
// A nil Undo is a step with no teardown (the default plan's Run step).
type LifecycleStep struct {
	Name string                                  // diagnostic label, e.g. "cascading:app", "prerun:build", "run:build"
	Do   func(ctx context.Context, rtx *Context) // the forward hook
	Undo func(ctx context.Context, rtx *Context) // the paired teardown; nil for none
}

// Lifecycle is the run phase's planner: given the resolved chain and each
// frame's [Handlers] (index-aligned with chain), it returns the ordered
// step plan the engine executes. It orders and pairs the declared hooks — it
// cannot change the engine's halting/unwind/funnel semantics, and the handler
// wiring rules (every frame's handler resolved from the generated set) hold
// before it is consulted. See [DefaultLifecycle].
type Lifecycle func(chain []ResolvedCommand, handlers []Handlers) []LifecycleStep

// DefaultLifecycle is rotini's run-phase plan, exported so a custom
// [Lifecycle] can wrap or reshape it: one CascadingPreRun/CascadingPostRun
// pair per frame (root → leaf), then the leaf's PreRun/PostRun pair, then the
// leaf's Run with no teardown. With the engine's reverse unwind this yields
// exactly the contract table above.
func DefaultLifecycle(chain []ResolvedCommand, handlers []Handlers) []LifecycleStep {
	steps := make([]LifecycleStep, 0, len(handlers)+2)
	for i, h := range handlers {
		steps = append(steps, LifecycleStep{Name: "cascading:" + chain[i].Name, Do: h.CascadingPreRun, Undo: h.CascadingPostRun})
	}
	leaf := handlers[len(handlers)-1]
	leafName := chain[len(chain)-1].Name
	steps = append(steps,
		LifecycleStep{Name: "prerun:" + leafName, Do: leaf.PreRun, Undo: leaf.PostRun},
		LifecycleStep{Name: "run:" + leafName, Do: leaf.Run},
	)
	return steps
}

// FieldPath identifies one leaf field of a generated inputs struct by its
// dot-joined Go field path, e.g. "RotiniGenerate.Flags.ConfFilePath" — the
// names the user reads in their own generated code. Both the channel parsers
// (which record presence) and the overlay (which copies set fields) derive it
// from the same type, so the two sides can never disagree.
type FieldPath string

// Provenance records which layer supplied a field's value and the raw text it
// supplied. Raw is pre-redacted for inputs the spec marks secret — a Report can
// never leak what an error message must not.
type Provenance struct {
	Layer string // the supplying layer's name: "defaults", "files", "env", "argv", "stdin", or custom
	Raw   string // the supplied text ("" when non-textual, e.g. a decoded stdin document); "[redacted]" for secrets
}

// Presence maps each field a layer actually supplied to its provenance —
// the set-detection that makes overlay precedence real: a layer's zero-valued,
// absent fields are skipped, never copied.
type Presence map[FieldPath]Provenance

// Layer is one input channel's view of the inputs type T: the values it
// supplied (sparsely populated — everything else is T's zero value) and exactly
// which fields those are. Layers produced by rotini's channel parsers also
// carry unexported validation data ([Report.Validate] uses it); a hand-built
// Layer{Name, Values, Set} participates in overlay and provenance but
// contributes nothing to validation.
type Layer[T any] struct {
	Name   string
	Values T
	Set    Presence

	core *layerCore // validation data: nil for hand-built layers
}

// layerCore is the channel parsers' validation payload: the resolved chain and
// the raw string values per chain scope, in the same store shape the Parser
// validates, so a merged Report re-uses the exact validation (and error text)
// of Parser.Parse / Binder.Bind.
type layerCore struct {
	chain       []ResolvedCommand
	store       *parsedInputs
	argDefaults map[int]string // the defaults layer's per-index argument defaults (sparse)
}

// ── the one-liner ────────────────────────────────────────────────────────────.

// Collect is the 95% handler's entire input story: every declared channel —
// argv, environment, configuration files (declared AND custom BindMeta
// sources), the stdin payload, defaults — acquired, reconciled in the standard
// precedence (defaults < files < env < argv), and validated, in one call:
//
//	inputs, err := rotini.Collect[cmdgen.MycliDeployInputs](rtx)
//
// Configuration comes from the Context's bound [BindMeta] ([KeyBindMeta] —
// the generated NewProgram binds it; a CLI with nothing to declare needs
// nothing). It is [Binder.Bind] under the hood; errors are the same
// data-shaped [*ParseError]s. When the answer to "where did this value come
// from" matters, use [CollectP].
func Collect[T any](rtx *Context) (T, error) {
	var t T
	err := binderFor(rtx).Bind(rtx, &t)
	return t, err
}

// CollectP is [Collect] with provenance: the same reconciled, validated
// inputs plus the [Report] that answers Winner/History per field. It rides
// the per-channel layer machinery ([Defaults], [ParseFiles], [ParseEnv],
// [ParseArgv], [ParseStdin]) overlaid in the standard precedence — the same
// values Collect produces (pinned by test), at the cost of acquiring each
// channel separately. Validation failures return the merged inputs AND the
// report alongside the error, so a funnel can still say which layer supplied
// the offending value.
func CollectP[T any](rtx *Context) (T, Report, error) {
	var zero T
	defaults, err := Defaults[T](rtx)
	if err != nil {
		return zero, Report{}, err
	}
	files, err := ParseFiles[T](rtx)
	if err != nil {
		return zero, Report{}, err
	}
	env, err := ParseEnv[T](rtx)
	if err != nil {
		return zero, Report{}, err
	}
	argv, err := ParseArgv[T](rtx)
	if err != nil {
		return zero, Report{}, err
	}
	stdin, err := ParseStdin[T](rtx)
	if err != nil {
		return zero, Report{}, err
	}
	merged, report := OverlayInputsP(defaults, files, env, argv, stdin)
	return merged, report, report.Validate()
}

// ── channel acquisition ──────────────────────────────────────────────────────.

// ParseArgv parses the command line only — flags and positionals across the
// resolved chain, exactly as supplied: no defaults, no env/config fallback, and
// no required/enum validation (validate the overlaid result via
// [Report.Validate], so a required flag satisfied by another layer passes).
// Parse failures (unknown flag, missing value) are [ParseError]s.
func ParseArgv[T any](rtx *Context) (Layer[T], error) {
	var t T
	set, core, err := argvLayer(rtx, reflect.ValueOf(&t).Elem())
	return Layer[T]{Name: "argv", Values: t, Set: set, core: core}, err
}

// ParseEnv acquires the environment channel: every Env input (explicit
// `variable:` or recon's SNAKE_UPPER projection of its key), plus the env
// fallback of any flag that declares a recon key. Channel-owned semantics stay
// in-channel, exactly as in [Binder.Bind]: a required env input missing or a
// constraint violation is this call's error.
func ParseEnv[T any](rtx *Context) (Layer[T], error) {
	var t T
	set, core, err := envLayer(binderFor(rtx), rtx, reflect.ValueOf(&t).Elem())
	return Layer[T]{Name: "env", Values: t, Set: set, core: core}, err
}

// ParseFiles acquires the configuration-files channel: every Config input from
// the BindMeta sources (declared order = precedence), plus the config fallback
// of any flag that declares a recon key. Channel-owned semantics (required,
// constraints) are this call's errors, exactly as in [Binder.Bind].
func ParseFiles[T any](rtx *Context) (Layer[T], error) {
	var t T
	set, core, err := filesLayer(binderFor(rtx), rtx, reflect.ValueOf(&t).Elem())
	return Layer[T]{Name: "files", Values: t, Set: set, core: core}, err
}

// ParseStdin acquires the stdin channel: the leaf command's typed payload,
// decoded per its declared format, schema-validated, and honoring required —
// exactly the [Binder.Bind] stdin step.
func ParseStdin[T any](rtx *Context) (Layer[T], error) {
	var t T
	set, core, err := stdinLayer(binderFor(rtx), rtx, reflect.ValueOf(&t).Elem())
	return Layer[T]{Name: "stdin", Values: t, Set: set, core: core}, err
}

// Defaults synthesizes the spec's declared defaults as an explicit layer —
// conventionally layer 0 of the overlay, making "no input at all" visible and
// testable. Flag and argument defaults come from the resolved chain's
// Definition; env/config input defaults from their recon `default=` tags.
func Defaults[T any](rtx *Context) (Layer[T], error) {
	var t T
	set, core, err := defaultsLayer(rtx, reflect.ValueOf(&t).Elem())
	return Layer[T]{Name: "defaults", Values: t, Set: set, core: core}, err
}

// ── overlay ──────────────────────────────────────────────────────────────────.

// OverlayInputs merges layers into one inputs value. Slice order is precedence,
// low → high: a field set by a later layer wins; a field no layer set stays the
// zero value; an unset layer field never clobbers a lower layer's value
// (skip-not-zero). Overlaying an empty layer is the identity.
func OverlayInputs[T any](layers ...Layer[T]) T {
	out, _ := OverlayInputsP(layers...)
	return out
}

// OverlayInputsP is [OverlayInputs] plus the merged [Report]: which layer won
// each field, the full per-field history, and Validate over the merged result.
func OverlayInputsP[T any](layers ...Layer[T]) (T, Report) {
	var out T
	dst := reflect.ValueOf(&out).Elem()
	rep := Report{set: Presence{}, history: map[FieldPath][]Provenance{}}

	for _, l := range layers {
		src := reflect.ValueOf(l.Values)
		for _, path := range sortedPaths(l.Set) {
			copyFieldByPath(dst, src, path)
			prov := l.Set[path]
			rep.set[path] = prov
			rep.history[path] = append(rep.history[path], prov)
		}
		rep.absorb(l.core)
	}
	rep.finalize()
	return out, rep
}

// sortedPaths returns a Presence's keys in deterministic order.
func sortedPaths(p Presence) []FieldPath {
	out := make([]FieldPath, 0, len(p))
	for k := range p {
		out = append(out, k)
	}
	slices.Sort(out)
	return out
}

// copyFieldByPath copies the field at a dot-joined Go field path from src to
// dst (same type). Unknown segments are skipped — a stale path in a hand-built
// layer copies nothing rather than panicking.
func copyFieldByPath(dst, src reflect.Value, path FieldPath) {
	for seg := range strings.SplitSeq(string(path), ".") {
		if dst.Kind() != reflect.Struct || src.Kind() != reflect.Struct {
			return
		}
		dst, src = dst.FieldByName(seg), src.FieldByName(seg)
		if !dst.IsValid() || !src.IsValid() {
			return
		}
	}
	if dst.CanSet() {
		dst.Set(src)
	}
}

// ── the report ───────────────────────────────────────────────────────────────.

// Report is the merged provenance of one overlay: which layer won each field,
// every layer that set it (low → high), and validation over the merged values.
type Report struct {
	set     Presence
	history map[FieldPath][]Provenance
	chain   []ResolvedCommand
	store   *parsedInputs
	argDefs map[int]string
}

// Winner returns the provenance of the layer that supplied path's final value.
func (r Report) Winner(path FieldPath) (Provenance, bool) {
	p, ok := r.set[path]
	return p, ok
}

// History returns every layer that set path, low → high precedence — the last
// element is the winner.
func (r Report) History(path FieldPath) []Provenance {
	return r.history[path]
}

// Fields returns every field any layer set, sorted, for stable doctor-style
// output.
func (r Report) Fields() []FieldPath {
	return sortedPaths(r.set)
}

// Validate runs the same declarative checks [Parser.Parse] applies — required,
// enum, constraints, flag groups, and flag dependencies — over the merged
// values, with group/dependency "explicitly set" meaning set by the argv layer.
// Run it after the overlay so a required flag satisfied by any layer passes.
// It validates the layers' channel data; hand-built layers contribute values
// but nothing to validate. A Report from no channel layers validates clean.
func (r Report) Validate() error {
	if r.chain == nil || r.store == nil {
		return nil
	}
	if err := validate(r.chain, r.store); err != nil {
		return err
	}
	if err := validateFlagGroups(r.chain, r.store); err != nil {
		return err
	}
	return validateFlagDependencies(r.chain, r.store)
}

// absorb folds one layer's validation core into the report: later layers'
// flag values replace earlier ones scope-by-scope (matching the overlay), the
// argv layer contributes positionals and the argv-set record, and the defaults
// layer contributes its sparse argument defaults.
func (r *Report) absorb(core *layerCore) {
	if core == nil {
		return
	}
	if r.chain == nil {
		r.chain = core.chain
		r.store = &parsedInputs{
			scopes:  make([]scopeInputs, len(core.chain)),
			argvSet: make([]map[string]bool, len(core.chain)),
		}
	}
	if core.argDefaults != nil {
		r.argDefs = core.argDefaults
	}
	if core.store == nil || len(core.store.scopes) != len(r.store.scopes) {
		return
	}
	for i := range core.store.scopes {
		for name, vals := range core.store.scopes[i].flags {
			if r.store.scopes[i].flags == nil {
				r.store.scopes[i].flags = map[string][]string{}
			}
			r.store.scopes[i].flags[name] = vals
		}
		if len(core.store.scopes[i].args) > 0 {
			r.store.scopes[i].args = core.store.scopes[i].args
		}
		for name := range core.store.argvSetAt(i) {
			if r.store.argvSet[i] == nil {
				r.store.argvSet[i] = map[string]bool{}
			}
			r.store.argvSet[i][name] = true
		}
	}
}

// finalize pads the merged positionals from the defaults layer's sparse
// argument defaults — exactly the gap rule the Parser applies: fill from the
// first unsupplied index, stopping at the first index without a default.
func (r *Report) finalize() {
	if r.store == nil || r.argDefs == nil || len(r.chain) == 0 {
		return
	}
	leaf := len(r.chain) - 1
	for i := len(r.store.scopes[leaf].args); ; i++ {
		d, ok := r.argDefs[i]
		if !ok {
			break
		}
		r.store.scopes[leaf].args = append(r.store.scopes[leaf].args, d)
	}
}

// argvSetAt returns frame idx's argv-set record, nil-safe.
func (p *parsedInputs) argvSetAt(idx int) map[string]bool {
	if p == nil || idx < 0 || idx >= len(p.argvSet) {
		return nil
	}
	return p.argvSet[idx]
}

// ── channel cores (shared, non-generic) ──────────────────────────────────────.

// argvLayer parses argv only (no defaults) into v and records presence.
func argvLayer(rtx *Context, v reflect.Value) (Presence, *layerCore, error) {
	chain, err := layerChain(rtx)
	if err != nil {
		return nil, nil, err
	}
	store, err := parseArgvTokens(chain, rtx.Args, rtx.Stdin)
	if err != nil {
		return nil, nil, err
	}
	if err := bindInputs(v, store, chain); err != nil {
		return nil, nil, err
	}

	set := Presence{}
	walkCommandStructs(v, chain, func(topName string, scope int, ci reflect.Value) {
		frame := chain[scope]
		si := store.scopes[scope]
		eachTaggedField(ci, "Flags", func(fieldName, logical string, _ reflect.Value) {
			vals, ok := si.flags[logical]
			if !ok {
				return
			}
			fd, _ := findFlagDef(frame.Flags, logical)
			set[fieldPath(topName, "Flags", fieldName)] = Provenance{
				Layer: "argv",
				Raw:   redactValue(strings.Join(vals, ", "), fd.Secret),
			}
		})
		argPresence(set, "argv", topName, ci, frame, si.args)
	})
	return set, &layerCore{chain: chain, store: store}, nil
}

// defaultsLayer synthesizes declared defaults into v and records presence.
func defaultsLayer(rtx *Context, v reflect.Value) (Presence, *layerCore, error) {
	chain, err := layerChain(rtx)
	if err != nil {
		return nil, nil, err
	}

	// Flag defaults bind through the same store machinery as parsed values.
	store := &parsedInputs{scopes: make([]scopeInputs, len(chain))}
	applyDefaults(chain, store)
	if err := bindInputs(v, store, chain); err != nil {
		return nil, nil, err
	}

	// Argument defaults are sparse (per index); record them for the overlay's
	// gap rule and set the corresponding fields directly.
	leaf := chain[len(chain)-1]
	argDefaults := map[int]string{}
	for i, ad := range leaf.Arguments {
		if ad.Default != "" {
			argDefaults[i] = ad.Default
		}
	}

	set := Presence{}
	walkCommandStructs(v, chain, func(topName string, scope int, ci reflect.Value) {
		frame := chain[scope]
		eachTaggedField(ci, "Flags", func(fieldName, logical string, _ reflect.Value) {
			if _, ok := store.scopes[scope].flags[logical]; !ok {
				return
			}
			fd, _ := findFlagDef(frame.Flags, logical)
			set[fieldPath(topName, "Flags", fieldName)] = Provenance{
				Layer: "defaults",
				Raw:   redactValue(fd.Default, fd.Secret),
			}
		})
		// Positional defaults: bind per-index into the Arguments struct.
		if scope == len(chain)-1 {
			idx := 0
			eachTaggedField(ci, "Arguments", func(fieldName, logical string, f reflect.Value) {
				i := idx
				idx++
				d, ok := argDefaults[i]
				if !ok {
					return
				}
				_ = coerce(f, []string{d})
				var secret bool
				if i < len(frame.Arguments) {
					secret = frame.Arguments[i].Secret
				}
				set[fieldPath(topName, "Arguments", fieldName)] = Provenance{
					Layer: "defaults",
					Raw:   redactValue(d, secret),
				}
			})
		}
		// Env/Config defaults come from their recon `default=` tags.
		for _, channel := range []string{"Env", "Config"} {
			eachTaggedField(ci, channel, func(fieldName, logical string, f reflect.Value) {
				body := taggedFieldTag(ci, channel, fieldName).Get("recon")
				d := reconDefault(body)
				if d == "" {
					return
				}
				_ = coerce(f, []string{d})
				set[fieldPath(topName, channel, fieldName)] = Provenance{
					Layer: "defaults",
					Raw:   redactValue(d, reconHasSecret(body)),
				}
			})
		}
	})
	return set, &layerCore{chain: chain, store: store, argDefaults: argDefaults}, nil
}

// envLayer acquires the env channel (Env structs + flag env-fallbacks) into v.
func envLayer(b *Binder, rtx *Context, v reflect.Value) (Presence, *layerCore, error) {
	chain, err := layerChain(rtx)
	if err != nil {
		return nil, nil, err
	}
	envReg, err := recon.New(recon.WithSources(envSources(v, b.envPrefix)...))
	if err != nil {
		return nil, nil, internalBind(channelEnv, "", "could not build the environment registry", err)
	}
	defer envReg.Close()

	// Flag env-fallbacks read the plain env projection of the recon key, the
	// same source order reconcileFlags gives them.
	flagReg, err := recon.New(recon.WithSource(flagEnvSource(b.envPrefix)))
	if err != nil {
		return nil, nil, internalBind(channelEnv, "", "could not build the environment registry", err)
	}
	defer flagReg.Close()

	return channelLayer(v, chain, "env", "Env", envReg, flagReg, nil)
}

// filesLayer acquires the config-files channel (Config structs + flag
// config-fallbacks) into v. config_source paths are honored here too: the
// argv+env phase is re-read best-effort to learn where the files channel
// should look (a malformed argv contributes nothing — ParseArgv owns
// reporting it).
func filesLayer(b *Binder, rtx *Context, v reflect.Value) (Presence, *layerCore, error) {
	chain, err := layerChain(rtx)
	if err != nil {
		return nil, nil, err
	}
	overrides := map[string]string{}
	if store, err := parseInto(chain, rtx.Args, rtx.Stdin); err == nil {
		overrides = b.pathOverrides(chain, store)
	}
	cfg, err := b.configRegs(chain, overrides)
	if err != nil {
		return nil, nil, err
	}
	defer cfg.Close()
	return channelLayer(v, chain, "files", "Config", cfg.merged, cfg.merged, cfg)
}

// channelLayer is the shared env/files core: recon-bind each command's channel
// struct (required + defaults are recon's contract), constraint-check provided
// values, fill flag fallbacks for recon-keyed flags, and record presence for
// everything the channel actually supplied.
func channelLayer(v reflect.Value, chain []ResolvedCommand, layerName, structName string, reg, flagReg *recon.Registry, cfg *cfgRegs) (Presence, *layerCore, error) {
	set := Presence{}
	store := &parsedInputs{scopes: make([]scopeInputs, len(chain))}
	var bindErr error

	walkCommandStructs(v, chain, func(topName string, scope int, ci reflect.Value) {
		if bindErr != nil {
			return
		}
		// The channel struct itself.
		cs := ci.FieldByName(structName)
		if cs.IsValid() && cs.Kind() == reflect.Struct {
			if err := reg.Bind(cs.Addr().Interface()); err != nil {
				bindErr = reconBind(channelForStruct(structName), err)
				return
			}
			if err := validateChannelStruct(cs, reg, cfg); err != nil {
				bindErr = err
				return
			}
			if cfg != nil {
				if err := bindPinnedConfig(cs, cfg); err != nil {
					bindErr = err
					return
				}
			}
			// Nested env families (envnest) are filled directly — recon
			// resolves leaf keys only — and recorded as non-textual presence.
			nested := map[string]bool{}
			if structName == "Env" {
				var err error
				if nested, err = fillEnvNested(cs); err != nil {
					bindErr = err
					return
				}
			}
			eachTaggedField(ci, structName, func(fieldName, logical string, _ reflect.Value) {
				tag := taggedFieldTag(ci, structName, fieldName)
				body := tag.Get("recon")
				key := reconKey(body)
				if key == "" {
					return
				}
				fieldReg := reg
				if pin := tag.Get("cfgfile"); pin != "" && cfg != nil {
					if pinned, err := cfg.For(pin); err == nil {
						fieldReg = pinned
					}
				}
				if nested[key] {
					set[fieldPath(topName, structName, fieldName)] = Provenance{
						Layer: layerName,
						Raw:   redactValue("", reconHasSecret(body)),
					}
					return
				}
				if val, found, err := fieldReg.Get(key); err == nil && found {
					set[fieldPath(topName, structName, fieldName)] = Provenance{
						Layer: layerName,
						Raw:   redactValue(val.String(), reconHasSecret(body)),
					}
				}
			})
		}
		// Flag fallbacks: recon-keyed flags read this channel too.
		eachTaggedField(ci, "Flags", func(fieldName, logical string, f reflect.Value) {
			key := reconKey(taggedFieldTag(ci, "Flags", fieldName).Get("recon"))
			if key == "" {
				return
			}
			val, found, err := flagReg.Get(key)
			if err != nil || !found {
				return
			}
			s := val.String()
			_ = coerce(f, []string{s})
			fd, _ := findFlagDef(chain[scope].Flags, logical)
			set[fieldPath(topName, "Flags", fieldName)] = Provenance{
				Layer: layerName,
				Raw:   redactValue(s, fd.Secret),
			}
			if store.scopes[scope].flags == nil {
				store.scopes[scope].flags = map[string][]string{}
			}
			store.scopes[scope].flags[logical] = []string{s}
		})
	})
	if bindErr != nil {
		return nil, nil, bindErr
	}
	return set, &layerCore{chain: chain, store: store}, nil
}

// stdinLayer acquires the stdin channel into v.
func stdinLayer(b *Binder, rtx *Context, v reflect.Value) (Presence, *layerCore, error) {
	chain, err := layerChain(rtx)
	if err != nil {
		return nil, nil, err
	}
	if err := b.fillStdin(rtx, v); err != nil {
		return nil, nil, err
	}
	set := Presence{}
	if v.Kind() == reflect.Struct && v.NumField() > 0 {
		leaf := v.Field(v.NumField() - 1)
		if leaf.Kind() == reflect.Struct {
			if sf := leaf.FieldByName("Stdin"); sf.IsValid() && sf.Kind() == reflect.Pointer && !sf.IsNil() {
				set[fieldPath(v.Type().Field(v.NumField()-1).Name, "Stdin")] = Provenance{Layer: "stdin"}
			}
		}
	}
	return set, &layerCore{chain: chain}, nil
}

// ── shared walking helpers ───────────────────────────────────────────────────.

// layerChain validates the context and returns its resolved chain — the same
// preconditions Parser.parseBind enforces.
func layerChain(rtx *Context) ([]ResolvedCommand, error) {
	if rtx == nil {
		return nil, &ParseError{Kind: ParseKindInternal, Msg: "rotini: parse on nil context"}
	}
	chain := rtx.Chain()
	if len(chain) == 0 {
		return nil, &ParseError{Kind: ParseKindInternal, Msg: "rotini: no command resolved for this context"}
	}
	return chain, nil
}

// walkCommandStructs visits each per-command CommandInputs field of a generated
// inputs struct with its Go field name and chain scope index, aligned at the
// leaf exactly like bindInputs.
func walkCommandStructs(v reflect.Value, chain []ResolvedCommand, visit func(topName string, scope int, ci reflect.Value)) {
	if v.Kind() != reflect.Struct {
		return
	}
	offset := len(chain) - v.NumField()
	if offset < 0 {
		return
	}
	for i := range v.NumField() {
		ci := v.Field(i)
		if ci.Kind() != reflect.Struct {
			continue
		}
		visit(v.Type().Field(i).Name, offset+i, ci)
	}
}

// eachTaggedField visits each rotini-tagged field of one channel sub-struct
// (Flags/Arguments/Env/Config) of a CommandInputs value.
func eachTaggedField(ci reflect.Value, structName string, visit func(fieldName, logical string, f reflect.Value)) {
	s := ci.FieldByName(structName)
	if !s.IsValid() || s.Kind() != reflect.Struct {
		return
	}
	st := s.Type()
	for j := range s.NumField() {
		logical := st.Field(j).Tag.Get("rotini")
		if logical == "" {
			continue
		}
		visit(st.Field(j).Name, logical, s.Field(j))
	}
}

// taggedFieldTag returns the full struct tag of one channel sub-struct field.
func taggedFieldTag(ci reflect.Value, structName, fieldName string) reflect.StructTag {
	s := ci.FieldByName(structName)
	if !s.IsValid() || s.Kind() != reflect.Struct {
		return ""
	}
	f, ok := s.Type().FieldByName(fieldName)
	if !ok {
		return ""
	}
	return f.Tag
}

// argPresence records presence for the positional-argument fields that
// received values, mirroring bindArgs' index mapping (a trailing []string
// absorbs the rest).
func argPresence(set Presence, layerName, topName string, ci reflect.Value, frame ResolvedCommand, args []string) {
	if len(args) == 0 {
		return
	}
	s := ci.FieldByName("Arguments")
	if !s.IsValid() || s.Kind() != reflect.Struct {
		return
	}
	st := s.Type()
	idx := 0
	for j := range s.NumField() {
		fieldName := st.Field(j).Name
		f := s.Field(j)
		variadic := f.Kind() == reflect.Slice // a slice argument is variadic, whatever its element type
		var vals []string
		switch {
		case variadic:
			vals = args[min(idx, len(args)):]
			idx = len(args)
		case idx < len(args):
			vals = args[idx : idx+1]
			idx++
		default:
			continue
		}
		if len(vals) == 0 {
			continue
		}
		var secret bool
		if j < len(frame.Arguments) {
			secret = frame.Arguments[j].Secret
		}
		set[fieldPath(topName, "Arguments", fieldName)] = Provenance{
			Layer: layerName,
			Raw:   redactValue(strings.Join(vals, ", "), secret),
		}
	}
}

// fieldPath joins Go field names into a FieldPath.
func fieldPath(parts ...string) FieldPath {
	return FieldPath(strings.Join(parts, "."))
}

// reconDefault extracts the `default=` option from a recon struct-tag body.
func reconDefault(body string) string {
	if body == "" {
		return ""
	}
	for _, opt := range strings.Split(body, ",")[1:] {
		if v, ok := strings.CutPrefix(strings.TrimSpace(opt), "default="); ok {
			return v
		}
	}
	return ""
}

// ResolvedCommand is one node on the invoked command path (root → leaf): the
// flattened command-tree data the runtime resolved for this invocation. The
// runtime computes the chain in order to dispatch the correct handler, and
// exposes it via [Rtx.Chain] so opt-in tooling (the [Parser]) binds inputs
// against the exact command whose handler ran — including for a statically
// composed child, whose chain is relative to its own root.
type ResolvedCommand struct {
	Name                  string
	Handler               string
	Matched               string   // the argv token that resolved this command (name or an alias); "" for the root
	DeprecatedIdentifiers []string // aliases of this command that are deprecated
	Flags                 []FlagDef
	Arguments             []ArgDef
	FlagGroups            []FlagGroup
	FlagDependencies      []FlagDependency
	Commands              []CommandDef
	Remotes               []RemoteDef
	Discovery             *RemoteDiscoveryDef
	Passthrough           bool
}

func rootFrame(def Definition) ResolvedCommand {
	return ResolvedCommand{
		Name: def.Name, Handler: def.Handler,
		Flags: def.Flags, Arguments: def.Arguments,
		FlagGroups: def.FlagGroups, FlagDependencies: def.FlagDependencies,
		Commands: def.Commands, Remotes: def.RemoteCommands, Discovery: def.Discovery,
		Passthrough: def.Passthrough,
	}
}

func cmdFrame(c CommandDef) ResolvedCommand {
	return ResolvedCommand{
		Name: c.Name, Handler: c.Handler, DeprecatedIdentifiers: c.DeprecatedIdentifiers,
		Flags: c.Flags, Arguments: c.Arguments,
		FlagGroups: c.FlagGroups, FlagDependencies: c.FlagDependencies,
		Commands: c.Commands, Remotes: c.Remotes, Discovery: c.Discovery,
		Passthrough: c.Passthrough,
	}
}

// resolveChain walks argv against def to find the invoked command path without
// validating inputs. It descends sub-commands by name/alias, skips flags (and a
// flag's separate value, so it is never mistaken for a command), and stops at the
// first positional argument. If a token names a remote/co-located command it
// returns the chain so far plus a non-nil [RemoteDispatch] the runtime should
// exec instead of dispatching the chain.
//
// Resolution is intentionally lenient — unknown flags, missing values, and bad
// input are not errors here. Parsing and validation are opt-in, performed by the
// handler via [Parser.Parse].
func resolveChain(def Definition, argv []string) ([]ResolvedCommand, *RemoteDispatch) {
	chain := []ResolvedCommand{rootFrame(def)}
	if def.Passthrough {
		return chain, nil // a passthrough root: every token is a positional
	}
	for i := 0; i < len(argv); i++ {
		tok := argv[i]
		if tok == "--" {
			break // the rest are positional; no further command descent
		}
		if isFlag(tok) {
			name, _, hasInline := splitFlag(tok)
			// Skip a separate value token so it is not mistaken for a command.
			if fd, _, ok := findFlag(chain, name); ok && takesValue(fd) && !hasInline {
				i++
			}
			continue
		}
		// A non-flag token that still begins with "-" (a negative-number argument like
		// "-5", or bare "-") is a positional, never a command/remote/plugin name — those
		// begin with a letter. Stop descending so it is not mis-dispatched.
		if strings.HasPrefix(tok, "-") {
			break
		}
		cur := chain[len(chain)-1]
		if child, ok := findChild(cur, tok); ok {
			frame := cmdFrame(child)
			frame.Matched = tok // record the token used (name or alias) for deprecation detection
			chain = append(chain, frame)
			if frame.Passthrough {
				break // raw tokens from here on — no further descent, no flag skipping
			}
			continue
		}
		if rd, ok := findRemote(cur, tok); ok {
			return chain, &RemoteDispatch{Def: rd, Args: append([]string{}, argv[i+1:]...)}
		}
		// Plugin discovery: at a discovery-enabled command, an unmatched token is
		// dispatched to the sibling executable <prefix><token> (kubectl-plugin style).
		// The binary is resolved (and any error reported) at exec time.
		if d := cur.Discovery; d != nil {
			rd := RemoteDef{Name: tok, Binary: d.Prefix + tok}
			return chain, &RemoteDispatch{Def: rd, Args: append([]string{}, argv[i+1:]...), Dir: d.Path, Discovered: true}
		}
		break // first positional argument; stop descending
	}
	return chain, nil
}

// findRemote returns the remote sub-command of f matching tok by name or alias.
func findRemote(f ResolvedCommand, tok string) (RemoteDef, bool) {
	for _, r := range f.Remotes {
		if r.Name == tok {
			return r, true
		}
		if slices.Contains(r.Aliases, tok) {
			return r, true
		}
	}
	return RemoteDef{}, false
}

// isFlag reports whether tok is a flag token (e.g. "-h", "--watch", "--config=x").
// Bare "-" and "--" are not flags. A token that parses as a number (e.g. "-5",
// "-0.5", "-1e3") is a negative-number argument, not a flag — flag identifiers always
// have a letter after the dash(es) — so it is excluded here and handled as a positional.
func isFlag(tok string) bool {
	if len(tok) <= 1 || tok[0] != '-' || tok == "--" {
		return false
	}
	if _, err := strconv.ParseFloat(tok, 64); err == nil {
		return false
	}
	return true
}

// splitFlag splits a flag token into its identifier and an inline "=value".
func splitFlag(tok string) (name, value string, hasValue bool) {
	if before, after, ok := strings.Cut(tok, "="); ok {
		return before, after, true
	}
	return tok, "", false
}

// findFlag searches the resolved chain leaf→root for a flag whose identifiers
// include name, returning its definition and the owning command-name scope.
func findFlag(chain []ResolvedCommand, name string) (FlagDef, string, bool) {
	for _, v := range slices.Backward(chain) {
		for _, f := range v.Flags {
			if slices.Contains(f.Identifiers, name) {
				return f, v.Name, true
			}
		}
	}
	return FlagDef{}, "", false
}

// findChild returns the sub-command of f matching tok by name or alias.
func findChild(f ResolvedCommand, tok string) (CommandDef, bool) {
	for _, c := range f.Commands {
		if c.Name == tok {
			return c, true
		}
		if slices.Contains(c.Aliases, tok) {
			return c, true
		}
	}
	return CommandDef{}, false
}

// KeyParser is the conventional registry key the generated main binds the
// [Parser] under (and handlers retrieve it by) — see [Program.Bind].
const KeyParser = "parser"

// parsedInputs is one invocation's parsed argv, indexed by position in the
// resolved command chain (root = 0 … leaf). [Parse] builds it via [parseInto] and
// reads it back through the reflective binder. Keying by chain position — not by
// command name — means two commands on a single path can never collide, and a
// statically-composed child still reads its inputs through its own generated types
// unchanged: those describe its own root→leaf tail of the chain, bound leaf-first.
type parsedInputs struct {
	scopes  []scopeInputs     // one entry per resolved chain frame, root → leaf
	argvSet []map[string]bool // per frame: logical flag names explicitly set on argv (not defaults, not env/config fallback)
}

// setOnArgv reports whether the flag with logical name was explicitly provided
// on argv in chain frame idx — the presence convention flag groups and
// dependencies enforce (a default or env/config fallback does not count).
func (p *parsedInputs) setOnArgv(idx int, name string) bool {
	if p == nil || idx < 0 || idx >= len(p.argvSet) || p.argvSet[idx] == nil {
		return false
	}
	return p.argvSet[idx][name]
}

// scopeInputs holds one chain frame's parsed values: flag values by logical name
// (a repeatable flag keeps every value) and the positional arguments.
type scopeInputs struct {
	flags map[string][]string
	args  []string
}

// ParseKind classifies a [ParseError] by what went wrong, so a funnel can
// branch on the failure WITHOUT matching the human message — the message is
// presentation, the kind is data. Most kinds are the end-user's to fix (a typo,
// a bad value); [ParseKindInternal] is a misuse of the parser API itself (a nil
// parser/context or a bad out argument) — still surfaced as a usage-shaped
// [*ParseError] for uniformity, but the author's bug.
type ParseKind int

const (
	// ParseKindUnspecified is the zero value: a [ParseError] whose construction
	// site did not classify it (a hand-built error, or a path predating EH5).
	ParseKindUnspecified         ParseKind = iota
	ParseKindUnknownFlag                   // an argv token looked like a flag no command on the chain declares
	ParseKindUnknownCommand                // a stray positional on a branch-only command (a mistyped sub-command)
	ParseKindNeedsValue                    // a value-taking flag was given no value
	ParseKindInvalidValue                  // a value could not be coerced/resolved (bad type, unreadable @file, malformed map, value on a no-value flag)
	ParseKindEnumViolation                 // a value was not one of a declared enum's members
	ParseKindConstraintViolation           // a declared bound or flag-group/dependency rule was violated
	ParseKindMissingRequired               // a required flag or argument was absent
	ParseKindNoArguments                   // a positional was given to a command that accepts none
	ParseKindTooManyArguments              // more positionals than the command's declared (non-variadic) arity
	ParseKindInternal                      // a parser API misuse: nil parser/context, or a bad out argument
)

// String renders the kind as a short, stable label (for logs and tests).
func (k ParseKind) String() string {
	switch k {
	case ParseKindUnknownFlag:
		return "unknown-flag"
	case ParseKindUnknownCommand:
		return "unknown-command"
	case ParseKindNeedsValue:
		return "needs-value"
	case ParseKindInvalidValue:
		return "invalid-value"
	case ParseKindEnumViolation:
		return "enum-violation"
	case ParseKindConstraintViolation:
		return "constraint-violation"
	case ParseKindMissingRequired:
		return "missing-required"
	case ParseKindNoArguments:
		return "no-arguments"
	case ParseKindTooManyArguments:
		return "too-many-arguments"
	case ParseKindInternal:
		return "internal"
	default:
		return "unspecified"
	}
}

// ParseError is a parse-time failure caused by bad input. It is data, not
// presentation: the message carries no opinions (no suggestions, no usage
// dump), and the structured fields let a handler compose its own response —
// switch on [ParseError.Kind] to branch, pair Token with Candidates and a bound
// [Suggestor] for "did you mean", or render help for Command. Handlers
// conventionally map it to exit code 2 (the usual CLI usage-error code). It
// unwraps to [ErrUsage], so CategoryOf classifies it as CategoryUsage; retrieve
// the fields with errors.As:
//
//	var pe *rotini.ParseError
//	if errors.As(err, &pe) {
//	    switch pe.Kind {
//	    case rotini.ParseKindUnknownFlag, rotini.ParseKindUnknownCommand:
//	        // pe.Token + pe.Candidates feed a Suggestor's "did you mean"
//	    case rotini.ParseKindMissingRequired:
//	        // prompt, or point at the help for pe.Command
//	    }
//	}
type ParseError struct {
	Kind       ParseKind // what went wrong, for branching without matching Msg (zero = ParseKindUnspecified)
	Msg        string    // the human-readable failure, opinion-free
	Command    string    // the command in whose scope parsing failed ("" when not command-scoped)
	Flag       string    // the flag involved, by the identifier or label used ("" when not flag-related)
	Token      string    // the offending argv token or value ("" when none)
	Candidates []string  // the vocabulary Token failed against — sibling commands, declared flags, enum members (nil when none applies)
}

func (e *ParseError) Error() string { return e.Msg }

func (e *ParseError) Unwrap() error { return ErrUsage }

// Parser is rotini's argument parser, and it is a *service*: a CLI binds it to the
// context registry under the key "parser" so that (1) parsing is opt-in — a CLI
// that wants raw argv binds nothing and reads Context.Args itself — and
// (2) the registry is a dependency-injection seam (the same handler code runs
// whether you bound the production parser or a double). A handler retrieves it and
// calls [Parser.Parse]:
//
//	// main.go
//	rth.Program.Bind(rotini.KeyParser, rotini.NewParser()).Execute()
//
//	// a handler
//	parser := rotini.MustGet[*rotini.Parser](rtx, rotini.KeyParser)
//	var in rtg.MycliInputs
//	err := parser.Parse(rtx, &in)
type Parser struct{}

// NewParser returns rotini's default [Parser], ready to bind under the "parser"
// registry key.
func NewParser() *Parser {
	return &Parser{}
}

// Parse binds the running command's arguments into out — a non-nil pointer to the
// typed inputs struct rtg emits (e.g. &rtg.MycliInputs{}) — using the resolved
// command and raw argv on rtx, in the json.Unmarshal style:
//
//	var in rtg.MycliInputs
//	if err := parser.Parse(rtx, &in); err != nil { /* handler owns it */ }
//
// It applies declared defaults and validates required/enum, then fills out by
// reflection from the `rotini:"…"` struct tags (each per-command field carries
// `scope=<command-name>`, each flag/argument field its logical name; built-ins and
// any encoding.TextUnmarshaler are coerced; a trailing []string absorbs remaining
// positionals). Parse returns an error when out is not a non-nil pointer, an
// unknown flag is given, a flag's value is missing, a required input is absent, or
// a value is outside a declared enum — print it (see [Usage]), rtx.Exit, or fall
// back to Context.Args.
func (p *Parser) Parse(rtx *Context, out any) error {
	store, chain, err := p.parseBind(rtx, out)
	if err != nil {
		return err
	}
	if err := validate(chain, store); err != nil {
		return err
	}
	if err := validateFlagGroups(chain, store); err != nil {
		return err
	}
	return validateFlagDependencies(chain, store)
}

// Deprecation is a deprecated CLI token found in this invocation's argv: the specific
// deprecated identifier/alias used, the kind of input, and that input's logical name. It
// is pure identification — the framework attaches no message and does nothing with it; the
// handler decides (print a warning, emit telemetry, fail the run, ignore). It implements
// error so it can be returned or printed directly.
type Deprecation struct {
	Kind       string // "flag" or "command"
	Name       string // the input's logical name (the flag/command name)
	Identifier string // the deprecated token actually used on argv (e.g. "--conf", "build")
}

func (d Deprecation) Error() string {
	return fmt.Sprintf("deprecated %s identifier %q was used", d.Kind, d.Identifier)
}

// Deprecations scans this invocation's argv against the spec's deprecated_identifiers and
// returns each deprecated token that was actually used — a command invoked via a deprecated
// alias, or a flag set via a deprecated identifier (the non-deprecated spellings are
// unaffected). It is a data feed only: the framework prints nothing; the handler decides
// what to do with each (warn, telemetry, exit, ignore). It does not parse and holds no
// parser state — call it any time the context's chain is resolved (typically after Parse).
func (p *Parser) Deprecations(rtx *Context) []Deprecation {
	if rtx == nil {
		return nil
	}
	argv := rtx.Args
	var out []Deprecation
	for _, frame := range rtx.Chain() {
		// A command invoked via one of its deprecated aliases (frame.Matched is the token
		// that resolved it).
		for _, alias := range frame.DeprecatedIdentifiers {
			if frame.Matched == alias {
				out = append(out, Deprecation{Kind: "command", Name: frame.Name, Identifier: alias})
				break
			}
		}
		// A flag set via one of its deprecated identifiers.
		for _, fd := range frame.Flags {
			for _, id := range fd.DeprecatedIdentifiers {
				if flagWasSet(argv, []string{id}) {
					out = append(out, Deprecation{Kind: "flag", Name: fd.Name, Identifier: id})
				}
			}
		}
	}
	return out
}

// parseBind parses argv into a store and binds it into out, but performs no
// required/enum/constraint validation — that is [validate]'s job. It is the shared
// front half of [Parser.Parse] (which then validates the argv-only store) and of the
// [Binder] (which first reconciles env/config fallbacks into the store, then
// validates last — so a required input is satisfiable from any source, not just
// argv). It returns the store and the resolved chain for that deferred validation.
func (p *Parser) parseBind(rtx *Context, out any) (*parsedInputs, []ResolvedCommand, error) {
	if p == nil {
		return nil, nil, &ParseError{Kind: ParseKindInternal, Msg: "rotini: nil parser"}
	}
	if rtx == nil {
		return nil, nil, &ParseError{Kind: ParseKindInternal, Msg: "rotini: parse on nil context"}
	}
	rv := reflect.ValueOf(out)
	if rv.Kind() != reflect.Pointer || rv.IsNil() {
		return nil, nil, &ParseError{Kind: ParseKindInternal, Msg: "rotini: Parse out argument must be a non-nil pointer to an inputs struct"}
	}
	chain := rtx.Chain()
	if len(chain) == 0 {
		return nil, nil, &ParseError{Kind: ParseKindInternal, Msg: "rotini: no command resolved for this context"}
	}
	store, err := parseInto(chain, rtx.Args, rtx.Stdin)
	if err != nil {
		return nil, nil, err
	}
	if err := bindInputs(rv.Elem(), store, chain); err != nil {
		return nil, nil, err
	}
	return store, chain, nil
}

// parseInto binds argv to an already-resolved chain, strictly: an unrecognized
// flag, or a flag missing its value, is a [ParseError]. Command tokens already in
// the chain are consumed; everything after the leaf command (and after "--") is a
// positional argument of the leaf. Declared defaults are applied. parseInto does
// not check required inputs or enums — that is [validate]'s job — so a handler can
// inspect what was supplied before deciding how strict to be.
func parseInto(chain []ResolvedCommand, argv []string, stdin io.Reader) (*parsedInputs, error) {
	store, err := parseArgvTokens(chain, argv, stdin)
	if err != nil {
		return nil, err
	}
	applyDefaults(chain, store)
	return store, nil
}

// parseArgvTokens is parseInto minus defaults: exactly what argv supplied,
// nothing more. It records each explicitly-set flag in the store's argvSet, the
// single source of truth for "set on the command line" (flag groups,
// dependencies, and the argv overlay layer all read it). stdin backs the
// from:stdin sentinel — a flag value of exactly "-" on a flag that opted in
// (it is only read when such a value actually appears).
func parseArgvTokens(chain []ResolvedCommand, argv []string, stdin io.Reader) (*parsedInputs, error) {
	store := &parsedInputs{
		scopes:  make([]scopeInputs, len(chain)),
		argvSet: make([]map[string]bool, len(chain)),
	}
	leaf := len(chain) - 1 // chain index of the leaf command
	depth := 1             // index of the next chain frame we might descend into
	startedArgs := false   // a positional has been seen: command descent is over
	terminated := false    // "--" has been seen: flag parsing is over too

	addFlag := func(idx int, fd FlagDef, value string) error {
		value, err := resolveFlagValue(fd, value, stdin)
		if err != nil {
			return err
		}
		if store.scopes[idx].flags == nil {
			store.scopes[idx].flags = map[string][]string{}
		}
		store.scopes[idx].flags[fd.Name] = append(store.scopes[idx].flags[fd.Name], value)
		if store.argvSet[idx] == nil {
			store.argvSet[idx] = map[string]bool{}
		}
		store.argvSet[idx][fd.Name] = true
		return nil
	}
	addArg := func(value string) {
		store.scopes[leaf].args = append(store.scopes[leaf].args, value)
	}

	// Passthrough: once the chain's passthrough leaf has been entered, every
	// remaining token — flag-shaped, "--", anything — is a raw positional.
	passthrough := func() bool {
		return chain[len(chain)-1].Passthrough && depth == len(chain)
	}

	for i := 0; i < len(argv); i++ {
		tok := argv[i]

		if passthrough() {
			addArg(tok)
			continue
		}

		if !terminated && tok == "--" { // explicit end of flags; the rest are
			terminated = true  // positional, even flag-looking tokens (and any
			startedArgs = true // further "--" is a literal positional)
			continue
		}

		if !terminated && isFlag(tok) {
			name, inline, hasInline := splitFlag(tok)
			fdef, idx, ok := findFlagIndex(chain, name)
			if !ok {
				// No exact identifier — try POSIX clustered short flags: -vh → -v
				// -h, -n5 → -n 5. Long flags ("--" prefix) never cluster.
				if isShortCluster(name) {
					consumed, err := parseCluster(chain, name[1:], inline, hasInline, argv, i, addFlag)
					if err != nil {
						return nil, err
					}
					i += consumed
					continue
				}
				return nil, &ParseError{
					Kind:       ParseKindUnknownFlag,
					Msg:        fmt.Sprintf("unknown flag %q", name),
					Flag:       name,
					Token:      name,
					Candidates: chainFlagIdentifiers(chain),
				}
			}
			var value string
			switch {
			case fdef.Type == "count":
				if hasInline {
					return nil, &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("flag %q counts occurrences and takes no value", name), Flag: name}
				}
				value = "1" // each occurrence appends one marker; the binder tallies them
			case fdef.Type == "bool":
				value = "true"
				if hasInline {
					value = inline
				}
			case hasInline:
				value = inline
			default:
				i++
				if i >= len(argv) {
					return nil, &ParseError{Kind: ParseKindNeedsValue, Msg: fmt.Sprintf("flag %q needs a value", name), Flag: name}
				}
				value = argv[i]
			}
			if err := addFlag(idx, fdef, value); err != nil {
				return nil, err
			}
			continue
		}

		// A non-flag token: consume it as the next command in the chain if it is
		// one, otherwise it (and everything after) is a positional of the leaf.
		if !startedArgs && depth < len(chain) {
			if c, ok := findChild(chain[depth-1], tok); ok && c.Name == chain[depth].Name {
				depth++
				continue
			}
		}
		startedArgs = true
		addArg(tok)
	}

	return store, nil
}

// validate enforces the declarative constraints on the resolved chain against a
// parsed store: a stray positional on a branch-only command is a mistyped
// sub-command; required flags/arguments must be present (or defaulted); and any
// value for a flag or argument that declares an Enum must be one of its members.
// It is the strict half of [Parse]; a handler that wants laxer behavior can bind
// inputs without it.
func validate(chain []ResolvedCommand, store *parsedInputs) error {
	leaf := chain[len(chain)-1]
	si := store.scopes[len(chain)-1]

	// A stray positional on a command that branches but takes no arguments is a
	// mistyped sub-command, not an argument. The error carries the sibling
	// vocabulary so a handler (with a bound [Suggestor]) can offer corrections.
	if len(leaf.Commands) > 0 && len(leaf.Arguments) == 0 && len(si.args) > 0 {
		tok := si.args[0]
		return &ParseError{
			Kind:       ParseKindUnknownCommand,
			Msg:        fmt.Sprintf("unknown command %q for %q", tok, leaf.Name),
			Command:    leaf.Name,
			Token:      tok,
			Candidates: childCommandNames(leaf),
		}
	}

	if err := requiredErrors(chain, store); err != nil {
		return err
	}

	for i, f := range chain {
		fsi := store.scopes[i]
		for _, fd := range f.Flags {
			vals := fsi.flags[fd.Name]
			for _, v := range vals {
				if len(fd.Enum) > 0 && !slices.Contains(fd.Enum, v) {
					return &ParseError{
						Kind:       ParseKindEnumViolation,
						Msg:        fmt.Sprintf("invalid value %q for %s (one of: %s)", redactValue(v, fd.Secret), flagLabel(fd), strings.Join(fd.Enum, ", ")),
						Flag:       flagLabel(fd),
						Token:      redactValue(v, fd.Secret),
						Candidates: fd.Enum,
					}
				}
				if isMapType(fd.Type) && !strings.Contains(v, "=") {
					return &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("%s expects key=value pairs (got %q)", flagLabel(fd), redactValue(v, fd.Secret)), Flag: flagLabel(fd)}
				}
			}
			if err := checkConstraints(flagLabel(fd), fd.Type, fd.Constraints, vals, fd.Secret); err != nil {
				return err
			}
		}
	}

	// With no variadic argument to absorb them, more positionals than declared
	// arguments is a usage error rather than a silent drop. (A branch-only command's
	// stray positional was handled above as a mistyped sub-command.)
	if n := len(leaf.Arguments); !hasVariadicArg(leaf.Arguments) && len(si.args) > n {
		if n == 0 {
			return &ParseError{Kind: ParseKindNoArguments, Msg: fmt.Sprintf("%q takes no arguments (got %d)", leaf.Name, len(si.args)), Command: leaf.Name}
		}
		return &ParseError{Kind: ParseKindTooManyArguments, Msg: fmt.Sprintf("%q accepts at most %d %s (got %d)", leaf.Name, n, plural("argument", n), len(si.args)), Command: leaf.Name}
	}

	for i, ad := range leaf.Arguments {
		var vals []string
		switch {
		case ad.Variadic:
			if i < len(si.args) {
				vals = si.args[i:]
			} // an absent variadic still gets a MinItems check below
		case i < len(si.args):
			vals = si.args[i : i+1]
		default:
			continue // a non-variadic argument that was not provided — requiredErrors covers absence
		}
		for _, v := range vals {
			if len(ad.Enum) > 0 && !slices.Contains(ad.Enum, v) {
				return &ParseError{
					Kind:       ParseKindEnumViolation,
					Msg:        fmt.Sprintf("invalid value %q for <%s> (one of: %s)", redactValue(v, ad.Secret), ad.Name, strings.Join(ad.Enum, ", ")),
					Token:      redactValue(v, ad.Secret),
					Candidates: ad.Enum,
				}
			}
		}
		if err := checkConstraints("<"+ad.Name+">", ad.Type, ad.Constraints, vals, ad.Secret); err != nil {
			return err
		}
	}
	return nil
}

// hasVariadicArg reports whether any of a command's arguments is variadic — when one
// is, it slurps every trailing positional, so no "too many arguments" can occur.
func hasVariadicArg(args []ArgDef) bool {
	for _, a := range args {
		if a.Variadic {
			return true
		}
	}
	return false
}

// checkConstraints enforces an input's declared numeric/string/array bounds against
// the value(s) supplied for it (one element for a scalar; possibly many for a
// repeatable flag or variadic argument). label is the human-facing identifier; typ is
// the resolved Go type. A zero bound (or empty pattern) is unset and skipped. Numeric
// bounds apply to the full int/uint/float family, length/pattern to strings, and item
// counts to arrays/maps; for a repeatable input the per-value checks apply to each
// ELEMENT (a []int's minimum bounds every occurrence). A constraint declared on a
// type none of those fit cannot come from a valid spec (lintConstraintApplicability
// rejects it at validate time); a hand-built Definition that does it anyway is
// skipped here, not guessed at. When secret is true the offending value (and its
// length) is redacted in the error.
func checkConstraints(label, typ string, c Constraints, values []string, secret bool) error {
	if isArrayType(typ) || isMapType(typ) {
		switch n := len(values); {
		case c.MinItems > 0 && n < c.MinItems:
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s needs at least %d %s (got %d)", label, c.MinItems, plural("value", c.MinItems), n)}
		case c.MaxItems > 0 && n > c.MaxItems:
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s accepts at most %d %s (got %d)", label, c.MaxItems, plural("value", c.MaxItems), n)}
		}
	}
	elem := constraintElemType(typ)
	for _, v := range values {
		switch {
		case isNumericType(elem):
			n, err := strconv.ParseFloat(v, 64)
			if err != nil {
				continue // not range-checkable; coerce already tolerates malformed input
			}
			if c.Minimum != nil && n < *c.Minimum {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be >= %s (got %s)", label, formatNum(*c.Minimum), redactValue(v, secret))}
			}
			if c.Maximum != nil && n > *c.Maximum {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be <= %s (got %s)", label, formatNum(*c.Maximum), redactValue(v, secret))}
			}
			if c.ExclusiveMinimum != nil && n <= *c.ExclusiveMinimum {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be > %s (got %s)", label, formatNum(*c.ExclusiveMinimum), redactValue(v, secret))}
			}
			if c.ExclusiveMaximum != nil && n >= *c.ExclusiveMaximum {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be < %s (got %s)", label, formatNum(*c.ExclusiveMaximum), redactValue(v, secret))}
			}
			if c.MultipleOf != nil && !isMultipleOf(n, *c.MultipleOf) {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be a multiple of %s (got %s)", label, formatNum(*c.MultipleOf), redactValue(v, secret))}
			}
		case elem == "string":
			ln := utf8.RuneCountInString(v)
			gotLen := strconv.Itoa(ln)
			if secret {
				gotLen = "[redacted]"
			}
			if c.MinLength > 0 && ln < c.MinLength {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be at least %d %s long (got %s)", label, c.MinLength, plural("character", c.MinLength), gotLen)}
			} else if c.MaxLength > 0 && ln > c.MaxLength {
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must be at most %d %s long (got %s)", label, c.MaxLength, plural("character", c.MaxLength), gotLen)}
			}
			if c.Pattern != "" {
				if ok, err := regexp.MatchString(c.Pattern, v); err == nil && !ok {
					return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s must match %s (got %q)", label, c.Pattern, redactValue(v, secret))}
				}
			}
		}
	}
	return nil
}

// isMultipleOf reports whether n is an integer multiple of m (JSON Schema
// semantics: the division yields an integer), with a small relative tolerance
// for float representation (1.2 / 0.1 must count). A non-positive m never
// matches — validation rejects it before it gets here.
func isMultipleOf(n, m float64) bool {
	if m <= 0 {
		return false
	}
	q := n / m
	return math.Abs(q-math.Round(q)) < 1e-9
}

// redactValue returns "[redacted]" for a secret input, else the value unchanged — so a
// secret flag/argument's value never appears in usage or validation errors.
func redactValue(v string, secret bool) string {
	if secret {
		return "[redacted]"
	}
	return v
}

// validateFlagGroups enforces each command's cross-flag presence rules (mutually
// exclusive / required together / one-of / at-least-one). "Set" means explicitly
// provided on argv — a default or env/config fallback does not count (matching the
// command-line-presence convention of cobra/clap) — read from the store's argvSet
// (which, unlike a raw argv re-scan, also sees flags set inside short clusters).
// Each violation is a usage error.
func validateFlagGroups(chain []ResolvedCommand, store *parsedInputs) error {
	for i, f := range chain {
		for _, g := range f.FlagGroups {
			all := make([]string, 0, len(g.Flags))
			var set []string
			for _, name := range g.Flags {
				label := "--" + name
				if fd, ok := findFlagDef(f.Flags, name); ok {
					label = flagLabel(fd)
				}
				all = append(all, label)
				if store.setOnArgv(i, name) {
					set = append(set, label)
				}
			}
			if err := checkFlagGroup(g.Kind, set, all); err != nil {
				return err
			}
		}
	}
	return nil
}

// validateFlagDependencies enforces each command's conditional cross-flag requirements:
// when a dependency's When flag is explicitly set on argv, every flag it Requires must
// also be set. "Set" follows the same explicit-argv convention as flag groups (the
// store's argvSet); a missing requirement is a usage error naming the absent flag(s)
// and the trigger.
func validateFlagDependencies(chain []ResolvedCommand, store *parsedInputs) error {
	for i, f := range chain {
		for _, dep := range f.FlagDependencies {
			whenFD, ok := findFlagDef(f.Flags, dep.When)
			if !ok {
				continue // unknown trigger flag (a spec lint rejects this) — nothing to enforce
			}
			whenLabel := flagLabel(whenFD)
			if !store.setOnArgv(i, dep.When) {
				continue // the trigger is absent — the requirement does not apply
			}
			var missing []string
			for _, name := range dep.Requires {
				label := "--" + name
				if fd, ok := findFlagDef(f.Flags, name); ok {
					if store.setOnArgv(i, name) {
						continue
					}
					label = flagLabel(fd)
				}
				missing = append(missing, label)
			}
			if len(missing) > 0 {
				noun, verb := "flag", "is"
				if len(missing) > 1 {
					noun, verb = "flags", "are"
				}
				return &ParseError{Kind: ParseKindConstraintViolation, Msg: fmt.Sprintf("%s %s %s required when %s is set", noun, joinAnd(missing), verb, whenLabel)}
			}
		}
	}
	return nil
}

// checkFlagGroup applies one group's rule given the labels set and the full membership.
func checkFlagGroup(kind FlagGroupKind, set, all []string) error {
	switch kind {
	case FlagGroupMutuallyExclusive:
		if len(set) > 1 {
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: "flags " + joinAnd(set) + " are mutually exclusive"}
		}
	case FlagGroupRequiredTogether:
		if n := len(set); n > 0 && n < len(all) {
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: "flags " + strings.Join(all, ", ") + " must be used together"}
		}
	case FlagGroupOneOf:
		switch {
		case len(set) == 0:
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: "exactly one of " + strings.Join(all, ", ") + " is required"}
		case len(set) > 1:
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: "flags " + joinAnd(set) + " are mutually exclusive"}
		}
	case FlagGroupAtLeastOne:
		if len(set) == 0 {
			return &ParseError{Kind: ParseKindConstraintViolation, Msg: "at least one of " + strings.Join(all, ", ") + " is required"}
		}
	}
	return nil
}

// joinAnd formats a list as "a", "a and b", or "a, b, and c".
func joinAnd(items []string) string {
	switch len(items) {
	case 0:
		return ""
	case 1:
		return items[0]
	case 2:
		return items[0] + " and " + items[1]
	default:
		return strings.Join(items[:len(items)-1], ", ") + ", and " + items[len(items)-1]
	}
}

// numericFamily is every resolved type string whose values are range-checkable
// numbers — the full int/uint/float vocabulary plus the JSON-Schema aliases
// (hand-built Definitions may use either spelling). The old allowlist was
// int|float64 only, which silently ignored bounds on every other numeric type
// (production-readiness R1).
var numericFamily = map[string]bool{
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
	"float32": true, "float64": true,
	"integer": true, "number": true,
}

func isNumericType(typ string) bool { return numericFamily[typ] }

// constraintElemType is the type a constraint's PER-VALUE checks apply to: the
// element type for an array/repeatable input (each occurrence is one value),
// the type itself otherwise. Item-count bounds stay on the collection.
func constraintElemType(typ string) string {
	return strings.TrimPrefix(typ, "[]")
}

func isArrayType(typ string) bool { return strings.HasPrefix(typ, "[]") }

// isMapType reports whether typ is a map type ("map[...]…"), whose flag takes repeated
// key=value pairs.
func isMapType(typ string) bool { return strings.HasPrefix(typ, "map[") }

// formatNum renders a numeric bound without a trailing ".000…".
func formatNum(f float64) string { return strconv.FormatFloat(f, 'g', -1, 64) }

// applyDefaults fills in declared flag and trailing-argument defaults for inputs
// the user did not provide, so handlers and required-checks see them.
func applyDefaults(chain []ResolvedCommand, store *parsedInputs) {
	for i, f := range chain {
		for _, fd := range f.Flags {
			if fd.Default == "" {
				continue
			}
			if store.scopes[i].flags == nil {
				store.scopes[i].flags = map[string][]string{}
			}
			if _, ok := store.scopes[i].flags[fd.Name]; !ok {
				store.scopes[i].flags[fd.Name] = []string{fd.Default}
			}
		}
	}

	leaf := len(chain) - 1
	args := chain[leaf].Arguments
	for i := len(store.scopes[leaf].args); i < len(args); i++ {
		if args[i].Default == "" {
			break // can't fill a gap before a defaultless argument
		}
		store.scopes[leaf].args = append(store.scopes[leaf].args, args[i].Default)
	}
}

// requiredErrors reports any required flags or arguments (across the resolved
// chain / on the leaf) that were neither provided nor defaulted.
func requiredErrors(chain []ResolvedCommand, store *parsedInputs) error {
	var missing []string
	for i, f := range chain {
		si := store.scopes[i]
		for _, fd := range f.Flags {
			if fd.Required {
				if _, ok := si.flags[fd.Name]; !ok {
					missing = append(missing, flagLabel(fd))
				}
			}
		}
	}
	leaf := chain[len(chain)-1]
	si := store.scopes[len(chain)-1]
	for i, ad := range leaf.Arguments {
		if ad.Required && i >= len(si.args) {
			missing = append(missing, "<"+ad.Name+">")
		}
	}
	if len(missing) > 0 {
		return &ParseError{Kind: ParseKindMissingRequired, Msg: "missing required " + plural("input", len(missing)) + ": " + strings.Join(missing, ", ")}
	}
	return nil
}

func flagLabel(f FlagDef) string {
	if len(f.Identifiers) > 0 {
		return f.Identifiers[0]
	}
	return "--" + f.Name
}

func plural(word string, n int) string {
	if n == 1 {
		return word
	}
	return word + "s"
}

// resolveFlagValue applies a flag's declared acquisition modes (spec `from:`)
// to one argv-supplied value. With "file", a value starting with '@' is
// replaced by the named file's contents; with "stdin", a value of exactly "-"
// is replaced by the piped stdin (which must not be empty — giving "-" demands
// a pipe). Resolved text is whitespace-trimmed (token files end in a newline)
// and then flows through the same coercion/enum/constraint checks as a literal
// value — the flag's value IS the resolved text. Without the matching `from`
// mode, '@' and '-' are ordinary characters. Declared defaults and env/config
// fallbacks never resolve — sentinels are argv grammar.
func resolveFlagValue(fd FlagDef, value string, stdin io.Reader) (string, error) {
	switch {
	case strings.HasPrefix(value, "@") && slices.Contains(fd.From, "file"):
		data, err := os.ReadFile(value[1:])
		if err != nil {
			return "", &ParseError{
				Kind: ParseKindInvalidValue,
				Msg:  fmt.Sprintf("%s: cannot read %q: %v", flagLabel(fd), value, err),
				Flag: flagLabel(fd), Token: value,
			}
		}
		return strings.TrimSpace(string(data)), nil
	case value == "-" && slices.Contains(fd.From, "stdin"):
		data, err := readStdin(stdin)
		if err != nil {
			return "", &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("%s: read stdin: %v", flagLabel(fd), err), Flag: flagLabel(fd)}
		}
		if len(data) == 0 {
			return "", &ParseError{
				Kind: ParseKindInvalidValue,
				Msg:  fmt.Sprintf("%s: stdin is empty — %q asks for a piped value", flagLabel(fd), "-"),
				Flag: flagLabel(fd),
			}
		}
		return strings.TrimSpace(string(data)), nil
	}
	return value, nil
}

// isShortCluster reports whether name is a candidate POSIX short-flag cluster: a
// single-dash token with more than one character (e.g. "-vh", "-n5") — as opposed
// to a long flag ("--x") or a bare short flag ("-v", which the exact match already
// handled). Clustering is tried only after an exact-identifier lookup misses.
func isShortCluster(name string) bool {
	return len(name) > 2 && name[0] == '-' && name[1] != '-'
}

// parseCluster expands a POSIX short-flag cluster (body is the characters after
// the leading '-', e.g. "vh" from -vh, or "n5" from -n5) against the chain. Each
// character is a single short flag, looked up as "-<c>": booleans are set in turn,
// and the first value-taking flag consumes the rest of the cluster, then the
// inline "=value", then the next argv token — whichever is present. It returns how
// many extra argv tokens it consumed (0 or 1).
func parseCluster(chain []ResolvedCommand, body, inline string, hasInline bool, argv []string, i int, addFlag func(idx int, fd FlagDef, value string) error) (int, error) {
	for k := range len(body) {
		short := "-" + body[k:k+1]
		fdef, idx, ok := findFlagIndex(chain, short)
		if !ok {
			return 0, &ParseError{Kind: ParseKindUnknownFlag, Msg: fmt.Sprintf("unknown flag %q", short), Flag: short, Token: short}
		}
		if fdef.Type == "bool" || fdef.Type == "count" {
			v := "true"
			if fdef.Type == "count" {
				v = "1"
			}
			if err := addFlag(idx, fdef, v); err != nil {
				return 0, err
			}
			continue
		}
		// A value-taking flag ends the cluster: its value is whatever follows.
		switch rest := body[k+1:]; {
		case rest != "":
			return 0, addFlag(idx, fdef, rest)
		case hasInline:
			return 0, addFlag(idx, fdef, inline)
		default:
			if i+1 >= len(argv) {
				return 0, &ParseError{Kind: ParseKindNeedsValue, Msg: fmt.Sprintf("flag %q needs a value", short), Flag: short}
			}
			return 1, addFlag(idx, fdef, argv[i+1])
		}
	}
	// Every flag in the cluster was boolean; a trailing "=value" has nothing to bind.
	if hasInline {
		return 0, &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("flag %q does not take a value", "-"+body), Flag: "-" + body}
	}
	return 0, nil
}

// findFlagIndex searches the resolved chain leaf→root for a flag whose identifiers
// include name, returning its definition and the chain index of the command that
// owns it.
func findFlagIndex(chain []ResolvedCommand, name string) (FlagDef, int, bool) {
	for i, v := range slices.Backward(chain) {
		for _, f := range v.Flags {
			if slices.Contains(f.Identifiers, name) {
				return f, i, true
			}
		}
	}
	return FlagDef{}, -1, false
}

// childCommandNames is the dispatchable-name vocabulary of a command's visible
// children — sub-command names and aliases, plus declared remotes — for a
// mistyped-command [ParseError]'s Candidates.
func childCommandNames(cur ResolvedCommand) []string {
	var names []string
	for _, c := range cur.Commands {
		if c.Hidden {
			continue
		}
		names = append(names, c.Name)
		names = append(names, c.Aliases...)
	}
	for _, r := range cur.Remotes {
		names = append(names, r.Name)
		names = append(names, r.Aliases...)
	}
	return names
}

// chainFlagIdentifiers is the declared, non-hidden flag vocabulary of the whole
// resolved chain (ancestor flags resolve on descendants), for an unknown-flag
// [ParseError]'s Candidates.
func chainFlagIdentifiers(chain []ResolvedCommand) []string {
	var ids []string
	for _, v := range slices.Backward(chain) {
		for _, f := range v.Flags {
			if !f.Hidden {
				ids = append(ids, f.Identifiers...)
			}
		}
	}
	return ids
}

// bindInputs fills a <Cmd>Inputs struct: one field per command on the resolved
// path, in root→leaf order. The fields bind to the tail of the chain aligned at
// the leaf, so each command's inputs come from the right frame no matter how deep
// it was reached — including a statically-composed subtree reached under extra
// parent frames, which simply go unbound.
func bindInputs(v reflect.Value, p *parsedInputs, chain []ResolvedCommand) error {
	if v.Kind() != reflect.Struct {
		return nil
	}
	offset := len(p.scopes) - v.NumField()
	if offset < 0 {
		return nil // the struct names more commands than the chain has frames
	}
	for i := range v.NumField() {
		if err := bindCommandInputs(v.Field(i), p.scopes[offset+i], chain[offset+i]); err != nil {
			return err
		}
	}
	return nil
}

// bindCommandInputs fills a <Cmd>CommandInputs struct's Flags and Arguments.
func bindCommandInputs(v reflect.Value, si scopeInputs, frame ResolvedCommand) error {
	if v.Kind() != reflect.Struct {
		return nil
	}
	t := v.Type()
	for i := range v.NumField() {
		switch t.Field(i).Name {
		case "Flags":
			if err := bindFlags(v.Field(i), si.flags, frame.Flags); err != nil {
				return err
			}
		case "Arguments":
			if err := bindArgs(v.Field(i), si.args); err != nil {
				return err
			}
		}
	}
	return nil
}

// bindFlags fills a <Cmd>Flags struct by matching each field's `rotini:"<name>"`
// tag against the parsed flag values, surfacing a coercion failure as a usage error
// naming the flag (by its CLI identifiers).
func bindFlags(v reflect.Value, flags map[string][]string, defs []FlagDef) error {
	if v.Kind() != reflect.Struct {
		return nil
	}
	t := v.Type()
	for i := range v.NumField() {
		name := t.Field(i).Tag.Get("rotini")
		if name == "" {
			continue
		}
		raw, ok := flags[name]
		if !ok {
			continue
		}
		if def, ok := findFlagDef(defs, name); ok {
			switch {
			case def.DottedKeys:
				if err := coerceMapDotted(v.Field(i), raw); err != nil {
					return &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("%s: %v", labelForFlag(defs, name), err), Flag: labelForFlag(defs, name)}
				}
				continue
			case def.Type == "count":
				// Each argv occurrence appended one marker; the field is the tally.
				if f := v.Field(i); f.CanSet() && f.Kind() == reflect.Int {
					f.SetInt(int64(len(raw)))
				}
				continue
			}
		}
		if err := coerce(v.Field(i), raw); err != nil {
			return &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("%s: %v", labelForFlag(defs, name), err), Flag: labelForFlag(defs, name)}
		}
	}
	return nil
}

// labelForFlag is a flag's CLI label (its identifiers) for error messages, falling back
// to the logical name when the definition isn't found.
func labelForFlag(defs []FlagDef, name string) string {
	for _, d := range defs {
		if d.Name == name {
			return flagLabel(d)
		}
	}
	return name
}

// bindArgs fills a <Cmd>Arguments struct positionally; a trailing []string field
// is variadic and absorbs all remaining positionals. A coercion failure is a usage
// error naming the argument.
func bindArgs(v reflect.Value, args []string) error {
	if v.Kind() != reflect.Struct {
		return nil
	}
	t := v.Type()
	idx := 0
	for i := range v.NumField() {
		f := v.Field(i)
		label := "<" + t.Field(i).Tag.Get("rotini") + ">"
		if f.Kind() == reflect.Slice { // a slice argument is variadic, whatever its element type
			if err := coerce(f, args[min(idx, len(args)):]); err != nil {
				return &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("%s: %v", label, err)}
			}
			idx = len(args)
			continue
		}
		if idx < len(args) {
			if err := coerce(f, args[idx:idx+1]); err != nil {
				return &ParseError{Kind: ParseKindInvalidValue, Msg: fmt.Sprintf("%s: %v", label, err)}
			}
			idx++
		}
	}
	return nil
}

var (
	durationType        = reflect.TypeFor[time.Duration]()
	textUnmarshalerType = reflect.TypeFor[encoding.TextUnmarshaler]()
)

// coerce sets f from the raw string value(s), returning an error when a value cannot be
// parsed into f's type — including a custom type's own [encoding.TextUnmarshaler] error,
// the per-type parse+validate hook. (The caller turns that into a usage error naming the
// flag/argument.) It never panics: an unparseable value is reported, not silently zeroed.
func coerce(f reflect.Value, raw []string) error {
	if len(raw) == 0 {
		return nil
	}
	if f.Kind() == reflect.Pointer {
		if f.IsNil() {
			f.Set(reflect.New(f.Type().Elem()))
		}
		return coerce(f.Elem(), raw)
	}
	last := raw[len(raw)-1]

	if f.Type() == durationType {
		d, err := time.ParseDuration(last)
		if err != nil {
			return notValid(last, "duration")
		}
		f.SetInt(int64(d))
		return nil
	}
	if f.CanAddr() && f.Addr().Type().Implements(textUnmarshalerType) {
		if err := f.Addr().Interface().(encoding.TextUnmarshaler).UnmarshalText([]byte(last)); err != nil {
			return fmt.Errorf("%q is not a valid %s (%w)", last, f.Type(), err)
		}
		return nil
	}

	switch f.Kind() {
	case reflect.Bool:
		b, err := strconv.ParseBool(last)
		if err != nil {
			return notValid(last, "boolean")
		}
		f.SetBool(b)
	case reflect.String:
		f.SetString(last)
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		n, err := strconv.ParseInt(last, 10, 64)
		if err != nil {
			return notValid(last, "integer")
		}
		f.SetInt(n)
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		n, err := strconv.ParseUint(last, 10, 64)
		if err != nil {
			return notValid(last, "non-negative integer")
		}
		f.SetUint(n)
	case reflect.Float32, reflect.Float64:
		x, err := strconv.ParseFloat(last, 64)
		if err != nil {
			return notValid(last, "number")
		}
		f.SetFloat(x)
	case reflect.Slice:
		return coerceSlice(f, raw)
	case reflect.Map:
		return coerceMap(f, raw)
	case reflect.Interface:
		if f.Type().NumMethod() != 0 {
			return unsupportedType(f.Type())
		}
		f.Set(reflect.ValueOf(last)) // an `any` input holds the raw string
	default:
		return unsupportedType(f.Type())
	}
	return nil
}

// unsupportedType is the loud refusal for a field type coerce has no rule for:
// silence here would zero the field and hide a spec/codegen mistake. The fix is
// the documented contract — give the type an UnmarshalText.
func unsupportedType(t reflect.Type) error {
	return fmt.Errorf("cannot parse into %s — the type must implement encoding.TextUnmarshaler", t)
}

// coerceSlice fills a slice field from the raw values (one per repeated flag
// occurrence, or the trailing positionals for a variadic argument), coercing
// each element into the slice's element type — []string verbatim, []int parsed,
// []time.Duration / TextUnmarshaler elements through their own parsers.
func coerceSlice(f reflect.Value, raw []string) error {
	out := reflect.MakeSlice(f.Type(), len(raw), len(raw))
	for i, r := range raw {
		if err := coerce(out.Index(i), []string{r}); err != nil {
			return err
		}
	}
	f.Set(out)
	return nil
}

// notValid is the standard "value isn't a <type>" coercion error.
func notValid(value, typeName string) error {
	return fmt.Errorf("%q is not a valid %s", value, typeName)
}

// coerceMap fills a string-keyed map field from raw "key=value" pairs (one per repeated
// flag occurrence), splitting on the first '='. The value is coerced into the map's
// element type (string/int/…); an `any` element stores the raw string. Later pairs win
// on a duplicate key. Malformed (no '=') pairs are skipped — validation rejects them. A
// value that doesn't parse into the element type is returned as an error.
// coerceMapDotted fills a map[string]any flag (spec dotted_keys) from raw
// "key=value" pairs whose keys are '.'-separated paths into nested maps:
// "image.tag=v2" → m["image"].(map[string]any)["tag"] = "v2". Each assignment
// overwrites whatever sits at its path (creating intermediate maps as needed),
// so later pairs win — including a pair that replaces a scalar with a subtree
// or vice versa. Malformed (no '=') pairs are skipped — validation rejects
// them; an empty path segment ("a..b", ".a", "a.") is an error.
func coerceMapDotted(f reflect.Value, raw []string) error {
	m := map[string]any{}
	if !reflect.TypeFor[map[string]any]().AssignableTo(f.Type()) {
		return fmt.Errorf("dotted keys need a map[string]any flag, not %s", f.Type())
	}
	for _, pair := range raw {
		k, v, ok := strings.Cut(pair, "=")
		if !ok {
			continue
		}
		segs := strings.Split(k, ".")
		if slices.Contains(segs, "") {
			return fmt.Errorf("invalid key path %q — empty segment", k)
		}
		cur := m
		for _, seg := range segs[:len(segs)-1] {
			next, ok := cur[seg].(map[string]any)
			if !ok {
				next = map[string]any{}
				cur[seg] = next
			}
			cur = next
		}
		cur[segs[len(segs)-1]] = v
	}
	f.Set(reflect.ValueOf(m))
	return nil
}

func coerceMap(f reflect.Value, raw []string) error {
	kt := f.Type().Key()
	if kt.Kind() != reflect.String {
		return nil // only string-keyed maps are supported
	}
	et := f.Type().Elem()
	m := reflect.MakeMapWithSize(f.Type(), len(raw))
	for _, pair := range raw {
		k, v, ok := strings.Cut(pair, "=")
		if !ok {
			continue
		}
		ev := reflect.New(et).Elem()
		if ev.Kind() == reflect.Interface {
			ev.Set(reflect.ValueOf(v))
		} else if err := coerce(ev, []string{v}); err != nil {
			return fmt.Errorf("value for key %q: %w", k, err)
		}
		m.SetMapIndex(reflect.ValueOf(k).Convert(kt), ev)
	}
	f.Set(m)
	return nil
}

// trapSignals are the OS signals rotini's handler traps when signal handling is active —
// by default whenever the caller supplies no context, and always under [Program.WithSignals]
// (which may also override the set). It is a package var, not a constant, so a white-box
// test can swap in a benign signal. The default action on the first signal is a graceful
// shutdown (cancel the run context + halt the lifecycle so teardown runs); a second signal
// forces exit with forceExitCode.
var trapSignals = []os.Signal{os.Interrupt, syscall.SIGTERM}

// forceExitCode is the status a second signal exits with (128 + SIGINT), the
// conventional "interrupted" code.
const forceExitCode = 130

// signalExitCode maps a trapped signal to its conventional exit status, 128 + signum
// (SIGINT→130, SIGTERM→143, SIGHUP→129, …). A signal carrying no numeric value falls back
// to forceExitCode.
func signalExitCode(s os.Signal) int {
	if sig, ok := s.(syscall.Signal); ok {
		return 128 + int(sig)
	}
	return forceExitCode
}

// signalTrapMode resolves whether rotini installs its signal trap, decoupling that choice
// from context ownership. The zero value is signalAuto — trap iff the caller supplied no
// context (the historical behavior). [Program.WithoutSignalHandling] forces it off;
// [Program.WithSignals] forces it on (with a custom signal set).
type signalTrapMode int

const (
	signalAuto signalTrapMode = iota // trap iff no WithContext (default)
	signalOff                        // WithoutSignalHandling(): never trap
	signalOn                         // WithSignals(...): always trap
)

// ExitCode returns a context-cancellation cause that tells rotini which process
// exit code to use when that cancellation halts the run. Pass it to the cancel
// function of a [Program.WithContext] context (Go 1.21+):
//
//	ctx, cancel := context.WithCancelCause(parent)
//	prog.WithContext(ctx)
//	cancel(rotini.ExitCode(3)) // exits 3
//
// It also composes with timeouts, e.g. exit 124 on a deadline:
//
//	ctx, cancel := context.WithTimeoutCause(parent, 5*time.Second, rotini.ExitCode(124))
//
// A handler reaches the same cancel function via the registry — bind it in main
// (`Bind("cancel", cancel)`) and call `MustGet[context.CancelCauseFunc](rtx,
// "cancel")(rotini.ExitCode(3))`. Canceling WITHOUT an ExitCode cause (a plain
// cancel or deadline) still halts cleanly, with the code falling through to the
// normal resolution (0 unless a handler recorded an error or fault). Cancellation
// is cooperative — it never preempts a running hook — and teardown always runs.
// See [Program.WithContext].
func ExitCode(code int) error { return exitCodeError{code: code} }

// exitCodeError carries a process exit code as a context-cancellation cause.
type exitCodeError struct{ code int }

func (e exitCodeError) Error() string {
	return fmt.Sprintf("rotini: run canceled (exit code %d)", e.code)
}

// canceledExitCode resolves the exit code recorded when a canceled run context
// halts the lifecycle: the code carried by the cancellation cause — the caller's
// cancel (via [ExitCode]) or the default signal trap attach one — or 0 (a clean
// stop that defers to the normal exit-code resolution) when none was.
func canceledExitCode(ctx context.Context) int {
	if ec, ok := errors.AsType[exitCodeError](context.Cause(ctx)); ok {
		return ec.code
	}
	return 0
}

type Program struct {
	ctx       context.Context
	args      []string
	def       Definition
	handlers  any
	rtx       *Context   // pre-seeded registry; user Bind calls land here
	funnelFn  FunnelFunc // the one outcome funnel (all recorded channels); nil → defaultFunnel
	resolver  Resolver   // resolve phase override; nil → DefaultResolver
	lifecycle Lifecycle  // run-phase plan override; nil → DefaultLifecycle
	stdin     io.Reader
	stdout    io.Writer
	stderr    io.Writer
	exit      func(int) // terminal action for Execute; defaults to os.Exit
	// panicForward: when true (default), a recovered panic halts forward progress but lets
	// teardown still run; when false, a recovered panic hard-stops, skipping remaining teardown.
	panicForward bool
	// panicRecover: when true (default), a hook panic is recovered and routed to the funnel; when
	// false, hooks run unguarded so a panic propagates raw.
	panicRecover bool
	// signalMode resolves whether the SIGINT/SIGTERM trap is installed, INDEPENDENTLY of
	// whether rotini owns the context (signalAuto = trap iff no WithContext). signalSet is the
	// signals trapped when on; empty falls back to trapSignals.
	signalMode signalTrapMode
	signalSet  []os.Signal
}

// NewProgram wires a generated program's command tree (the rtg [Definition]) and
// its aggregate handler set (the rtg ProgramHandlers implementation) to the
// rotini runtime. handlers is any so the runtime need not import the generated
// framework package; dispatch resolves the per-command handlers from it at
// execution time, via the Handler names recorded in def.
func NewProgram(def Definition, handlers any) *Program {
	return &Program{
		args:         os.Args[1:],
		def:          def,
		handlers:     handlers,
		rtx:          newContext(),
		stdin:        os.Stdin,
		stdout:       os.Stdout,
		stderr:       os.Stderr,
		exit:         os.Exit,
		panicForward: true,
		panicRecover: true,
	}
}

// WithStdin overrides the program's standard-input stream (defaults to os.Stdin) — the
// source a handler reads from via [Context.Stdin], and the source the Binder decodes a
// stdin channel from. Supply a reader (e.g. strings.NewReader) to drive an end-to-end test
// without piping real os.Stdin, or to embed rotini reading from somewhere else. A nil
// reader is ignored. It returns the receiver to chain.
func (p *Program) WithStdin(r io.Reader) *Program {
	if r != nil {
		p.stdin = r
	}
	return p
}

// WithStdout overrides the program's standard-output stream (defaults to os.Stdout) —
// the destination for the runtime's own writes (help/completion output, usage). A nil
// writer is ignored. It returns the receiver to chain.
func (p *Program) WithStdout(w io.Writer) *Program {
	if w != nil {
		p.stdout = w
	}
	return p
}

// WithStderr overrides the program's standard-error stream (defaults to os.Stderr) — the
// destination for the runtime's own diagnostics (dispatch errors, the default funnel). A
// nil writer is ignored. It returns the receiver to chain.
func (p *Program) WithStderr(w io.Writer) *Program {
	if w != nil {
		p.stderr = w
	}
	return p
}

// WithExit overrides the terminal action [Program.Execute] takes with the resolved exit
// code — defaults to [os.Exit]. Supply a recording function to capture the code without
// terminating the process (a test), or a custom exit when embedding rotini in a larger
// program/REPL. If the supplied function returns, Execute returns to its caller. A nil
// function is ignored. It returns the receiver to chain.
func (p *Program) WithExit(fn func(int)) *Program {
	if fn != nil {
		p.exit = fn
	}
	return p
}

// WithPanicForward controls whether teardown runs when a hook panics. The default is true: a
// panic in a hook halts forward progress (no further setup/PreRun/Run) but every begun setup
// hook's teardown (PostRun/CascadingPostRun) still runs — cleanup on failure, mirroring how
// `defer`s run during a panic unwind. Pass false for a HARD STOP: remaining teardown is SKIPPED
// (as a hard [Context.Exit] would).
//
// Where the panic ultimately goes — the funnel ([Program.WithFunnel], the default) or raw to
// the caller — is the separate [Program.WithPanicRecover] knob; the two compose. Keep forward on
// when teardown must release resources / roll back regardless of a panic; turn it off when a
// panic means the program is too broken to clean up safely (e.g. a wiring fault). The exit code
// is never masked to 0. It returns the receiver to chain.
func (p *Program) WithPanicForward(enabled bool) *Program {
	p.panicForward = enabled
	return p
}

// WithPanicRecover controls where a hook panic ultimately goes. The default is true: every hook
// panic is recovered and routed to the funnel ([Program.WithFunnel]), so consumers of the built
// CLI never see a raw stack dump. Pass false to re-raise the panic RAW to the caller instead of
// funneling it — the original value crashes the process (exit 2, unfunneled), plain-Go behavior, for e.g.
// embedding rotini under your own top-level recover, a crash reporter, or debugging.
//
// It composes with [Program.WithPanicForward], which still decides teardown:
//   - recover=false, forward=true  → teardown runs, THEN the panic is re-raised (its stack roots
//     at the re-raise, not the original site).
//   - recover=false, forward=false → "panic now": the hook runs unguarded, so the panic
//     propagates immediately with its ORIGINAL stack, skipping teardown.
//
// Note: rotini can only recover panics in the hook goroutine — a panic in a goroutine a handler
// spawned crashes regardless. It returns the receiver to chain.
func (p *Program) WithPanicRecover(enabled bool) *Program {
	p.panicRecover = enabled
	return p
}

// WithArgs overrides the argument vector (defaults to os.Args[1:]).
func (p *Program) WithArgs(args []string) *Program {
	if args != nil {
		p.args = args
	}
	return p
}

// WithContext sets the base [context.Context] threaded to every lifecycle hook (and to
// the funnel and any remote sub-command exec), so a caller — a server, a test,
// a parent process — can cancel or time-bound the whole run. A nil context is ignored.
//
// Cancellation is cooperative: it cannot preempt a hook that ignores it (a handler
// observes it via its ctx.Done()), but once the context is canceled rotini starts no
// further setup hook (CascadingPreRun), PreRun, or Run — and teardown (PostRun/
// CascadingPostRun for every begun setup hook) still runs, in reverse. Attach the process
// exit code to the cancellation with [ExitCode] — e.g. cancel(rotini.ExitCode(3)) via a
// [context.WithCancelCause]/[context.WithTimeoutCause] function; without one, a canceled
// run stops cleanly and the exit code falls through to the normal resolution (0 unless a
// handler recorded an error). A handler can cancel the run by holding this context's cancel
// function — bind it (`Bind("cancel", cancel)`) and call it, e.g.
// `MustGet[context.CancelCauseFunc](rtx, "cancel")(rotini.ExitCode(3))` — or, to stop without
// canceling the context (leaving it live for teardown), use [Context.SignalExit]/[Context.Exit].
//
// By default, supplying a context also opts OUT of rotini's signal trap (the caller owns
// signal handling — e.g. via [signal.NotifyContext] on the context it passes, the
// recommended path for graceful user-owned shutdown, since the caller then holds the cancel
// that halts the run). This is the AUTO policy, not a hard coupling: [Program.WithSignals]
// re-enables the trap on top of a supplied context (rotini derives a cancelable child to
// drive it), and [Program.WithoutSignalHandling] suppresses the trap without a context. With
// no WithContext, rotini installs its default trap — see [Program.Execute].
func (p *Program) WithContext(ctx context.Context) *Program {
	if ctx != nil {
		p.ctx = ctx
	}
	return p
}

// WithoutSignalHandling suppresses rotini's default SIGINT/SIGTERM trap WITHOUT requiring
// the caller to surrender the context: rotini still owns a cancelable run context, but
// installs no signal.Notify, so the program's own signal handling (in main or a handler) is
// the only one. It is the seam for "I own signals" in the default (rotini-owned-context)
// mode — note Go's signal.Notify is ADDITIVE, so without this opt-out a caller's own handler
// would merely STACK with rotini's (both fire, racing to exit), not replace it.
//
// Caveat: in this mode rotini owns the context and exposes no cancel, so a signal handler set
// up here has no rotini-provided way to halt the run GRACEFULLY (it would os.Exit itself,
// skipping teardown). For graceful user-owned shutdown prefer [Program.WithContext] with
// [signal.NotifyContext], so the caller holds the cancel that halts the run. It returns the
// receiver to chain.
func (p *Program) WithoutSignalHandling() *Program {
	p.signalMode = signalOff
	return p
}

// WithSignals installs rotini's graceful trap for the given signals, INDEPENDENTLY of
// whether the caller supplied a context — it forces the trap on (the default set is
// os.Interrupt + syscall.SIGTERM; pass others, e.g. syscall.SIGHUP, to trap them too). When
// a [Program.WithContext] context is also supplied, rotini derives a cancelable CHILD of it
// to drive the trap — the caller's context, deadline, and values still flow through, and
// rotini never cancels the caller's own context (only its child). The action is fixed: the
// first signal cancels the run context for a graceful halt (teardown runs, exit 128+signum),
// a second forces exit. An empty signal list is ignored (use [Program.WithoutSignalHandling]
// to opt out). It returns the receiver to chain.
func (p *Program) WithSignals(sigs ...os.Signal) *Program {
	if len(sigs) > 0 {
		p.signalMode = signalOn
		p.signalSet = sigs
	}
	return p
}

// Bind registers a service on the program's registry under key, overwriting any
// prior binding, and returns the receiver so it chains with [Program.WithFunnel] and
// [program.WithArgs] before [program.Execute]. It is the dependency-injection
// seam: bind a real implementation in production or a double in tests, with the
// same handler code retrieving it via the typed [Get] / [MustGet]. Binding
// "parser" overrides the default [Parser].
func (p *Program) Bind(key string, value any) *Program {
	p.rtx.Bind(key, value)
	return p
}

// FunnelFunc is the program's single outcome funnel ([Program.WithFunnel]): the
// runtime calls it once, after the lifecycle (teardown included) settles, with every
// channel a run recorded — informational messages ([Context.RecordInfo]), successes
// ([Context.RecordSuccess]), non-fatal warnings ([Context.RecordWarning]), the
// end-user's errors ([Context.RecordError]), and the panics slice (recovered panics +
// rotini-detected faults: a wiring mismatch, a resolver fault, a [MustGet] on a missing
// service — never handler-recordable). Each slice is in recording order; all are
// PRIVATE (the funnel's parameters are the only way they surface — there is no drainable
// accessor on rtx). The funnel decides what to print and where, in what order, and the
// final exit code: it is the LAST authority, so [Context.Exit] inside it OVERRIDES any
// code the lifecycle set (see [Context.Exit]; [Context.SignalExit] is a no-op here).
type FunnelFunc func(ctx context.Context, rtx *Context, infos []string, successes []string, warnings []error, errors []error, panics []*PanicError)

// WithFunnel sets the program's outcome funnel — the single place a run's recorded
// channels (infos / successes / warnings / errors / panics) are reported. The runtime
// invokes it once per run, after the lifecycle settles, whenever ANY channel recorded
// something (a clean run with nothing recorded never invokes it). It replaces the four
// former per-channel funnels: one function receives everything at once, so a CLI controls
// cross-channel logic, print ordering, and the exit code in one place — see [FunnelFunc].
//
// With no funnel set, the default ([Program.defaultFunnel]) prints in the order
// info → warning → error → panic → success (infos/successes to stdout, the rest to
// stderr) and applies the exit floor: a recorded error or a panic exits non-zero unless a
// handler already set a deliberate code. A custom funnel owns the exit entirely (it may
// even mask a panic to 0 via [Context.Exit]). It returns the receiver so it chains with
// [Program.Bind].
func (p *Program) WithFunnel(fn FunnelFunc) *Program {
	p.funnelFn = fn
	return p
}

// PanicError is how a panic recovered from a lifecycle hook reaches the funnel
// ([Program.WithFunnel]) as a panics-slice element: Value is the value passed to panic, Stack is the
// goroutine stack captured at the recovery point (runtime/debug.Stack) — the
// information the recover would otherwise discard. Error renders Value alone, so
// default output stays one line; a funnel that wants the stack asks with errors.As.
type PanicError struct {
	Value any
	Stack []byte
}

func (e *PanicError) Error() string { return fmt.Sprintf("%v", e.Value) }

// Unwrap exposes a panicked error value so errors.Is/errors.As and [CategoryOf]
// see through the wrapping; it is nil for non-error panic values.
func (e *PanicError) Unwrap() error {
	if err, ok := e.Value.(error); ok {
		return err
	}
	return nil
}

// WiringError reports that the generated [Definition] and the handler set are
// out of sync — a resolved command names a handler method that does not exist,
// or whose return value does not implement [Handlers]. It is a build-
// time bug surfaced at run time (always [CategoryInternal]); the structured
// fields name the offending command and method so a funnel can report it
// precisely without matching the message:
//
//	var we *rotini.WiringError
//	if errors.As(err, &we) { log.Fatalf("wire %s → %s", we.Command, we.Handler) }
type WiringError struct {
	Command string // the command whose handler wiring is broken
	Handler string // the handler method name the Definition referenced
	Msg     string // the human-readable failure
}

func (e *WiringError) Error() string { return e.Msg }

// Unwrap reports [ErrInternal]: a wiring mismatch is always the author's bug,
// never the end-user's.
func (e *WiringError) Unwrap() error { return ErrInternal }

// WithResolver overrides the resolve phase — argv to invocation target (the
// command chain to dispatch, or a remote dispatch, plus the argv the parsers
// later see). Wrap [DefaultResolver] rather than re-deriving it: a resolver
// that rewrites tokens (an alias, a shorthand expansion) rewrites argv, hands
// it to the default, and returns the result — routing and parsing then agree.
// A resolver error is a resolution-phase fault, routed through the funnel
// (as a fault), and fails the run. The hidden __complete protocol intercept runs before resolution, and
// completion candidates walk the Definition — a resolver-only alias is
// dispatchable but not completable (declare real aliases in the spec for
// that). A nil resolver is ignored. It returns the receiver to chain.
func (p *Program) WithResolver(fn Resolver) *Program {
	if fn != nil {
		p.resolver = fn
	}
	return p
}

// WithLifecycle overrides the run phase's PLAN — which declared hooks run, in
// what pairing and order (see [Lifecycle] and the contract in [DefaultLifecycle]).
// The execution semantics around the plan (halt on SignalExit/Exit/panic/
// signal, balanced reverse unwind of begun steps, teardown-to-completion, the
// panic funnel, exit codes) are rotini's and stay fixed. Wrap
// [DefaultLifecycle] to adjust rather than re-derive. A nil lifecycle is
// ignored. It returns the receiver to chain.
func (p *Program) WithLifecycle(fn Lifecycle) *Program {
	if fn != nil {
		p.lifecycle = fn
	}
	return p
}

// Execute resolves the command, runs its lifecycle, and ends with the resulting status
// code via the program's exit action ([os.Exit] by default; override with
// [Program.WithExit] to capture the code or embed without terminating).
//
// By default (no [Program.WithContext]) Execute installs rotini's signal trap: the first
// os.Interrupt or syscall.SIGTERM cancels the run context AND halts the lifecycle like
// [Context.SignalExit] — forward progress stops and every begun teardown hook still runs —
// exiting 128+signum (130 for SIGINT, 143 for SIGTERM). A second signal forces exit
// immediately (code 130), skipping any remaining teardown, so a handler stuck ignoring the
// context can always be interrupted. The trap is independently controllable:
// [Program.WithoutSignalHandling] suppresses it (rotini still owns the context),
// [Program.WithSignals] forces it on with a custom signal set (even atop a supplied
// context), and [Program.WithContext] alone defers signal handling to the caller.
func (p *Program) Execute() error {
	code, err := p.run(p.args)
	p.exit(code)
	return err
}

// run is the testable core of Execute: it resolves the invoked command (no eager
// flag parsing — that is the handler's opt-in via [Parse]), execs a remote
// sub-command if one was selected, otherwise builds the per-invocation [Rtx] and
// dispatches the lifecycle. It returns the process exit code instead of calling
// os.Exit. The only retained protocol intercept is the hidden __complete entry
// the generated shell scripts invoke.
func (p *Program) run(argv []string) (int, error) {
	if len(argv) > 0 && argv[0] == completeCommand {
		p.rtx.Stdin, p.rtx.Stdout, p.rtx.Stderr = p.stdin, p.stdout, p.stderr
		for _, c := range complete(p.def, argv[1:], p.handlers, p.rtx) {
			fmt.Fprintln(p.stdout, c)
		}
		return 0, nil
	}

	// The effective run context, and whether rotini traps signals — two INDEPENDENT axes (see
	// [Program.WithSignals] / [Program.WithoutSignalHandling]). rotini's working context is
	// always a CHILD it can cancel when it must drive the trap: derived from the caller's
	// context when one was supplied, else from context.Background(). In pure pass-through mode
	// (a WithContext context, no trap) the caller's context is used as-is, so handlers see
	// exactly what was passed; rotini still halts on its cancellation by observing ctx.Err().
	// A canceled run context halts the lifecycle either way — see [Program.dispatch].
	ctx := p.ctx
	trap := ctx == nil // signalAuto: trap iff the caller supplied no context
	switch p.signalMode {
	case signalOff:
		trap = false
	case signalOn:
		trap = true
	}

	// Derive a cancelable child only when rotini needs to be the canceler (the trap) or when
	// it owns the context outright (no WithContext); otherwise the caller's context passes
	// through untouched.
	var cancel context.CancelCauseFunc
	switch {
	case ctx == nil:
		ctx, cancel = context.WithCancelCause(context.Background())
	case trap:
		ctx, cancel = context.WithCancelCause(ctx)
	}
	if cancel != nil {
		defer cancel(nil)
	}

	if trap {
		sigs := p.signalSet
		if len(sigs) == 0 {
			sigs = trapSignals
		}
		sigCh := make(chan os.Signal, 2)
		signal.Notify(sigCh, sigs...)
		defer signal.Stop(sigCh)

		done := make(chan struct{})
		defer close(done)
		go func() {
			select {
			case s := <-sigCh: // first signal → graceful: cancel ctx with the signal's exit code; dispatch then halts the lifecycle
				cancel(exitCodeError{code: signalExitCode(s)})
			case <-done:
				return
			}
			select {
			case <-sigCh: // second signal → force exit, skipping any remaining teardown
				p.exit(forceExitCode)
			case <-done:
			}
		}()
	}

	resolve := p.resolver
	if resolve == nil {
		resolve = DefaultResolver
	}
	rtx := p.rtx
	if rtx == nil {
		rtx = newContext()
	}
	rtx.Stdin = p.stdin
	rtx.Stdout = p.stdout
	rtx.Stderr = p.stderr

	res, err := resolve(p.def, argv)
	if err != nil {
		// A resolver fault is rotini's domain, not the end-user's → the funnel (as a fault).
		rtx.recordFault(asFault(internalUnlessTagged(fmt.Errorf("resolve: %w", err))))
		return p.settle(ctx, rtx)
	}
	if res.Remote != nil {
		return p.execRemote(ctx, rtx, res.Remote)
	}
	if len(res.Chain) == 0 {
		// An empty chain is a resolver contract violation → the funnel (as a fault).
		rtx.recordFault(asFault(InternalError(errors.New("resolver returned an empty chain — the root frame is always resolvable"))))
		return p.settle(ctx, rtx)
	}

	rtx.Args = argv
	if res.Args != nil {
		rtx.Args = res.Args
	}
	rtx.chain = res.Chain
	return p.dispatch(ctx, res.Chain, rtx)
}

// internalUnlessTagged tags err [CategoryInternal] unless its producer already
// categorized it — a custom resolver may legitimately raise a usage error (the
// user's token was the problem), and that classification must survive.
func internalUnlessTagged(err error) error {
	if CategoryOf(err) != CategoryNone {
		return err
	}
	return InternalError(err)
}

// asFault wraps a rotini-detected fault error (a wiring mismatch, a resolver
// fault) into a [*PanicError] so it rides the panics channel uniformly with
// recovered panics. Value holds the error (errors.As/Is and [CategoryOf] see
// through it); Stack is empty — this is a detected fault, not a real panic
// (detect-and-route, no stack unwind).
func asFault(err error) *PanicError { return &PanicError{Value: err} }

// settle is the single run tail: after the lifecycle (or an early framework
// fault) has populated the Context's outcome channels, it hands them ALL to the one
// funnel — the custom [Program.WithFunnel] or [Program.defaultFunnel] — and resolves
// the exit code. It is shared by the dispatch tail and the resolve/wiring/remote early
// returns, so every run path reports through the same funnel.
//
// Exit code: a handler's explicit rtx.SignalExit/rtx.Exit carries into the funnel (first
// non-zero, already in rtx.exitCode). The funnel is the FINAL authority — it runs in the
// funnel stage where rtx.Exit OVERRIDES that code (a custom funnel may even exit 0 on a
// panic). The exit floors live in defaultFunnel (a recorded error or a captured fault
// exits non-zero unless a deliberate code is already set), so a custom funnel that wants
// other behavior simply does not call into them. rotini holds no named exit-code
// constants; a CLI that wants other codes sets them in its funnel.
func (p *Program) settle(ctx context.Context, rtx *Context) (int, error) {
	// Snapshot the private channels once; the records surface only here, as the
	// slices the funnel receives — there is no public drainable accessor.
	infos := rtx.copyInfos()
	successes := rtx.copySuccesses()
	warnings := rtx.copyWarnings()
	errs := rtx.copyErrors()
	faults := rtx.copyFaults()

	// A clean run that recorded nothing never invokes the funnel.
	if len(infos)+len(successes)+len(warnings)+len(errs)+len(faults) > 0 {
		fn := p.funnelFn
		if fn == nil {
			fn = p.defaultFunnel
		}
		rtx.funnelStage = true // rtx.Exit now overrides; rtx.SignalExit is a no-op
		fn(ctx, rtx, infos, successes, warnings, errs, faults)
		rtx.funnelStage = false
	}
	return rtx.exitCode, joinOutcome(errs, faults)
}

// joinOutcome is the error a run returns to its caller (and tests): every
// recorded error AND every captured fault, so errors.Is/As reach them all. It
// is nil for a clean run.
func joinOutcome(errs []error, faults []*PanicError) error {
	if len(errs) == 0 && len(faults) == 0 {
		return nil
	}
	all := make([]error, 0, len(errs)+len(faults))
	all = append(all, errs...)
	for _, f := range faults {
		all = append(all, f)
	}
	return errors.Join(all...)
}

// defaultFunnel is the outcome funnel used when the program supplies none. It prints
// each channel in the order info → warning → error → panic → success — infos and
// successes to stdout, warnings/errors/faults to stderr (each rotini error type renders a
// single non-leaky line; a [*PanicError]'s Value is printed, never its Stack — that stays
// for an errors.As). Then it applies the exit floor: a recorded error or a captured fault
// exits non-zero (1) UNLESS a handler already set a deliberate code, which it never
// downgrades. A CLI that wants richer reporting, a different order, or a different code
// supplies its own [Program.WithFunnel].
func (p *Program) defaultFunnel(_ context.Context, rtx *Context, infos, successes []string, warnings, errs []error, faults []*PanicError) {
	for _, s := range infos {
		fmt.Fprintln(p.stdout, s)
	}
	for _, w := range warnings {
		fmt.Fprintf(p.stderr, "Warning: %s\n", w.Error())
	}
	for _, e := range errs {
		fmt.Fprintf(p.stderr, "Error: %s\n", e.Error())
	}
	for _, pe := range faults {
		fmt.Fprintf(p.stderr, "Fatal Error: %v\n", pe)
	}
	for _, s := range successes {
		fmt.Fprintln(p.stdout, s)
	}
	// Exit floor: an error or a fault is non-zero by default, but a deliberate handler
	// exit (a non-zero rtx.exitCode set during the lifecycle) is never downgraded.
	if rtx.exitCode == 0 && (len(errs) > 0 || len(faults) > 0) {
		rtx.exitCode = 1
	}
}

// dispatch resolves each command in the chain to its [Handlers] (by the
// recorded Handler method name, via reflection on the aggregate handlers),
// asks the lifecycle planner for the step plan (the default plan reproduces
// the contract table in lifecycle.go), and executes it as a balanced, LIFO
// setup/teardown:
//
//   - Forward: each step's Do, in plan order, halting the moment a hook calls
//     rtx.SignalExit/rtx.Exit or panics (or a trapped signal cancels ctx).
//   - Unwind: the Undo of every step whose Do BEGAN, in reverse, to
//     completion — a panic or rtx.SignalExit inside an Undo neither aborts the
//     rest nor displaces the first failure or exit code; a hard rtx.Exit skips
//     what remains, and so does a panic when [Program.WithPanicForward] is false.
//
// rtx.SignalExit is a clean stop that still runs teardown; rtx.Exit is a hard stop that
// skips it. A panic anywhere (e.g. the [MustGet] on a missing service) is recovered as a
// fault and routed once — after teardown — to the funnel, last. By default it does
// not abort the remaining teardown (cleanup still runs); [Program.WithPanicForward](false)
// makes a panic a hard stop that skips the rest of teardown.
//
// A canceled run context — by the caller of a WithContext context (directly or via a bound
// cancel a handler calls) or by the default signal trap — is converted into a lifecycle
// [Context.SignalExit] between forward hooks: forward progress stops, teardown still runs, and
// the exit code is the cancellation cause's ([ExitCode]) or 0. The conversion happens only on
// the dispatch goroutine, so rtx state stays single-writer; the canceler only cancels ctx.
func (p *Program) dispatch(ctx context.Context, chain []ResolvedCommand, rtx *Context) (int, error) {
	hv := reflect.ValueOf(p.handlers)
	handlers := make([]Handlers, len(chain))
	for i, f := range chain {
		// A wiring failure (generated Definition and handler set out of sync) is
		// rotini's "this should never have happened" — a detected fault routed to
		// the funnel (detect-and-route, no literal panic).
		m := hv.MethodByName(f.Handler)
		if !m.IsValid() {
			rtx.recordFault(asFault(&WiringError{
				Command: f.Name, Handler: f.Handler,
				Msg: fmt.Sprintf("no handler for command %q (missing method %q)", f.Name, f.Handler),
			}))
			return p.settle(ctx, rtx)
		}
		out := m.Call(nil)
		h, ok := out[0].Interface().(Handlers)
		if !ok || h == nil {
			rtx.recordFault(asFault(&WiringError{
				Command: f.Name, Handler: f.Handler,
				Msg: fmt.Sprintf("handler %q does not implement Handlers", f.Handler),
			}))
			return p.settle(ctx, rtx)
		}
		handlers[i] = h
	}

	// The plan: which declared hooks run, paired and ordered. The wiring above
	// happened first, so a custom lifecycle orders resolved handlers — it
	// cannot bypass the handler rules.
	plan := p.lifecycle
	if plan == nil {
		plan = DefaultLifecycle
	}
	steps := plan(chain, handlers)

	// run wraps every hook so a panic is RECOVERED and the lifecycle stays in control — teardown
	// can still run and the panic is dealt with once, last. Two independent knobs decide the rest:
	//   - [Program.WithPanicForward] (default true): does begun-step teardown run after a panic?
	//   - [Program.WithPanicRecover] (default true): is the panic funneled (true), or
	//     re-panicked raw to the caller after the lifecycle settles (false)?
	// The one combination rotini does NOT recover is recover=false AND forward=false — "panic now":
	// the hook runs unguarded so the panic propagates immediately with its original stack, skipping
	// teardown. panicked records that a panic stopped forward progress; panicValue holds the first
	// panic when it will be re-panicked (recover=false, forward=true) instead of funneled.
	panicked := false
	var panicValue any
	run := func(hook func(context.Context, *Context)) {
		if !p.panicRecover && !p.panicForward {
			hook(ctx, rtx) // panic now: unguarded, original stack, no teardown
			return
		}
		defer func() {
			if r := recover(); r != nil {
				panicked = true
				if p.panicRecover {
					rtx.recordFault(&PanicError{Value: r, Stack: debug.Stack()})
				} else if panicValue == nil {
					panicValue = r // re-panicked after teardown
				}
			}
		}()
		hook(ctx, rtx)
	}

	// halt reports whether forward progress should stop — after a hook called
	// rtx.SignalExit/rtx.Exit or panicked, OR after the run context was canceled (by the caller
	// of a WithContext context or the default signal trap). On cancellation it records the exit
	// code via rtx.SignalExit — the cancellation cause's code ([ExitCode]) or 0 — so the
	// cancellation becomes a clean lifecycle stop that still runs teardown.
	halt := func() bool {
		if !rtx.stopped && ctx.Err() != nil {
			rtx.SignalExit(canceledExitCode(ctx))
		}
		return rtx.stopped || panicked
	}

	// Forward — every step's Do in plan order, halting on rtx.SignalExit/rtx.Exit
	// (rtx.stopped), a panic, or a signal. began records how far the plan got, so
	// the unwind covers exactly the begun steps. The final halt() call records the
	// signal exit code when the last hook returned because the context was canceled.
	began := 0
	for _, s := range steps {
		began++
		run(s.Do)
		if halt() {
			break
		}
	}

	// Unwind, reverse — every begun step's Undo, to completion — unless a hard
	// [Context.Exit] asked to stop now (skipping any teardown still pending), or a panic
	// occurred and [Program.WithPanicForward] is false (a hard stop on panic). Both guards are
	// re-checked per step, so an Exit or panic from within a teardown hook stops the rest too.
	for i := began - 1; i >= 0 && !rtx.exitNow && (p.panicForward || !panicked); i-- {
		if steps[i].Undo != nil {
			run(steps[i].Undo)
		}
	}

	// Recovery off (recover=false, forward=true): the panic was caught only so teardown could
	// run; surface it raw now — after teardown — instead of funneling it.
	if panicked && !p.panicRecover {
		panic(panicValue)
	}

	// settle fires whatever outcome channels this run populated (warnings,
	// successes, recorded errors, captured faults), in order, once, after
	// teardown — and resolves the exit code.
	return p.settle(ctx, rtx)
}

// RemoteErrorKind classifies a remote-dispatch failure: the plugin binary could
// not be located, it exceeded its declared timeout, or it could not be spawned.
type RemoteErrorKind int

const (
	// RemoteBinaryNotFound: no binary was found next to the executable, in the
	// discovery path, or on PATH.
	RemoteBinaryNotFound RemoteErrorKind = iota
	// RemoteTimeout: the plugin ran past its declared timeout and was killed.
	RemoteTimeout
	// RemoteSpawnFailed: the binary was found but could not be started (a fork/
	// exec or pipe failure — NOT the plugin's own non-zero exit, which passes
	// through untouched).
	RemoteSpawnFailed
)

// String renders the kind as a short, stable label.
func (k RemoteErrorKind) String() string {
	switch k {
	case RemoteBinaryNotFound:
		return "binary-not-found"
	case RemoteTimeout:
		return "timeout"
	case RemoteSpawnFailed:
		return "spawn-failed"
	default:
		return "unknown"
	}
}

// RemoteError reports a rotini-authored failure carrying out a remote/plugin
// dispatch (NOT the plugin's own non-zero exit, which rotini passes through —
// the plugin already spoke for itself). It is the remote channel's typed,
// errors.As-able error, so a funnel can special-case a timeout or a missing
// plugin without matching the message:
//
//	var re *rotini.RemoteError
//	if errors.As(err, &re) && re.Kind == rotini.RemoteTimeout {
//	    fmt.Fprintf(os.Stderr, "%s timed out after %s\n", re.Name, re.Timeout)
//	}
//
// Category follows D4: a missing binary is the user's typo when DISCOVERED
// ([CategoryUsage]) and an install/wiring problem when DECLARED
// ([CategoryInternal]); a spawn failure is [CategoryInternal]; a timeout is
// deliberately [CategoryNone] — operational, neither party's fault — but still
// As-able here so a funnel that wants to treat it specially can. The underlying
// OS/exec Cause stays reachable via errors.As (nil for a synthesized
// not-found).
type RemoteError struct {
	Name    string          // the remote command name (or discovery token)
	Binary  string          // the plugin binary that was sought or spawned
	Kind    RemoteErrorKind // what went wrong
	Timeout time.Duration   // the elapsed deadline, for Kind == RemoteTimeout (else 0)
	Cause   error           // the underlying OS/exec error, reachable via errors.As (may be nil)
	Msg     string          // the human-readable failure

	cat Category // how CategoryOf classifies it (CategoryNone for a timeout)
}

func (e *RemoteError) Error() string { return e.Msg }

// Unwrap exposes the Cause (when present) and the category sentinel
// ([ErrUsage]/[ErrInternal]) so errors.Is/As reach both; a timeout adds no
// sentinel, so [CategoryOf] reports [CategoryNone].
func (e *RemoteError) Unwrap() []error {
	var out []error
	if e.Cause != nil {
		out = append(out, e.Cause)
	}
	switch e.cat {
	case CategoryUsage:
		out = append(out, ErrUsage)
	case CategoryInternal:
		out = append(out, ErrInternal)
	}
	return out
}

// RemoteDispatch is a resolved remote/co-located sub-command invocation: the
// plugin binary Def.Binary run with Args (everything after the command name).
// Dir is an extra directory to search first (from remote_discovery.path),
// empty for a declared remote command. The default resolver produces one for
// declared remote_commands and discovered plugins; a custom [Resolver] may
// return its own in [Resolution.Remote].
type RemoteDispatch struct {
	Def  RemoteDef
	Args []string
	Dir  string
	// Discovered marks a plugin-discovery dispatch (an unmatched token mapped
	// to <prefix><token>) as opposed to a declared remote command. It decides
	// the error CATEGORY when the binary cannot be resolved: a discovered
	// token is the user's typo (CategoryUsage — pair it with a Suggestor in a
	// custom funnel), while a declared remote's missing binary is an
	// install/wiring problem (CategoryInternal).
	Discovered bool
}

// execRemote locates and runs the co-located plugin binary, passing stdio
// through, honoring the run context (so a signal/cancellation kills the subprocess)
// and any timeout, and returning the plugin's exit code. rotini-authored
// diagnostics (binary not found, timeout, spawn failure) are recorded as errors
// and routed through the funnel (a plugin's environment is the
// end-user's, not a rotini fault — see [Program.remoteFailure]); the plugin's
// own non-zero exit passes through untouched (the plugin already spoke for itself).
func (p *Program) execRemote(ctx context.Context, rtx *Context, r *RemoteDispatch) (int, error) {
	path, err := resolveRemoteBinary(r.Def.Binary, r.Dir)
	if err != nil {
		// A DISCOVERED token's missing binary is the user's typo (Usage); a
		// DECLARED remote's is an install/wiring problem (Internal).
		cat := CategoryInternal
		if r.Discovered {
			cat = CategoryUsage
		}
		return p.remoteFailure(ctx, rtx, &RemoteError{
			Name: r.Def.Name, Binary: r.Def.Binary, Kind: RemoteBinaryNotFound,
			Cause: err, Msg: err.Error(), cat: cat,
		})
	}

	if r.Def.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, r.Def.Timeout)
		defer cancel()
	}

	cmd := exec.CommandContext(ctx, path, r.Args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = p.stdout
	cmd.Stderr = p.stderr

	switch err := cmd.Run(); {
	case err == nil:
		return 0, nil
	case errors.Is(ctx.Err(), context.DeadlineExceeded):
		// Deliberately CategoryNone (cat unset): a timeout is operational —
		// neither the user's command nor the author's wiring is "wrong" — but
		// still As-able as a *RemoteError so a funnel can special-case it.
		return p.remoteFailure(ctx, rtx, &RemoteError{
			Name: r.Def.Name, Binary: r.Def.Binary, Kind: RemoteTimeout, Timeout: r.Def.Timeout,
			Msg: fmt.Sprintf("%s: timed out after %s", r.Def.Name, r.Def.Timeout),
		})
	default:
		if ee, ok := errors.AsType[*exec.ExitError](err); ok {
			return ee.ExitCode(), err
		}
		return p.remoteFailure(ctx, rtx, &RemoteError{
			Name: r.Def.Name, Binary: r.Def.Binary, Kind: RemoteSpawnFailed,
			Cause: err, Msg: fmt.Sprintf("%s: %v", r.Def.Name, err), cat: CategoryInternal,
		})
	}
}

// remoteFailure records a rotini-authored remote dispatch error and reports it
// through the funnel. A missing / timed-out / unspawnable plugin is
// ENVIRONMENTAL — the engineer who built this binary cannot control whether the
// consumer installed the plugin being dispatched to — so it is the end-user's
// recorded error, not rotini's "should never happen" fault (a panic).
func (p *Program) remoteFailure(ctx context.Context, rtx *Context, re *RemoteError) (int, error) {
	rtx.RecordError(re)
	return p.settle(ctx, rtx)
}

// resolveRemoteBinary finds the plugin binary: first adjacent to the running
// executable (the git/kubectl convention), then in dir (the remote_discovery.path,
// when set), then anywhere on PATH.
func resolveRemoteBinary(name, dir string) (string, error) {
	if exe, err := os.Executable(); err == nil {
		if p, ok := executableAt(filepath.Dir(exe), name); ok {
			return p, nil
		}
	}
	if dir != "" {
		if p, ok := executableAt(dir, name); ok {
			return p, nil
		}
	}
	if p, err := exec.LookPath(name); err == nil {
		return p, nil
	}
	return "", fmt.Errorf("%q not found (looked next to the binary, in the discovery path, and on PATH)", name)
}

// executableAt reports the path dir/name when it exists as a non-directory file.
func executableAt(dir, name string) (string, bool) {
	p := filepath.Join(dir, name)
	if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
		return p, true
	}
	return "", false
}

const KeyStyler = "styler"

const reset = "\x1b[0m"

type Styler struct {
	enabled bool
	profile Profile
	styles  map[string]*Style
}

func NewStyler() *Styler {
	return &Styler{
		enabled: true,
		profile: ProfileTrueColor,
		styles:  map[string]*Style{},
	}
}

func (s *Styler) SetEnabled(enabled bool) *Styler {
	s.enabled = enabled
	return s
}

func (s *Styler) SetProfile(profile Profile) *Styler {
	s.profile = profile
	return s
}

func (s *Styler) Define(key string) *Style {
	style := NewStyle()
	s.Set(key, style)
	return style
}

func (s *Styler) Get(key string) (*Style, bool) {
	style, ok := s.styles[key]
	return style, ok
}

func (s *Styler) Set(key string, style *Style) *Styler {
	s.styles[key] = style
	return s
}

func (s *Styler) Delete(key string) *Styler {
	delete(s.styles, key)
	return s
}

func (s *Styler) Render(key, text string) string {
	if !s.enabled {
		return Strip(text)
	}
	style, ok := s.styles[key]
	if !ok {
		return text
	}
	return style.renderAt(s.profile, text)
}

func (s *Styler) Renderf(key, format string, args ...any) string {
	return s.Render(key, fmt.Sprintf(format, args...))
}

func (s *Styler) Fprint(w io.Writer, key string, a ...any) {
	_, _ = fmt.Fprint(w, s.Render(key, fmt.Sprint(a...)))
}

func (s *Styler) Fprintln(w io.Writer, key string, a ...any) {
	_, _ = fmt.Fprintln(w, s.Render(key, fmt.Sprint(a...)))
}

func (s *Styler) Fprintf(w io.Writer, key, format string, a ...any) {
	_, _ = fmt.Fprint(w, s.Renderf(key, format, a...))
}

type Style struct {
	enabled bool
	profile Profile
	attrs   []string
	fg      color
	bg      color
}

func NewStyle() *Style {
	return &Style{enabled: true, profile: ProfileTrueColor}
}

func (s *Style) SetEnabled(enabled bool) *Style {
	s.enabled = enabled
	return s
}

func (s *Style) SetProfile(profile Profile) *Style {
	s.profile = profile
	return s
}

func (s *Style) Clone() *Style {
	clone := *s
	clone.attrs = slices.Clone(s.attrs)
	return &clone
}

func (s *Style) Bold() *Style {
	return s.addAttr("1")
}

func (s *Style) Faint() *Style {
	return s.addAttr("2")
}

func (s *Style) Italic() *Style {
	return s.addAttr("3")
}

func (s *Style) Underline() *Style {
	return s.addAttr("4")
}

func (s *Style) DoubleUnderline() *Style {
	return s.addAttr("21")
}

func (s *Style) Blink() *Style {
	return s.addAttr("5")
}

func (s *Style) RapidBlink() *Style {
	return s.addAttr("6")
}

func (s *Style) Reverse() *Style {
	return s.addAttr("7")
}

func (s *Style) Conceal() *Style {
	return s.addAttr("8")
}

func (s *Style) Strikethrough() *Style {
	return s.addAttr("9")
}

func (s *Style) Overline() *Style {
	return s.addAttr("53")
}

func (s *Style) ForegroundANSI(c ANSIColor) *Style {
	s.fg = colorANSI(c)
	return s
}

func (s *Style) BackgroundANSI(c ANSIColor) *Style {
	s.bg = colorANSI(c)
	return s
}

func (s *Style) ForegroundRGB(red, green, blue uint8) *Style {
	s.fg = colorRGB{red, green, blue}
	return s
}

func (s *Style) BackgroundRGB(red, green, blue uint8) *Style {
	s.bg = colorRGB{red, green, blue}
	return s
}

func (s *Style) Foreground256(code uint8) *Style {
	s.fg = color256(code)
	return s
}

func (s *Style) Background256(code uint8) *Style {
	s.bg = color256(code)
	return s
}

func (s *Style) ForegroundHex(hex string) *Style {
	if red, green, blue, ok := parseHex(hex); ok {
		s.fg = colorRGB{red, green, blue}
	}
	return s
}

func (s *Style) BackgroundHex(hex string) *Style {
	if red, green, blue, ok := parseHex(hex); ok {
		s.bg = colorRGB{red, green, blue}
	}
	return s
}

func (s *Style) Raw(sgr string) *Style {
	if sgr != "" {
		s.attrs = append(s.attrs, sgr)
	}
	return s
}

func (s *Style) Merge(other *Style) *Style {
	if other == nil {
		return s
	}
	s.attrs = append(s.attrs, other.attrs...)
	if other.fg != nil {
		s.fg = other.fg
	}
	if other.bg != nil {
		s.bg = other.bg
	}
	return s
}

func (s *Style) addAttr(parameter string) *Style {
	s.attrs = append(s.attrs, parameter)
	return s
}

func (s *Style) sgrParams(profile Profile) string {
	params := make([]string, 0, len(s.attrs)+2)
	params = append(params, s.attrs...)
	if s.fg != nil {
		if p := s.fg.sgr(profile, false); p != "" {
			params = append(params, p)
		}
	}
	if s.bg != nil {
		if p := s.bg.sgr(profile, true); p != "" {
			params = append(params, p)
		}
	}
	return strings.Join(params, ";")
}

func (s *Style) renderAt(profile Profile, text string) string {
	if !s.enabled {
		return text
	}
	params := s.sgrParams(profile)
	if params == "" {
		return text
	}
	open := "\x1b[" + params + "m"
	if strings.Contains(text, reset) {
		text = strings.ReplaceAll(text, reset, reset+open)
	}
	return open + text + reset
}

func (s *Style) Sprint(text string) string {
	return s.renderAt(s.profile, text)
}

func (s *Style) Sprintf(format string, args ...any) string {
	return s.Sprint(fmt.Sprintf(format, args...))
}

func (s *Style) Fprint(w io.Writer, a ...any) {
	_, _ = fmt.Fprint(w, s.Sprint(fmt.Sprint(a...)))
}

func (s *Style) Fprintln(w io.Writer, a ...any) {
	_, _ = fmt.Fprintln(w, s.Sprint(fmt.Sprint(a...)))
}

func (s *Style) Fprintf(w io.Writer, format string, a ...any) {
	_, _ = fmt.Fprint(w, s.Sprintf(format, a...))
}

// KeySuggestor is the conventional key under which a [Suggestor] is registered in
// a service registry — used, for example, by rotini, whose generated entrypoint
// binds the Suggestor under this key and whose handlers retrieve it by it.
const KeySuggestor = "suggestor"

// defaultMinScore is the cutoff a [Suggestor] keeps candidates at or above —
// "comfortably similar" by the configured algorithm, strict enough to avoid
// suggesting merely-adjacent words.
const defaultMinScore = 0.6

// Suggestor turns a possibly-mistyped token and a list of candidate strings into
// ranked "did you mean" suggestions. It is a pure ranking function — it discovers
// nothing, prints nothing, and holds no state beyond its configuration. The
// candidates come from whatever vocabulary the caller has: command names, enum
// members, map keys, or any []string.
//
// Configure it fluently; it ranks by a pluggable algorithm normalized to a
// similarity score (see [SuggestAlgorithm]):
//
//	s := rotini.NewSuggestor().
//		WithAlgorithm(rotini.SuggestAlgorithmJaroWinkler).
//		WithMinScore(0.7).
//		WithMaxResults(5).
//		WithCaseFold()
//	hits := s.Suggest("isntall", []string{"install", "uninstall", "list"}) // [install]
//
// As a rotini opt-in service it is bound under [KeySuggestor] and consulted by a
// handler after a parse failure — rotini itself suggests nothing; a
// rotini.ParseError carries the offending Token and the valid Candidates:
//
//	suggestor := rotini.MustGet[*rotini.Suggestor](rtx, rotini.KeySuggestor)
//	if best, ok := suggestor.Closest(parseErr.Token, parseErr.Candidates); ok {
//		fmt.Fprintf(rtx.Stderr, "Did you mean %q?\n", best)
//	}
//
// A configured Suggestor is safe for concurrent use: [Suggestor.Suggest],
// [Suggestor.Matches], [Suggestor.Closest], and [Suggestor.Score] do not mutate
// it. Finish configuring (the With* methods) before sharing it across goroutines.
type Suggestor struct {
	algorithm  SuggestAlgorithm
	minScore   float64
	maxResults int
	caseFold   bool
	normalizer func(string) string
}

// Match is a scored suggestion returned by [Suggestor.Matches]: the original
// candidate Value (exactly as passed in) and its similarity Score in [0,1]
// (1 = identical).
type Match struct {
	Value string
	Score float64
}

// NewSuggestor returns a [Suggestor] ready to bind under a registry key
// (conventionally [KeySuggestor]), ranking by [SuggestAlgorithmLevenshtein] with a
// minimum score of 0.6 and at most 3 results. Tune any of it fluently:
// NewSuggestor().WithAlgorithm(…).WithMinScore(…).WithMaxResults(…).WithCaseFold().
func NewSuggestor() *Suggestor {
	return &Suggestor{
		algorithm:  SuggestAlgorithmLevenshtein,
		minScore:   defaultMinScore,
		maxResults: 3,
	}
}

// WithAlgorithm selects the ranking algorithm (see [SuggestAlgorithm]) and returns
// the receiver to chain. An unrecognized algorithm is ignored. Default
// [SuggestAlgorithmLevenshtein].
func (s *Suggestor) WithAlgorithm(algorithm SuggestAlgorithm) *Suggestor {
	if algorithm.Valid() {
		s.algorithm = algorithm
	}
	return s
}

// WithMinScore sets the smallest similarity score (in [0,1], 1 = identical) a
// candidate may have and still be suggested, and returns the receiver to chain.
// Default 0.6. A score outside [0,1] is ignored.
func (s *Suggestor) WithMinScore(score float64) *Suggestor {
	if score >= 0 && score <= 1 {
		s.minScore = score
	}
	return s
}

// WithMaxResults caps how many suggestions [Suggestor.Suggest] / [Suggestor.Matches]
// return, and returns the receiver to chain. Default 3. A non-positive n is ignored.
func (s *Suggestor) WithMaxResults(n int) *Suggestor {
	if n > 0 {
		s.maxResults = n
	}
	return s
}

// WithCaseFold makes matching case-insensitive (input and candidates are lowered
// before scoring), and returns the receiver to chain. Off by default.
func (s *Suggestor) WithCaseFold() *Suggestor {
	s.caseFold = true
	return s
}

// WithNormalizer sets a preprocessing function applied to both the input and each
// candidate before scoring (e.g. trim whitespace, strip accents), and returns the
// receiver to chain. It runs before case-folding. The original candidate strings
// are still what [Suggestor.Suggest] / [Suggestor.Matches] return. A nil function
// clears it.
func (s *Suggestor) WithNormalizer(normalizer func(string) string) *Suggestor {
	s.normalizer = normalizer
	return s
}

// normalize applies the configured normalizer (if any) then case-folding (if on).
func (s *Suggestor) normalize(text string) string {
	if s.normalizer != nil {
		text = s.normalizer(text)
	}
	if s.caseFold {
		text = strings.ToLower(text)
	}
	return text
}

// Score returns the configured algorithm's similarity of a and b in [0,1] (1 =
// identical), after applying the Suggestor's normalization. It scores a single
// pair; [Suggestor.Suggest] / [Suggestor.Matches] rank a candidate set. A nil
// receiver returns 0.
func (s *Suggestor) Score(a, b string) float64 {
	if s == nil {
		return 0
	}
	return similarity(s.normalize(a), s.normalize(b), s.algorithm)
}

// Matches ranks candidates by similarity to input, nearest first, keeping those
// scoring at least the configured minimum (default 0.6) and at most the configured
// number of results. Each [Match] carries the ORIGINAL candidate string and its
// score. Score ties prefer the candidate sharing the longer common prefix with
// input, then break lexicographically, so the result is deterministic. An empty
// input yields no matches; empty candidates are skipped and duplicates (after
// normalization) collapse to the first occurrence; a nil receiver yields nil.
// Unlike [Suggestor.Suggest], Matches DOES include an exact match (score 1).
func (s *Suggestor) Matches(input string, candidates []string) []Match {
	if s == nil {
		return nil
	}
	normalizedInput := s.normalize(input)
	if normalizedInput == "" {
		return nil
	}
	type scoredMatch struct {
		value     string
		score     float64
		prefixLen int
	}
	hits := make([]scoredMatch, 0, len(candidates))
	seen := make(map[string]bool, len(candidates))
	for _, candidate := range candidates {
		normalizedCandidate := s.normalize(candidate)
		if normalizedCandidate == "" || seen[normalizedCandidate] {
			continue
		}
		seen[normalizedCandidate] = true
		score := similarity(normalizedInput, normalizedCandidate, s.algorithm)
		if score >= s.minScore {
			hits = append(hits, scoredMatch{
				value:     candidate,
				score:     score,
				prefixLen: commonPrefixLength(normalizedInput, normalizedCandidate),
			})
		}
	}
	sort.Slice(hits, func(i, j int) bool {
		if hits[i].score != hits[j].score {
			return hits[i].score > hits[j].score
		}
		if hits[i].prefixLen != hits[j].prefixLen {
			return hits[i].prefixLen > hits[j].prefixLen
		}
		return hits[i].value < hits[j].value
	})
	if s.maxResults > 0 && len(hits) > s.maxResults {
		hits = hits[:s.maxResults]
	}
	result := make([]Match, len(hits))
	for i, hit := range hits {
		result[i] = Match{Value: hit.value, Score: hit.score}
	}
	return result
}

// Suggest is the "did you mean" convenience over [Suggestor.Matches]: it returns
// just the candidate strings, nearest first. But when input EXACTLY matches a
// candidate (it wasn't mistyped) it returns nil — there is nothing to suggest. A
// nil receiver or empty input also yields nil.
func (s *Suggestor) Suggest(input string, candidates []string) []string {
	if s == nil {
		return nil
	}
	matches := s.Matches(input, candidates)
	// A (normalized) exact match scores exactly 1 and sorts first: the input was
	// typed correctly, so there is nothing to suggest.
	if len(matches) == 0 || matches[0].Score == 1 {
		return nil
	}
	result := make([]string, len(matches))
	for i, match := range matches {
		result[i] = match.Value
	}
	return result
}

// Closest returns the single best suggestion for input and whether one was found
// — the ergonomic "did you mean X?" form of [Suggestor.Suggest]. Like Suggest, it
// reports ok=false when input exactly matches a candidate or nothing clears the
// minimum score.
func (s *Suggestor) Closest(input string, candidates []string) (suggestion string, ok bool) {
	if hits := s.Suggest(input, candidates); len(hits) > 0 {
		return hits[0], true
	}
	return "", false
}

// commonPrefixLength is the length (in runes) of the longest common prefix of a and b.
func commonPrefixLength(a, b string) int {
	aRunes, bRunes := []rune(a), []rune(b)
	length := 0
	for length < len(aRunes) && length < len(bRunes) && aRunes[length] == bRunes[length] {
		length++
	}
	return length
}

// --- String metrics ---
//
// A roster of rune-based nearness algorithms, each normalized to a [0,1]
// similarity score (1 = identical) that a [Suggestor] ranks by.

// SuggestAlgorithm selects the string-distance algorithm a [Suggestor] ranks by —
// a small string enum so it reads clearly in code and config. The package defines
// the set; it is not user-extensible.
type SuggestAlgorithm string

const (
	// SuggestAlgorithmLevenshtein — Levenshtein (Wagner–Fischer) edit distance:
	// insertions, deletions, substitutions, each cost one. The default.
	SuggestAlgorithmLevenshtein SuggestAlgorithm = "levenshtein"
	// SuggestAlgorithmDamerauLevenshtein — true (unrestricted) Damerau–Levenshtein:
	// Levenshtein plus transpositions of adjacent runes, allowing a substring to
	// be edited more than once.
	SuggestAlgorithmDamerauLevenshtein SuggestAlgorithm = "damerau-levenshtein"
	// SuggestAlgorithmOptimalStringAlignment — restricted Damerau–Levenshtein:
	// adds adjacent transpositions, but no substring is edited more than once.
	SuggestAlgorithmOptimalStringAlignment SuggestAlgorithm = "optimal-string-alignment"
	// SuggestAlgorithmHamming — positional substitutions; defined only for
	// equal-length strings (unequal lengths score 0).
	SuggestAlgorithmHamming SuggestAlgorithm = "hamming"
	// SuggestAlgorithmLongestCommonSubsequence — longest common subsequence; the
	// score is 2·LCS/(len a + len b).
	SuggestAlgorithmLongestCommonSubsequence SuggestAlgorithm = "longest-common-subsequence"
	// SuggestAlgorithmJaro — Jaro similarity, weighting matching runes and
	// transpositions; good for short strings.
	SuggestAlgorithmJaro SuggestAlgorithm = "jaro"
	// SuggestAlgorithmJaroWinkler — Jaro plus a shared-prefix bonus; the classic
	// "did you mean" metric for short, prefix-similar typos.
	SuggestAlgorithmJaroWinkler SuggestAlgorithm = "jaro-winkler"
	// SuggestAlgorithmSorensenDice — Sørensen–Dice coefficient over rune bigrams.
	SuggestAlgorithmSorensenDice SuggestAlgorithm = "sorensen-dice"
	// SuggestAlgorithmJaccard — Jaccard index over the set of rune bigrams.
	SuggestAlgorithmJaccard SuggestAlgorithm = "jaccard"
)

// Algorithms returns every supported [SuggestAlgorithm] in a stable order — for
// enumerating the choices (config validation, a flag's enum, a UI list).
func Algorithms() []SuggestAlgorithm {
	return []SuggestAlgorithm{
		SuggestAlgorithmLevenshtein,
		SuggestAlgorithmDamerauLevenshtein,
		SuggestAlgorithmOptimalStringAlignment,
		SuggestAlgorithmHamming,
		SuggestAlgorithmLongestCommonSubsequence,
		SuggestAlgorithmJaro,
		SuggestAlgorithmJaroWinkler,
		SuggestAlgorithmSorensenDice,
		SuggestAlgorithmJaccard,
	}
}

// Valid reports whether a is a recognized [SuggestAlgorithm].
func (a SuggestAlgorithm) Valid() bool {
	switch a {
	case SuggestAlgorithmLevenshtein, SuggestAlgorithmDamerauLevenshtein,
		SuggestAlgorithmOptimalStringAlignment, SuggestAlgorithmHamming,
		SuggestAlgorithmLongestCommonSubsequence, SuggestAlgorithmJaro,
		SuggestAlgorithmJaroWinkler, SuggestAlgorithmSorensenDice, SuggestAlgorithmJaccard:
		return true
	default:
		return false
	}
}

// similarity normalizes algorithm's metric for a and b to a score in [0,1], where
// 1 means identical and 0 means maximally dissimilar — so edit-distance and
// similarity algorithms compare on one scale. An unrecognized algorithm falls back
// to Levenshtein. It does no case-folding or normalization; a [Suggestor] applies
// those before calling it.
func similarity(a, b string, algorithm SuggestAlgorithm) float64 {
	switch algorithm {
	case SuggestAlgorithmDamerauLevenshtein:
		return editSimilarity(damerauLevenshtein(a, b), a, b)
	case SuggestAlgorithmOptimalStringAlignment:
		return editSimilarity(optimalStringAlignment(a, b), a, b)
	case SuggestAlgorithmHamming:
		distance, ok := hamming(a, b)
		if !ok {
			return 0
		}
		return editSimilarityLength(distance, runeLength(a))
	case SuggestAlgorithmLongestCommonSubsequence:
		lenA, lenB := runeLength(a), runeLength(b)
		if lenA+lenB == 0 {
			return 1
		}
		return 2 * float64(longestCommonSubsequence(a, b)) / float64(lenA+lenB)
	case SuggestAlgorithmJaro:
		return jaro(a, b)
	case SuggestAlgorithmJaroWinkler:
		return jaroWinkler(a, b)
	case SuggestAlgorithmSorensenDice:
		return sorensenDice(a, b)
	case SuggestAlgorithmJaccard:
		return jaccard(a, b)
	default: // SuggestAlgorithmLevenshtein and any unrecognized algorithm
		return editSimilarity(levenshtein(a, b), a, b)
	}
}

// editSimilarity maps an edit distance to a [0,1] similarity, normalizing by the
// longer of the two rune lengths.
func editSimilarity(distance int, a, b string) float64 {
	return editSimilarityLength(distance, max(runeLength(a), runeLength(b)))
}

func editSimilarityLength(distance, length int) float64 {
	if length == 0 {
		return 1
	}
	return 1 - float64(distance)/float64(length)
}

func runeLength(s string) int { return len([]rune(s)) }

// levenshtein returns the Levenshtein (Wagner–Fischer) edit distance between a
// and b: the minimum number of single-rune insertions, deletions, and
// substitutions to turn one into the other.
func levenshtein(a, b string) int {
	aRunes, bRunes := []rune(a), []rune(b)
	if len(aRunes) == 0 {
		return len(bRunes)
	}
	if len(bRunes) == 0 {
		return len(aRunes)
	}
	previousRow := make([]int, len(bRunes)+1)
	for j := range previousRow {
		previousRow[j] = j
	}
	for i := 1; i <= len(aRunes); i++ {
		currentRow := make([]int, len(bRunes)+1)
		currentRow[0] = i
		for j := 1; j <= len(bRunes); j++ {
			cost := 1
			if aRunes[i-1] == bRunes[j-1] {
				cost = 0
			}
			currentRow[j] = min(previousRow[j]+1, currentRow[j-1]+1, previousRow[j-1]+cost)
		}
		previousRow = currentRow
	}
	return previousRow[len(bRunes)]
}

// optimalStringAlignment returns the Optimal String Alignment distance (restricted
// Damerau–Levenshtein): Levenshtein plus transposition of two adjacent runes, with
// the restriction that no substring is edited more than once.
func optimalStringAlignment(a, b string) int {
	aRunes, bRunes := []rune(a), []rune(b)
	lenA, lenB := len(aRunes), len(bRunes)
	if lenA == 0 {
		return lenB
	}
	if lenB == 0 {
		return lenA
	}
	matrix := make([][]int, lenA+1)
	for i := range lenA + 1 {
		matrix[i] = make([]int, lenB+1)
		matrix[i][0] = i
	}
	for j := range lenB + 1 {
		matrix[0][j] = j
	}
	for i := 1; i <= lenA; i++ {
		for j := 1; j <= lenB; j++ {
			cost := 1
			if aRunes[i-1] == bRunes[j-1] {
				cost = 0
			}
			matrix[i][j] = min(matrix[i-1][j]+1, matrix[i][j-1]+1, matrix[i-1][j-1]+cost)
			if i > 1 && j > 1 && aRunes[i-1] == bRunes[j-2] && aRunes[i-2] == bRunes[j-1] {
				matrix[i][j] = min(matrix[i][j], matrix[i-2][j-2]+1)
			}
		}
	}
	return matrix[lenA][lenB]
}

// damerauLevenshtein returns the true (unrestricted) Damerau–Levenshtein distance:
// insertions, deletions, substitutions, and transpositions of adjacent runes,
// allowing a substring to be edited more than once (so it can beat
// optimal string alignment, e.g. "ca"→"abc" is 2, not 3).
func damerauLevenshtein(a, b string) int {
	aRunes, bRunes := []rune(a), []rune(b)
	lenA, lenB := len(aRunes), len(bRunes)
	if lenA == 0 {
		return lenB
	}
	if lenB == 0 {
		return lenA
	}
	maxDist := lenA + lenB
	matrix := make([][]int, lenA+2)
	for i := range matrix {
		matrix[i] = make([]int, lenB+2)
	}
	matrix[0][0] = maxDist
	for i := range lenA + 1 {
		matrix[i+1][0] = maxDist
		matrix[i+1][1] = i
	}
	for j := range lenB + 1 {
		matrix[0][j+1] = maxDist
		matrix[1][j+1] = j
	}
	lastRow := map[rune]int{} // last row (1-indexed) at which each rune appeared in a
	for i := 1; i <= lenA; i++ {
		lastMatchCol := 0
		for j := 1; j <= lenB; j++ {
			matchRow := lastRow[bRunes[j-1]]
			matchCol := lastMatchCol
			cost := 1
			if aRunes[i-1] == bRunes[j-1] {
				cost = 0
				lastMatchCol = j
			}
			matrix[i+1][j+1] = min(
				matrix[i][j]+cost, // substitution / match
				matrix[i+1][j]+1,  // insertion
				matrix[i][j+1]+1,  // deletion
				matrix[matchRow][matchCol]+(i-matchRow-1)+1+(j-matchCol-1), // transposition
			)
		}
		lastRow[aRunes[i-1]] = i
	}
	return matrix[lenA+1][lenB+1]
}

// hamming returns the Hamming distance — the number of positions at which a and b
// differ — and ok=false when the strings differ in rune length (Hamming is defined
// only for equal-length strings).
func hamming(a, b string) (distance int, ok bool) {
	aRunes, bRunes := []rune(a), []rune(b)
	if len(aRunes) != len(bRunes) {
		return 0, false
	}
	for i := range aRunes {
		if aRunes[i] != bRunes[i] {
			distance++
		}
	}
	return distance, true
}

// longestCommonSubsequence returns the length of the longest common subsequence of
// a and b (runes in order, not necessarily contiguous).
func longestCommonSubsequence(a, b string) int {
	aRunes, bRunes := []rune(a), []rune(b)
	lenA, lenB := len(aRunes), len(bRunes)
	if lenA == 0 || lenB == 0 {
		return 0
	}
	previousRow := make([]int, lenB+1)
	for i := 1; i <= lenA; i++ {
		currentRow := make([]int, lenB+1)
		for j := 1; j <= lenB; j++ {
			if aRunes[i-1] == bRunes[j-1] {
				currentRow[j] = previousRow[j-1] + 1
			} else {
				currentRow[j] = max(previousRow[j], currentRow[j-1])
			}
		}
		previousRow = currentRow
	}
	return previousRow[lenB]
}

// jaro returns the Jaro similarity of a and b in [0,1] (1 = identical).
func jaro(a, b string) float64 {
	aRunes, bRunes := []rune(a), []rune(b)
	lenA, lenB := len(aRunes), len(bRunes)
	if lenA == 0 && lenB == 0 {
		return 1
	}
	if lenA == 0 || lenB == 0 {
		return 0
	}
	matchDistance := max(0, max(lenA, lenB)/2-1)
	aMatched := make([]bool, lenA)
	bMatched := make([]bool, lenB)
	matches := 0
	for i := range lenA {
		start := max(0, i-matchDistance)
		end := min(lenB, i+matchDistance+1)
		for j := start; j < end; j++ {
			if bMatched[j] || aRunes[i] != bRunes[j] {
				continue
			}
			aMatched[i], bMatched[j] = true, true
			matches++
			break
		}
	}
	if matches == 0 {
		return 0
	}
	transpositions := 0.0
	bIndex := 0
	for i := range lenA {
		if !aMatched[i] {
			continue
		}
		for !bMatched[bIndex] {
			bIndex++
		}
		if aRunes[i] != bRunes[bIndex] {
			transpositions++
		}
		bIndex++
	}
	transpositions /= 2
	matchCount := float64(matches)
	return (matchCount/float64(lenA) + matchCount/float64(lenB) + (matchCount-transpositions)/matchCount) / 3
}

// jaroWinkler returns the Jaro–Winkler similarity in [0,1]: Jaro plus a bonus for
// a shared prefix (up to 4 runes), so prefix-similar typos rank higher.
func jaroWinkler(a, b string) float64 {
	jaroScore := jaro(a, b)
	if jaroScore == 0 {
		return 0
	}
	aRunes, bRunes := []rune(a), []rune(b)
	prefixLength := 0
	for prefixLength < len(aRunes) && prefixLength < len(bRunes) && prefixLength < 4 && aRunes[prefixLength] == bRunes[prefixLength] {
		prefixLength++
	}
	const prefixScale = 0.1 // standard Winkler prefix scaling factor
	return jaroScore + float64(prefixLength)*prefixScale*(1-jaroScore)
}

// sorensenDice returns the Sørensen–Dice coefficient over rune bigrams in [0,1].
// It is weak on strings shorter than two runes (which have no bigrams).
func sorensenDice(a, b string) float64 {
	if a == b {
		return 1
	}
	aBigrams, bBigrams := bigrams(a), bigrams(b)
	if len(aBigrams) == 0 || len(bBigrams) == 0 {
		return 0
	}
	counts := make(map[string]int, len(aBigrams))
	for _, gram := range aBigrams {
		counts[gram]++
	}
	overlap := 0
	for _, gram := range bBigrams {
		if counts[gram] > 0 {
			counts[gram]--
			overlap++
		}
	}
	return 2 * float64(overlap) / float64(len(aBigrams)+len(bBigrams))
}

// jaccard returns the Jaccard index over the SET of rune bigrams in [0,1]. It is
// weak on strings shorter than two runes (which have no bigrams).
func jaccard(a, b string) float64 {
	if a == b {
		return 1
	}
	aSet, bSet := map[string]bool{}, map[string]bool{}
	for _, gram := range bigrams(a) {
		aSet[gram] = true
	}
	for _, gram := range bigrams(b) {
		bSet[gram] = true
	}
	intersection := 0
	for gram := range aSet {
		if bSet[gram] {
			intersection++
		}
	}
	union := len(aSet) + len(bSet) - intersection
	if union == 0 {
		return 0
	}
	return float64(intersection) / float64(union)
}

// bigrams returns the adjacent rune-pairs of s, in order (with repeats).
func bigrams(s string) []string {
	runes := []rune(s)
	if len(runes) < 2 {
		return nil
	}
	result := make([]string, 0, len(runes)-1)
	for i := 0; i+1 < len(runes); i++ {
		result = append(result, string(runes[i:i+2]))
	}
	return result
}

var ansiSequences = regexp.MustCompile(`\x1b\[[0-9;:?]*[\x20-\x2f]*[\x40-\x7e]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)`)

func Strip(text string) string {
	return ansiSequences.ReplaceAllString(text, "")
}

func Hyperlink(url, text string) string {
	return "\x1b]8;;" + url + "\x07" + text + "\x1b]8;;\x07"
}

// Width returns the display width of text in terminal cells: ANSI escape
// sequences contribute nothing, combining marks zero, wide East-Asian and emoji
// runes two, everything else one. It is a wcwidth-style approximation (not full
// grapheme-cluster segmentation), sufficient for aligning styled output.
func Width(text string) int {
	width := 0
	for _, r := range Strip(text) {
		width += runeWidth(r)
	}
	return width
}

func runeWidth(r rune) int {
	switch {
	case r == 0:
		return 0
	case unicode.In(r, unicode.Mn, unicode.Me, unicode.Cf):
		return 0
	case isWide(r):
		return 2
	default:
		return 1
	}
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, // Hangul Jamo
		r >= 0x2E80 && r <= 0x303E,   // CJK radicals, Kangxi
		r >= 0x3041 && r <= 0x33FF,   // Hiragana, Katakana, CJK symbols
		r >= 0x3400 && r <= 0x4DBF,   // CJK Extension A
		r >= 0x4E00 && r <= 0x9FFF,   // CJK Unified Ideographs
		r >= 0xA000 && r <= 0xA4CF,   // Yi
		r >= 0xAC00 && r <= 0xD7A3,   // Hangul Syllables
		r >= 0xF900 && r <= 0xFAFF,   // CJK Compatibility Ideographs
		r >= 0xFE30 && r <= 0xFE4F,   // CJK Compatibility Forms
		r >= 0xFF00 && r <= 0xFF60,   // Fullwidth Forms
		r >= 0xFFE0 && r <= 0xFFE6,   // Fullwidth signs
		r >= 0x1F300 && r <= 0x1FAFF, // emoji and symbols
		r >= 0x20000 && r <= 0x3FFFD: // CJK Extension B+
		return true
	default:
		return false
	}
}

// Handlers is the lifecycle interface every command's handler set
// implements. The runtime invokes the hooks in order, sharing one [Context]
// across the chain; handlers read their typed inputs with [Parser.Parse].
type Handlers interface {
	CascadingPreRun(ctx context.Context, rtx *Context)
	PreRun(ctx context.Context, rtx *Context)
	Run(ctx context.Context, rtx *Context)
	PostRun(ctx context.Context, rtx *Context)
	CascadingPostRun(ctx context.Context, rtx *Context)
}

// Definition is the compiled command tree for a generated rotini program. The
// framework package (rtg) emits it as a Go literal and the rollup passes it to
// [NewProgram]; the runtime uses it to parse argv, dispatch, and render help and
// completion. It is data only — behavior lives in the handlers.
type Definition struct {
	Name             string
	Handler          string // ProgramHandlers method for the root command, e.g. "Rotini"
	Flags            []FlagDef
	Arguments        []ArgDef
	FlagGroups       []FlagGroup      // cross-flag presence rules validated at parse time
	FlagDependencies []FlagDependency // conditional cross-flag requirements validated at parse time
	Commands         []CommandDef
	RemoteCommands   []RemoteDef         // co-located plugin sub-commands (Model 3)
	Discovery        *RemoteDiscoveryDef // plugin auto-discovery on the root command (nil = off)
	Passthrough      bool                // every token after the program name is a raw positional (no flag parsing)
}

// FlagGroupKind names a cross-flag presence rule. The value is the spec's `kind`.
type FlagGroupKind string

const (
	// FlagGroupMutuallyExclusive: at most one of the group's flags may be set.
	FlagGroupMutuallyExclusive FlagGroupKind = "mutually_exclusive"
	// FlagGroupRequiredTogether: set all of the group's flags, or none.
	FlagGroupRequiredTogether FlagGroupKind = "required_together"
	// FlagGroupOneOf: exactly one of the group's flags must be set.
	FlagGroupOneOf FlagGroupKind = "one_of"
	// FlagGroupAtLeastOne: at least one of the group's flags must be set.
	FlagGroupAtLeastOne FlagGroupKind = "at_least_one"
)

// FlagGroup is a constraint on which of a command's flags may (or must) appear
// together on the command line. Flags are referenced by their logical Name; "set"
// means explicitly provided on argv (a default or env/config fallback does not count,
// matching the convention of cobra/clap). Enforced by the [Parser]; a violation is
// a usage error.
type FlagGroup struct {
	Kind  FlagGroupKind
	Flags []string // logical flag names that make up the group
}

// FlagDependency is a conditional cross-flag requirement: when the When flag is
// explicitly set on argv, every flag in Requires must also be set. Flags are referenced
// by their logical Name and "set" follows the same explicit-argv convention as
// [FlagGroup]. Enforced by the [Parser]; a violation is a usage error.
type FlagDependency struct {
	When     string   // the flag whose presence triggers the requirement
	Requires []string // flags that must also be set when When is set
}

// RemoteDef describes a remote/co-located sub-command (kubectl/git plugin
// style): invoking it execs the sibling binary Binary, passing through the
// remaining arguments.
type RemoteDef struct {
	Name    string
	Aliases []string
	Summary string        // one-line description (completion candidates carry it as "name\tsummary")
	Binary  string        // expected executable name, e.g. "kubectl-ctx"
	Timeout time.Duration // 0 means no timeout
}

// BindMeta is the generated, data-only descriptor the default binder ([Binder])
// consumes to fill the non-argv input channels. It carries document-level concerns
// that the dispatch-time Definition deliberately omits. The rtg package emits it as
// `var BindMeta = rotini.BindMeta{…}`; main.go passes it to [NewBinder].
type BindMeta struct {
	ConfigFiles []ConfigFile // per-command config_files sources, each tagged with its Scope; the binder scopes them to the invoked chain (cascade, nearest-wins)
	// EnvPrefix scopes every DERIVED env-var name (the SNAKE_UPPER projections:
	// plain env inputs without variable:, envnest bases, flags' env fallbacks)
	// under "<EnvPrefix>_". Explicit variable: names are exempt, and with a
	// prefix set the unprefixed conventional names no longer bind. The spec's
	// document-level env_prefix; "" = no prefix (the default projection).
	EnvPrefix string
	// Sources are custom recon sources (a secrets manager, a remote config
	// service — anything implementing recon.Source) joined into the Binder's
	// config precedence AFTER the declared configuration_files: explicit
	// files beat ambient services; custom sources beat nothing. Appended by
	// the program's own code (conventionally main.go: meta := cli.BindMeta;
	// meta.Sources = append(meta.Sources, vaultSource) — codegen never
	// emits one), they serve config inputs and flags' config fallbacks
	// alike. Per-input `file:` pins stay configuration_files anchors and
	// cannot name a custom source. Source names must not collide with
	// declared file names — the registry rejects duplicates loudly.
	Sources []recon.Source
	// StdinSchemas maps a command's stdin payload type name ("<Prefix>Stdin") to a
	// self-contained JSON Schema the binder validates the decoded payload against.
	StdinSchemas map[string]string
}

// ConfigFile is one configuration-file source the binder reads (reconciled by recon).
// Exactly one of Path and Discover locates the file (the spec enforces this).
type ConfigFile struct {
	Name string // logical name
	// Scope is the command path ("root", "root/sub", …) this source is declared
	// on. config_files cascade: a source is in scope for the invoked chain when
	// its Scope is one of the chain's commands (D-W3.1). "" means UNSCOPED — in
	// scope for every command (a manually-built BindMeta or a legacy global list);
	// generated descriptors always set it.
	Scope    string
	Path     string       // fixed file path (may contain ~)
	Format   string       // "json" | "yaml" | "toml"; "" lets the binder infer from the extension
	Discover *DiscoverDef // run-time location strategy, instead of a fixed Path
	PathFrom *PathFromDef // runtime inputs that supply/override the path (spec config_source)
	// Schema is the self-contained JSON Schema the binder validates the loaded
	// document against at bind time (the spec entry's `schema:`); "" = none.
	// The file that actually resolved — fixed, discovered, or
	// config_source-supplied — is the file validated; an absent optional file
	// passes vacuously.
	Schema string
}

// PathFromDef names the runtime inputs that supply a [ConfigFile]'s path (the
// spec's config_source) — the declarative two-phase parse: argv and env are
// read first, then the file channel opens whatever they pointed at. The path
// precedence is: the flag explicitly set on argv, then the env variable, then
// the flag's declared default, then the entry's own path/discover. A path
// supplied this way must exist — the user explicitly asked for it.
type PathFromDef struct {
	Flag string // logical flag name searched across the resolved chain
	Env  string // environment variable read directly
}

// DiscoverDef locates a configuration file at run time (the spec's discover:).
// The strategy orders the directories searched for File; the first directory
// containing it wins, and a file found nowhere is simply absent.
type DiscoverDef struct {
	Strategy string // "walk-up" (working directory up to the filesystem root) | "xdg" ($XDG_CONFIG_HOME/<app>, default ~/.config/<app>)
	File     string // the file name looked for in each searched directory
	App      string // the application directory under the XDG config root (xdg only)
}

// RemoteDiscoveryDef enables kubectl/git/gh-style plugin discovery on a command:
// an unmatched token execs the sibling binary Prefix+<token>, and `<Prefix>*`
// executables are offered as completion candidates (unless Hidden). A nil
// *RemoteDiscoveryDef means discovery is off for that command.
type RemoteDiscoveryDef struct {
	Prefix string // executable-name prefix, e.g. "acme-"
	Path   string // extra directory to scan, in addition to the host dir and PATH
	Hidden bool   // dispatch discovered plugins but omit them from completion listings
}

// CommandDef describes one command node within a [Definition]. Handler is the
// ProgramHandlers method name the runtime invokes (via reflection) to obtain
// this command's [Handlers].
type CommandDef struct {
	Name                  string
	Aliases               []string
	Summary               string   // one-line description (completion candidates carry it as "name\tsummary")
	Handler               string   // ProgramHandlers method, e.g. "RotiniGenerate"
	Hidden                bool     // omitted from completion candidates (it still dispatches); help omission happens at codegen
	DeprecatedIdentifiers []string // aliases (subset of Aliases) that [Parser.Deprecations] reports when used to invoke
	Flags                 []FlagDef
	Arguments             []ArgDef
	FlagGroups            []FlagGroup      // cross-flag presence rules validated at parse time
	FlagDependencies      []FlagDependency // conditional cross-flag requirements validated at parse time
	Commands              []CommandDef
	Remotes               []RemoteDef         // co-located remote binaries dispatched as sub-commands of this command
	Discovery             *RemoteDiscoveryDef // plugin auto-discovery on this command (nil = off)
	Passthrough           bool                // every token after this command is a raw positional (no flag parsing)
}

// Constraints carries the optional JSON-schema-style validation bounds a spec may
// declare on a flag or argument; the parser enforces them after reconciliation (so a
// value supplied via env/config is checked too). The numeric bounds are
// presence-carrying pointers — nil means "unset", so `minimum: 0` is a real,
// enforced bound ([Ptr] builds one in a hand-authored Definition). The
// length/count bounds keep the zero-sentinel convention: a 0 minimum is
// vacuous, and a 0 maximum is not expressible (no real-world demand recorded).
type Constraints struct {
	Minimum          *float64 // inclusive numeric lower bound; nil = unset
	Maximum          *float64 // inclusive numeric upper bound; nil = unset
	ExclusiveMinimum *float64 // strict numeric lower bound (value must be >); nil = unset
	ExclusiveMaximum *float64 // strict numeric upper bound (value must be <); nil = unset
	MultipleOf       *float64 // the value must be an integer multiple (strictly positive); nil = unset
	MinLength        int      // minimum string length in runes; 0 = unset
	MaxLength        int      // maximum string length in runes; 0 = unset
	MinItems         int      // minimum item count (repeatable flag / variadic argument); 0 = unset
	MaxItems         int      // maximum item count; 0 = unset
	Pattern          string   // regular expression the value must contain (string types); "" = unset
}

// Ptr returns a pointer to v — sugar for the presence-carrying [Constraints]
// bounds in a hand-authored [Definition] (generated code uses it too):
// Constraints{Minimum: rotini.Ptr(0.0)} declares an enforced >= 0.
//
//go:fix inline
func Ptr[T any](v T) *T { return new(v) }

// takesValue reports whether a flag consumes a value token: everything except
// the presence flags — bool (value form is inline-only) and count (no value at
// all; each occurrence increments the generated int field).
func takesValue(fd FlagDef) bool { return fd.Type != "bool" && fd.Type != "count" }

// FlagDef describes a single flag of a command. Name is the logical name and
// matches the `rotini:"<name>"` tag on the corresponding generated input field.
type FlagDef struct {
	Name                  string
	Identifiers           []string // CLI forms, e.g. {"--loud", "-l"}
	Summary               string   // one-line description (completion candidates carry it as "identifier\tsummary")
	Type                  string   // resolved Go type, e.g. "bool", "string", "[]string", "int", "time.Duration"
	Required              bool
	Default               string
	Enum                  []string
	Secret                bool     // when true, the value is redacted in usage/validation error output
	Hidden                bool     // omitted from completion candidates (it still parses); help omission happens at codegen
	DeprecatedIdentifiers []string // identifiers (subset of Identifiers) that [Parser.Deprecations] reports when used
	DottedKeys            bool     // map flag whose key=value keys are '.'-separated paths into nested maps (spec dotted_keys)
	KeyPaths              []string // a map flag's declared key paths (from its schema's properties), completed up to the '='
	From                  []string // extra acquisition modes (spec from:): "file" resolves @path values, "stdin" resolves a bare "-"
	Constraints
}

// ArgDef describes a single positional argument of a command. Variadic is true
// for a trailing slice argument that absorbs the remaining positionals.
type ArgDef struct {
	Name     string
	Type     string
	Required bool
	Variadic bool
	Default  string
	Enum     []string
	Secret   bool // when true, the value is redacted in usage/validation error output
	Hidden   bool // omitted from completion candidates (it still parses); help omission happens at codegen
	Constraints
}

const (
	KeyVersioner = "versioner"
)

var (
	readBuildInfo     = debug.ReadBuildInfo
	semanticVersionRe = regexp.MustCompile(`^v?(\d+\.\d+\.\d+)`)
)

// Versioner carries the program's version in the two forms handlers print:
// the full module/ldflag string and its leading semantic X.Y.Z. It is a bound
// service like the parser — the generated main constructs one with
// [NewVersioner] and binds it under [KeyVersioner] for the version handler.
type Versioner struct {
	Version         string // the version as reported: the module's build info, else the ldflag value (i.e. the program's own version variable)
	VersionSemantic string // the leading X.Y.Z of Version (any v prefix stripped); "0.0.0" when Version carries none, so it is always a valid semver
}

// NewVersioner resolves the program's version: the module's build info when it
// carries a release version (a go install / go get -tool build), otherwise
// ldflagVersion — the value baked in via -ldflags "-X main.version=…", or the
// program's own default for that variable when no ldflag was applied. The
// framework imposes no fallback of its own; the ultimate default is whatever the
// program set its version variable to.
func NewVersioner(ldflagVersion string) *Versioner {
	version := ldflagVersion
	if info, ok := readBuildInfo(); ok && info.Main.Version != "" && info.Main.Version != "(devel)" {
		version = info.Main.Version
	}

	v := &Versioner{Version: version, VersionSemantic: "0.0.0"}
	if match := semanticVersionRe.FindStringSubmatch(version); match != nil {
		v.VersionSemantic = match[1]
	}
	return v
}
